  'async__closure.py':
      "# run-async\n# Async function capturing variables from enclosing scope\n\n\ndef make_adder(n):\n    async def adder(x):\n        return x + n\n\n    return adder\n\n\nadd_five = make_adder(5)\nresult = await add_five(10)  # pyright: ignore\nassert result == 15\n",
