  'async__exception.py':
      "# run-async\n# Test that exceptions in async functions propagate correctly\n\n\nasync def raises_error():\n    raise ValueError('async error')\n\n\nawait raises_error()  # pyright: ignore\n# Raise=ValueError('async error')\n",
  'async__ext_call.py':
      "# call-external\n# run-async\n# Test async external function calls (coroutines)\n\n# === Basic async external call ===\nresult = await async_call(42)  # pyright: ignore\nassert result == 42\n\n# === Async call with string ===\ns = await async_call('hello')  # pyright: ignore\nassert s == 'hello'\n\n# === Async call with list ===\nlst = await async_call([1, 2, 3])  # pyright: ignore\nassert lst == [1, 2, 3]\n\n# === Multiple async calls ===\na = await async_call(10)  # pyright: ignore\nb = await async_call(20)  # pyright: ignore\nassert a + b == 30\n\n# === Gather multiple external async calls ===\nimport asyncio\n\nresults = await asyncio.gather(async_call(1), async_call(2), async_call(3))  # pyright: ignore\nassert results == [1, 2, 3]\n\n# === Gather with mixed external calls ===\nresults = await asyncio.gather(async_call('a'), async_call('b'))  # pyright: ignore\nassert results == ['a', 'b']\n\n\n# === Gather mixing coroutines and external futures ===\nasync def add(a, b):\n    return a + b\n\n\nasync def multiply(a, b):\n    return a * b\n\n\n# Mix: coroutine first, external future second\nresults = await asyncio.gather(add(1, 2), async_call(10))  # pyright: ignore\nassert results == [3, 10]\n\n# Mix: external future first, coroutine second\nresults = await asyncio.gather(async_call(20), multiply(3, 4))  # pyright: ignore\nassert results == [20, 12]\n\n# Mix: multiple of each interleaved\nresults = await asyncio.gather(add(5, 5), async_call('x'), multiply(2, 3), async_call('y'))  # pyright: ignore\nassert results == [10, 'x', 6, 'y']\n\n\n# === Coroutine with nested external awaits ===\nasync def double_external(x):\n    val = await async_call(x)\n    return val * 2\n\n\nresults = await asyncio.gather(double_external(5), async_call(100))  # pyright: ignore\nassert results == [10, 100]\n\n\n# === Coroutine with multiple nested awaits ===\nasync def triple_add(a, b, c):\n    x = await async_call(a)\n    y = await async_call(b)\n    return x + y + c\n\n\nresults = await asyncio.gather(triple_add(1, 2, 3), async_call(50))  # pyright: ignore\nassert results == [6, 50]\n\n\n# === Gather with the same external future passed twice ===\nf = async_call(7)\nresults = await asyncio.gather(f, f)  # pyright: ignore\nassert results == [7, 7], f'duplicate external future dedup: {results}'\n\n# Mixed with unique external futures around the duplicate.\ng = async_call('dup')\nresults = await asyncio.gather(async_call('a'), g, async_call('b'), g)  # pyright: ignore\nassert results == ['a', 'dup', 'b', 'dup'], f'mixed external future dedup: {results}'\n\n\n# === Same external future shared across sibling gathers ===\n# Two concurrent helpers each await their own gather around the SAME external\n# future. In Monty the future is still `Pending` at this point so the second\n# gather sees the awaiter slot already taken and raises RuntimeError. In\n# CPython the test harness now returns an already-resolved `asyncio.Future`,\n# which permits multi-await, so both gathers settle with `[99]`. Both\n# outcomes are accepted as they reflect a genuine semantic difference (Monty\n# rejects concurrent awaiters on a `Pending` future; multi-awaiter on\n# `Pending` is a planned follow-up).\nasync def helper(future):\n    return await asyncio.gather(future)\n\n\nshared = async_call(99)\ntry:\n    result = await asyncio.gather(helper(shared), helper(shared))  # pyright: ignore\n    assert result == [[99], [99]], f'CPython multi-await of resolved future: {result}'\nexcept RuntimeError as e:\n    assert str(e) == 'cannot reuse already awaited future', f'Monty rejection: {e}'\n\n\n# === Re-awaiting a resolved external future returns the cached value ===\n\nreawait_f = async_call('cached')\nfirst = await reawait_f  # pyright: ignore\nsecond = await reawait_f  # pyright: ignore\nthird = await reawait_f  # pyright: ignore\nassert first == 'cached', f'first await: {first}'\nassert second == 'cached', f'second await: {second}'\nassert third == 'cached', f'third await: {third}'\n\nreawait_list = async_call([1, 2, 3])\nfirst_list = await reawait_list  # pyright: ignore\nsecond_list = await reawait_list  # pyright: ignore\nassert first_list is second_list\nfirst_list.append(99)\nassert second_list == [1, 2, 3, 99]\n",
  'async__ext_exc.py':
      "# call-external\n# run-async\n# === Async external function exceptions ===\n# Tests for exceptions raised by awaited external async functions. Mirrors\n# `ext_call__ext_exc.py` section-by-section via `async_fail`, then appends\n# async-specific call shapes (asyncio.gather, user-defined async wrappers,\n# gathered coroutines).\nimport asyncio\n\n# === Basic exception propagation ===\n\n# External function raising ValueError\ncaught_value_error = False\ntry:\n    await async_fail('ValueError', 'test error')  # pyright: ignore\n    assert False, 'should not reach here'\nexcept ValueError:\n    caught_value_error = True\nassert caught_value_error\n\n# External function raising TypeError\ncaught_type_error = False\ntry:\n    await async_fail('TypeError', 'type error message')  # pyright: ignore\n    assert False, 'should not reach here'\nexcept TypeError:\n    caught_type_error = True\nassert caught_type_error\n\n# External function raising KeyError\ncaught_key_error = False\ntry:\n    await async_fail('KeyError', 'missing key')  # pyright: ignore\n    assert False, 'should not reach here'\nexcept KeyError:\n    caught_key_error = True\nassert caught_key_error\n\n# External function raising RuntimeError\ncaught_runtime_error = False\ntry:\n    await async_fail('RuntimeError', 'runtime error')  # pyright: ignore\n    assert False, 'should not reach here'\nexcept RuntimeError:\n    caught_runtime_error = True\nassert caught_runtime_error\n\n# === Exception not caught by wrong handler ===\n\n# ValueError not caught by TypeError handler\ncaught_outer = False\ntry:\n    try:\n        await async_fail('ValueError', 'inner error')  # pyright: ignore\n    except TypeError:\n        assert False, 'TypeError should not catch ValueError'\nexcept ValueError:\n    caught_outer = True\nassert caught_outer\n\n# === Exception in expression with multiple ext calls ===\n\n# Awaited external call raises mid-expression — surrounding ops don't run\ntry:\n    x = 1 + (await async_fail('ValueError', 'mid-expr')) + 2  # pyright: ignore\n    assert False, 'should not reach here'\nexcept ValueError:\n    pass  # Expected\n\n# First ext call raises, second should not be called\ntry:\n    x = (await async_fail('ValueError', 'first')) + add_ints(1, 2)  # pyright: ignore\n    assert False, 'should not reach here'\nexcept ValueError:\n    pass  # Expected\n\n# === External exception in try body with finally ===\n\nfinally_ran = False\ntry:\n    await async_fail('ValueError', 'in try')  # pyright: ignore\nexcept ValueError:\n    pass  # Caught\nfinally:\n    finally_ran = True\nassert finally_ran\n\n# External exception propagating through finally\nouter_caught = False\nfinally_ran2 = False\ntry:\n    try:\n        await async_fail('KeyError', 'will propagate')  # pyright: ignore\n    except ValueError:\n        assert False, 'ValueError should not catch KeyError'\n    finally:\n        finally_ran2 = True\nexcept KeyError:\n    outer_caught = True\nassert finally_ran2\nassert outer_caught\n\n# === Mix of normal returns and exceptions ===\n\n# Normal return, then exception\nvalue1 = await async_call(30)  # pyright: ignore\nassert value1 == 30\ntry:\n    await async_fail('ValueError', 'after success')  # pyright: ignore\n    assert False, 'should not reach here'\nexcept ValueError:\n    pass  # Expected\n\n# Exception, then normal return (after catching)\ncaught_exc = False\ntry:\n    await async_fail('TypeError', 'will be caught')  # pyright: ignore\nexcept TypeError:\n    caught_exc = True\nvalue2 = await async_call(10)  # pyright: ignore\nassert caught_exc\nassert value2 == 10\n\n# === Exception in except handler from external function ===\n\nouter_catch = False\ntry:\n    try:\n        raise ValueError('inner')\n    except ValueError:\n        await async_fail('TypeError', 'from handler')  # pyright: ignore\nexcept TypeError:\n    outer_catch = True\nassert outer_catch\n\n# === Exception in else block from external function ===\n\nelse_exc_caught = False\ntry:\n    try:\n        pass  # No exception\n    except:\n        assert False, 'should not reach except'\n    else:\n        await async_fail('RuntimeError', 'from else')  # pyright: ignore\nexcept RuntimeError:\n    else_exc_caught = True\nassert else_exc_caught\n\n# === Exception in finally block ===\n\n# Note: exception in finally replaces any pending exception\nfinally_exc_caught = False\ntry:\n    try:\n        pass\n    finally:\n        await async_fail('ValueError', 'from finally')  # pyright: ignore\nexcept ValueError:\n    finally_exc_caught = True\nassert finally_exc_caught\n\n# === Nested try blocks with external exceptions ===\n\ninner_handled = False\nouter_handled = False\nfinally_count = 0\ntry:\n    try:\n        await async_fail('ValueError', 'inner error')  # pyright: ignore\n    except ValueError:\n        inner_handled = True\n        await async_fail('TypeError', 'from inner handler')  # pyright: ignore\n    finally:\n        finally_count += 1\nexcept TypeError:\n    outer_handled = True\nfinally:\n    finally_count += 1\n\nassert inner_handled\nassert outer_handled\nassert finally_count == 2\n\n# === Tests with no sync counterpart in `ext_call__ext_exc.py`. ===\n\n# === Exception message is preserved across async boundary ===\ntry:\n    await async_fail('ValueError', 'exact message')  # pyright: ignore\n    assert False, 'should not reach here'\nexcept ValueError as e:\n    assert str(e) == 'exact message', f'message preserved through await: {e}'\n\n\n# === Bare raise re-raises across an async frame boundary ===\nasync def wrapper_rereraise():\n    try:\n        await async_fail('ValueError', 're-raised')\n    except ValueError:\n        raise\n\n\nouter_reraised = False\ntry:\n    await wrapper_rereraise()  # pyright: ignore\nexcept ValueError as e:\n    assert str(e) == 're-raised'\n    outer_reraised = True\nassert outer_reraised\n\n\n# === Exception unwinds through user-defined async wrapper ===\nasync def wrapper_catches():\n    try:\n        await async_fail('ValueError', 'inside wrapper')\n        return 'no error'\n    except ValueError as e:\n        return 'caught: ' + str(e)\n\n\nwrapper_result = await wrapper_catches()  # pyright: ignore\nassert wrapper_result == 'caught: inside wrapper', f'caught inside async wrapper: {wrapper_result}'\n\n\n# === Exception unwinds through multiple async wrapper frames ===\nasync def inner_wrapper():\n    await async_fail('ValueError', 'deep')\n\n\nasync def outer_wrapper():\n    await inner_wrapper()\n\n\nnested_caught = None\ntry:\n    await outer_wrapper()  # pyright: ignore\nexcept ValueError as e:\n    nested_caught = str(e)\nassert nested_caught == 'deep'\n\n# === asyncio.gather: failure propagates out ===\ncaught_gather = None\ntry:\n    await asyncio.gather(async_call(1), async_fail('ValueError', 'gather failure'))  # pyright: ignore\nexcept ValueError as e:\n    caught_gather = str(e)\nassert caught_gather == 'gather failure'\n\n\n# === Gathered coroutine: child failure surfaces at the main task's gather ===\nasync def get_a():\n    return await async_fail('ValueError', 'async boom')\n\n\nasync def get_b():\n    return await async_call('b')\n\n\ngathered_coro_caught = None\ntry:\n    await asyncio.gather(get_a(), get_b())  # pyright: ignore\nexcept ValueError as e:\n    gathered_coro_caught = str(e)\nassert gathered_coro_caught == 'async boom', f'gathered child exception caught at gather: {gathered_coro_caught}'\n\n\n# === Re-awaiting a failed external future re-raises the cached error ===\n\nreawait_fail = async_fail('ValueError', 'cached failure')\nerrors = []\nfor _ in range(3):\n    try:\n        await reawait_fail  # pyright: ignore\n        assert False, 'await of failed future should raise'\n    except ValueError as e:\n        errors.append(str(e))\nassert errors == ['cached failure', 'cached failure', 'cached failure'], (\n    f'each re-await of a failed future replays the cached error: {errors}'\n)\n",
  'async__gather_all.py':
      "# run-async\nimport asyncio\n\n\n# === Basic gather ===\nasync def task1():\n    return 1\n\n\nasync def task2():\n    return 2\n\n\nresult = await asyncio.gather(task1(), task2())  # pyright: ignore\nassert result == [1, 2]\n\n\n# === Result ordering ===\n# Results should be in argument order, not completion order\nasync def slow():\n    return 'slow'\n\n\nasync def fast():\n    return 'fast'\n\n\nresult = await asyncio.gather(slow(), fast())  # pyright: ignore\nassert result == ['slow', 'fast']\n\n# === Empty gather ===\nresult = await asyncio.gather()  # pyright: ignore\nassert result == []\n\n\n# === Single coroutine ===\nasync def single():\n    return 42\n\n\nresult = await asyncio.gather(single())  # pyright: ignore\nassert result == [42]\n\n# === repr of gather function ===\nr = repr(asyncio.gather)\nassert r.startswith('<function gather at 0x'), f'repr should start with: {r}'\n\n# === TypeError for non-awaitable argument ===\ntry:\n    await asyncio.gather(123)  # pyright: ignore\n    assert False, 'should have raised TypeError'\nexcept TypeError as e:\n    assert str(e) == 'An asyncio.Future, a coroutine or an awaitable is required'\n\n\n# === *args unpacking with gather ===\nasync def a():\n    return 'a'\n\n\nasync def b():\n    return 'b'\n\n\nasync def c():\n    return 'c'\n\n\n# Unpack a list of coroutines\ncoros = [a(), b(), c()]\nresult = await asyncio.gather(*coros)  # pyright: ignore\nassert result == ['a', 'b', 'c'], f'gather with *args unpacking: {result}'\n\n# Unpack with mixed args\nresult = await asyncio.gather(a(), *[b(), c()])  # pyright: ignore\nassert result == ['a', 'b', 'c'], f'gather with mixed args and *unpacking: {result}'\n\n# Unpack empty list\nresult = await asyncio.gather(*[])  # pyright: ignore\nassert result == [], f'gather with empty *args: {result}'\n\n# Unpack tuple\ncoro_tuple = (a(), b())\nresult = await asyncio.gather(*coro_tuple)  # pyright: ignore\nassert result == ['a', 'b'], f'gather with *tuple unpacking: {result}'\n\n\n# === gather with the same coroutine passed twice ===\ndup_runs = [0]\n\n\nasync def dup():\n    dup_runs[0] += 1\n    return 1\n\n\ndup_coro = dup()\nresult = await asyncio.gather(dup_coro, dup_coro)  # pyright: ignore\nassert result == [1, 1], f'expected [1, 1], got {result}'\nassert dup_runs[0] == 1, f'coroutine body should run once, ran {dup_runs[0]} times'\n\n\n# Three duplicates and a mix of duplicates with a unique coroutine.\nasync def dup3():\n    return 'x'\n\n\ndup3_coro = dup3()\nresult = await asyncio.gather(dup3_coro, dup3_coro, dup3_coro)  # pyright: ignore\nassert result == ['x', 'x', 'x'], f'expected three xs, got {result}'\n\n\nasync def alpha():\n    return 'a'\n\n\nasync def beta():\n    return 'b'\n\n\na_coro = alpha()\nb_coro = beta()\nresult = await asyncio.gather(a_coro, b_coro, a_coro)  # pyright: ignore\nassert result == ['a', 'b', 'a'], f'mixed dedup: expected [a, b, a], got {result}'\n\n\n# === gather with an already-awaited coroutine raises RuntimeError ===\nasync def already():\n    return 1\n\n\nalready_coro = already()\nawait already_coro  # pyright: ignore\ntry:\n    await asyncio.gather(already_coro)  # pyright: ignore\n    assert False, 'should have raised RuntimeError'\nexcept RuntimeError as e:\n    assert str(e) == 'cannot reuse already awaited coroutine', f'unexpected error: {e}'\n\n\n# === Re-awaiting a completed gather returns the cached result list ===\n# CPython's _GatheringFuture is a Future that stores its result; every await\n# returns the same list. Monty caches the result on the GatherFuture so this\n# matches.\n\n\nasync def reawait_member():\n    return 7\n\n\ng = asyncio.gather(reawait_member(), reawait_member())\nfirst = await g  # pyright: ignore\nsecond = await g  # pyright: ignore\nthird = await g  # pyright: ignore\nassert first == [7, 7], f'first await: {first}'\nassert second == [7, 7], f'second await: {second}'\nassert third == [7, 7], f'third await: {third}'\n# Identity: every re-await yields the same list object (CPython behavior).\nassert first is second\nassert second is third\n\n\n# === Re-awaiting an empty gather returns the same empty list ===\ng_empty = asyncio.gather()\ne1 = await g_empty  # pyright: ignore\ne2 = await g_empty  # pyright: ignore\nassert e1 == [] and e2 == [], 'empty gather re-await: both empty'\nassert e1 is e2\n\n\n# === Re-awaiting a failed gather re-raises the same exception ===\n\n\nasync def boom():\n    raise ValueError('detonate')\n\n\ng_fail = asyncio.gather(boom())\ntry:\n    await g_fail  # pyright: ignore\n    assert False, 'first await should have raised'\nexcept ValueError as e:\n    assert str(e) == 'detonate', f'first await message: {e}'\n\ntry:\n    await g_fail  # pyright: ignore\n    assert False, 'second await should have raised'\nexcept ValueError as e:\n    assert str(e) == 'detonate', f'second await message: {e}'\n\ntry:\n    await g_fail  # pyright: ignore\n    assert False, 'third await should have raised'\nexcept ValueError as e:\n    assert str(e) == 'detonate', f'third await message: {e}'\n\n\n# === Nested gather ===\n\nnested_1 = asyncio.gather(task1(), task1())\nnested_2 = asyncio.gather(nested_1, nested_1)\n\nassert await nested_2 == [[1, 1], [1, 1]]  # pyright: ignore\n",
  'async__gather_commit_rollback.py':
      "# run-async\n\"\"\"Gather failure must clean up committed siblings and nested failures.\"\"\"\n\nimport asyncio\n\n\n# === Commit-time orphan: Failed nested gather is the second item ===\n# Outer spawns slow() first, then hits `g_failed` which raises synchronously.\n# Rollback must cancel slow()'s task.\nasync def boom_orphan():\n    raise ValueError('boom')\n\n\nasync def slow_orphan():\n    return 'slow ok'\n\n\ng_failed = asyncio.gather(boom_orphan())\ntry:\n    await g_failed  # pyright: ignore\n    assert False, 'g_failed should have raised'\nexcept ValueError as e:\n    assert str(e) == 'boom', f'first await: {e}'\n\ntry:\n    await asyncio.gather(slow_orphan(), g_failed)  # pyright: ignore\n    assert False, 'reuse of failed gather should raise'\nexcept ValueError as e:\n    assert str(e) == 'boom', f'second await: {e}'\n\n# If `slow_orphan`'s task was orphaned, this later gather would trip stale\n# scheduler state.\nresult_after_orphan = await asyncio.gather(slow_orphan())  # pyright: ignore\nassert result_after_orphan == ['slow ok'], f'post-orphan gather: {result_after_orphan}'\n\n\n# === Double-fail: nested gather whose only child raises ===\n# The outer failure walk must not re-fail an inner gather that already failed.\nasync def boom_double_fail():\n    raise ValueError('double-fail err')\n\n\nasync def double_fail_main():\n    await asyncio.gather(asyncio.gather(boom_double_fail()))\n\n\ntry:\n    await double_fail_main()  # pyright: ignore\n    assert False, 'double_fail_main should have raised'\nexcept ValueError as e:\n    assert str(e) == 'double-fail err', f'double-fail error: {e}'\n\n\n# === Three-deep nested gather with the deepest child raising ===\n# Failure walks up two GatherSlot links; both ancestors must skip the inner\n# gather that already failed.\nasync def boom_triple():\n    raise ValueError('triple')\n\n\nasync def triple_main():\n    await asyncio.gather(asyncio.gather(asyncio.gather(boom_triple())))\n\n\ntry:\n    await triple_main()  # pyright: ignore\n    assert False, 'triple_main should have raised'\nexcept ValueError as e:\n    assert str(e) == 'triple', f'triple-nested error: {e}'\n\n\n# === Sibling-failure-with-orphan: outer has nested-gather + coroutine ===\n# One inner child raises and propagates upward while the outer sibling has\n# already committed. Teardown must cancel that sibling and skip the failed inner.\nasync def boom_a():\n    raise NotImplementedError('a')\n\n\nasync def boom_b():\n    raise NotImplementedError('b')\n\n\nasync def ext_c():\n    raise NotImplementedError('c')\n\n\nasync def sibling_main():\n    inner = asyncio.gather(boom_a(), boom_b())\n    outer = asyncio.gather(inner, ext_c())\n    try:\n        await outer\n        assert False, 'sibling_main should have raised'\n    except NotImplementedError as e:\n        # Any committed sibling may win before teardown reaches the rest.\n        assert str(e) in ('a', 'b', 'c'), f'sibling error: {e}'\n\n\nawait sibling_main()  # pyright: ignore\n\n\n# === Rolled-back gather caches the error: re-await replays it ===\n# Re-awaiting a rolled-back gather must replay the cached error.\nasync def boom_replay():\n    raise ValueError('replay')\n\n\nasync def slow_replay():\n    return 1\n\n\ng_replay = asyncio.gather(boom_replay())\ntry:\n    await g_replay  # pyright: ignore\nexcept ValueError:\n    pass\n\nouter_replay = asyncio.gather(slow_replay(), g_replay)\ntry:\n    await outer_replay  # pyright: ignore\n    assert False, 'first outer_replay should raise'\nexcept ValueError as e:\n    assert str(e) == 'replay', f'first outer_replay: {e}'\n\n# Second await on the same outer gather instance — must replay, not retry.\ntry:\n    await outer_replay  # pyright: ignore\n    assert False, 'second outer_replay should raise'\nexcept ValueError as e:\n    assert str(e) == 'replay', f'second outer_replay: {e}'\n\n\n# === Cross-gather double-spawn rollback works mid-tree ===\n# Cross-gather coroutine reuse must also roll back siblings committed before\n# the duplicate spawn is detected.\nasync def make_payload():\n    return 'payload'\n\n\nc_shared = make_payload()\ng_share_1 = asyncio.gather(c_shared)\ng_share_2 = asyncio.gather(c_shared)\ntry:\n    await asyncio.gather(g_share_1, g_share_2)  # pyright: ignore\n    assert False, 'shared-coroutine outer gather should raise'\nexcept RuntimeError as e:\n    assert str(e) == 'cannot reuse already awaited coroutine', f'cross-gather: {e}'\n\n# Heap/scheduler still usable.\nfinal = await asyncio.gather(make_payload(), make_payload())  # pyright: ignore\nassert final == ['payload', 'payload'], f'final gather: {final}'\n",
  'async__gather_double_spawn.py':
      "# run-async\n\"\"\"Cross-gather coroutine reuse must raise `RuntimeError`, not panic.\"\"\"\n\nimport asyncio\n\n\n# === Canonical: g1 = gather(c); g2 = gather(c); await gather(g1, g2) ===\nasync def foo_canonical():\n    return [1, 2, 3]\n\n\nasync def main_canonical():\n    c = foo_canonical()\n    g1 = asyncio.gather(c)\n    g2 = asyncio.gather(c)\n    try:\n        await asyncio.gather(g1, g2)\n        assert False, 'cross-gather reuse should have raised RuntimeError'\n    except RuntimeError as e:\n        assert str(e) == 'cannot reuse already awaited coroutine', f'canonical: unexpected error: {e}'\n\n\nawait main_canonical()  # pyright: ignore\n\n\n# === Nested: gather(gather(c), gather(c)) ===\n# Same shape, simpler driver — no `main()` wrapper, no intermediate references.\nasync def foo_nested():\n    return 1\n\n\nc_nested = foo_nested()\ntry:\n    await asyncio.gather(asyncio.gather(c_nested), asyncio.gather(c_nested))  # pyright: ignore\n    assert False, 'nested cross-gather reuse should have raised RuntimeError'\nexcept RuntimeError as e:\n    assert str(e) == 'cannot reuse already awaited coroutine', f'nested: unexpected error: {e}'\n\n\n# === Sequential: g1 = gather(c); g2 = gather(c); await g1; await g2 ===\n# CPython: `await g1` resolves successfully with `[result]`; `await g2` raises\n# because the coroutine was already driven by g1.\nasync def foo_seq():\n    return 42\n\n\nc_seq = foo_seq()\ng1_seq = asyncio.gather(c_seq)\ng2_seq = asyncio.gather(c_seq)\nr1_seq = await g1_seq  # pyright: ignore\nassert r1_seq == [42], f'sequential g1 should resolve to [42], got {r1_seq}'\ntry:\n    await g2_seq  # pyright: ignore\n    assert False, 'sequential g2 should have raised RuntimeError'\nexcept RuntimeError as e:\n    assert str(e) == 'cannot reuse already awaited coroutine', f'sequential g2: unexpected error: {e}'\n\n\n# === Three separate gathers sharing one coroutine ===\nasync def foo_three():\n    return 'x'\n\n\nc_three = foo_three()\ntry:\n    await asyncio.gather(asyncio.gather(c_three), asyncio.gather(c_three), asyncio.gather(c_three))  # pyright: ignore\n    assert False, 'three-way cross-gather reuse should have raised RuntimeError'\nexcept RuntimeError as e:\n    assert str(e) == 'cannot reuse already awaited coroutine', f'three-way: unexpected error: {e}'\n\n\n# === Direct await then gather: await c; await gather(c) ===\n# Covered by the direct await state check; kept with the gather reuse matrix.\nasync def foo_direct_first():\n    return 9\n\n\nc_direct_first = foo_direct_first()\nr_direct = await c_direct_first  # pyright: ignore\nassert r_direct == 9, f'direct await should return 9, got {r_direct}'\ntry:\n    await asyncio.gather(c_direct_first)  # pyright: ignore\n    assert False, 'gather after direct await should have raised'\nexcept RuntimeError as e:\n    assert str(e) == 'cannot reuse already awaited coroutine', f'direct→gather: unexpected error: {e}'\n\n\n# === Gather then direct await: g = gather(c); await g; await c ===\nasync def foo_gather_first():\n    return 11\n\n\nc_gather_first = foo_gather_first()\ng_first = asyncio.gather(c_gather_first)\nr_g = await g_first  # pyright: ignore\nassert r_g == [11], f'gather should resolve to [11], got {r_g}'\ntry:\n    await c_gather_first  # pyright: ignore\n    assert False, 'direct await after gather should have raised'\nexcept RuntimeError as e:\n    assert str(e) == 'cannot reuse already awaited coroutine', f'gather→direct: unexpected error: {e}'\n\n\n# === Cleanup smoke test: scheduler/heap still usable after the error path ===\n# The scheduler and heap should still be usable after the error path.\nasync def foo_cleanup_doomed():\n    return 1\n\n\nasync def foo_cleanup_ok():\n    return 'ok'\n\n\nc_doomed = foo_cleanup_doomed()\ntry:\n    await asyncio.gather(asyncio.gather(c_doomed), asyncio.gather(c_doomed))  # pyright: ignore\n    assert False, 'cleanup doomed gather should have raised'\nexcept RuntimeError:\n    pass\n\n# Fresh coroutines should still drive a fresh gather to completion.\nclean_result = await asyncio.gather(foo_cleanup_ok(), foo_cleanup_ok())  # pyright: ignore\nassert clean_result == ['ok', 'ok'], f'post-error gather should still work, got {clean_result}'\n",
  'async__gather_double_spawn_traceback.py':
      "# run-async\n\"\"\"Locks in the exception type, message, and frame layout for the canonical\ncross-gather coroutine reuse case (the reachable-on-live-server repro from\n`01-gather-double-spawn.md`).\"\"\"\n\nimport asyncio\n\n\nasync def foo():\n    return [1, 2, 3]\n\n\nc = foo()\ng1 = asyncio.gather(c)\ng2 = asyncio.gather(c)\nawait asyncio.gather(g1, g2)  # pyright: ignore\n\"\"\"\nTRACEBACK:\nTraceback (most recent call last):\n  File \"async__gather_double_spawn_traceback.py\", line 16, in <module>\n    await asyncio.gather(g1, g2)  # pyright: ignore\n    ~~~~~~~~~~~~~~~~~~~~~~~~~~~~\nRuntimeError: cannot reuse already awaited coroutine\n\"\"\"\n",
