  'bench__kitchen_sink.py':
      "# This test case is also used in the benchmark (benches/main.rs)\n# List operations\nmy_list = []\nmy_list.append(1)\nmy_list.append(2)\nmy_list.insert(0, 0)\nlist_len = len(my_list)\nlist_item = my_list[1]\n\n# Dict operations\nmy_dict = {}\nmy_dict['a'] = 10\nmy_dict['b'] = 20\ndict_val = my_dict['a']\npopped = my_dict.pop('b')\ndict_len = len(my_dict)\n\n# Tuple operations\nmy_tuple = (1, 2, 3)\ntuple_item = my_tuple[0]\ntuple_len = len(my_tuple)\n\n# String operations\ns = 'hello'\ns += ' world'\nstr_len = len(s)\n\n\n# Function definition and call\ndef add(x, y):\n    return x + y\n\n\nfunc_result = add(3, 4)\n\n# For loop with if/elif/else\ntotal = 0\nfor i in range(10):\n    if i < 3:\n        total += 1\n    elif i < 6:\n        total += 2\n    else:\n        total += 3\n\n# Boolean operators and comparisons\nflag = True and not False\ncheck = 1 < 2 and 3 > 2\nidentity = None is None\nnot_identity = 1 is not None\ncompare = 5 >= 5 and 5 <= 5 and 4 != 5\n\n# Assert with message\nassert total > 0\n\n# List comprehension\nsquares = [x * x for x in range(10)]\ncomp_sum = sum(squares)\n\n# Dict comprehension\nsquare_dict = {x: x * x for x in range(5)}\ndict_comp_sum = sum(square_dict.values())\n\n# Final result\nresult = list_len + list_item + dict_val + dict_len + tuple_item + tuple_len\nresult += str_len + func_result + total + comp_sum + dict_comp_sum\nresult\n# Return=373\n",
  'bool__ops.py':
      "# === Boolean 'and' operator ===\n# returns first falsy value, or last value if all truthy\nassert (5 and 3) == 3\nassert (0 and 3) == 0\nassert (1 and 2 and 3) == 3\n\n# === Boolean 'or' operator ===\n# returns first truthy value, or last value if all falsy\nassert (5 or 3) == 5\nassert (0 or 3) == 3\nassert (0 or 0 or 3) == 3\n\n# === Boolean 'not' operator ===\nassert (not 5) == False\nassert (not 0) == True\nassert (not None) == True\n\n# === Complex boolean expressions ===\nassert ((1 and 2) or (3 and 0)) == 2\nassert (not (0 and 1)) == True\n",
