      "# === sum() ===\n# Basic sum operations\nassert sum([1, 2, 3]) == 6\nassert sum([1, 2, 3], 10) == 16\nassert sum([1, 2, 3], start=10) == 16\nassert sum(()) == 0\nassert sum([], 5) == 5\nassert sum(range(5)) == 10\nassert sum([1.5, 2.5, 3.0], 0.0) == 7.0\n# Note: sum of floats without start requires py_add to support int+float\n\n# str/bytes start values are rejected, pointing at join() instead\ntry:\n    sum([], 'x')\n    assert False, 'expected TypeError'\nexcept TypeError as e:\n    assert str(e) == \"sum() can't sum strings [use ''.join(seq) instead]\"\n\ntry:\n    sum([], b'x')\n    assert False, 'expected TypeError'\nexcept TypeError as e:\n    assert str(e) == \"sum() can't sum bytes [use b''.join(seq) instead]\"\n\ntry:\n    sum([b'a'], start=b'')\n    assert False, 'expected TypeError'\nexcept TypeError as e:\n    assert str(e) == \"sum() can't sum bytes [use b''.join(seq) instead]\"\n\n# sum with different iterables\nassert sum({1, 2, 3}) == 6\nassert sum({1: 'a', 2: 'b', 3: 'c'}) == 6\n\n# === any() ===\n# Basic any operations\nassert any([True, False, False]) == True\nassert any([False, False, False]) == False\nassert any([]) == False\nassert any([0, 0, 1]) == True\nassert any([0, '', None]) == False\nassert any(['', 'hello']) == True\nassert any(range(0, 5)) == True\nassert any(range(0, 1)) == False\n\n# === all() ===\n# Basic all operations\nassert all([True, True, True]) == True\nassert all([True, False, True]) == False\nassert all([]) == True\nassert all([1, 2, 3]) == True\nassert all([1, 0, 3]) == False\nassert all(['a', 'b', 'c']) == True\nassert all(['a', '', 'c']) == False\n\n# More edge cases with nested structures\nassert any([[1], [], [3]]) == True\nassert all([[1], [2], [3]]) == True\n\n# sum with lists (list + list is supported)\nassert sum([[1], [2], [3]], []) == [1, 2, 3]\n# Note: sum with tuples requires Tuple py_add which is not implemented\n",
  'builtin__iter_next.py':
      "# === iter() on various iterables ===\n# iter() creates an iterator from an iterable\n\n# iter() on list\nit = iter([1, 2, 3])\nassert next(it) == 1\nassert next(it) == 2\nassert next(it) == 3\n\n# iter() on tuple\nit = iter((10, 20))\nassert next(it) == 10\nassert next(it) == 20\n\n# iter() on string\nit = iter('ab')\nassert next(it) == 'a'\nassert next(it) == 'b'\n\n# iter() on range\nit = iter(range(3))\nassert next(it) == 0\nassert next(it) == 1\nassert next(it) == 2\n\n# iter() on dict iterates over keys\nd = {'x': 1, 'y': 2}\nit = iter(d)\nkeys = [next(it), next(it)]\nassert 'x' in keys\nassert 'y' in keys\n\n# === next() with default value ===\n# next() returns default when iterator is exhausted\n\nit = iter([42])\nassert next(it) == 42\nassert next(it, 'done') == 'done'\n\n# Check default with various types\nit = iter([])\nassert next(it, None) is None\nassert next(it, 0) == 0\nassert next(it, []) == []\n\n# === iter() on iterator returns itself ===\n# Calling iter() on an iterator should return the same iterator\n\noriginal = iter([1, 2, 3])\nsame = iter(original)\n# They should iterate over the same values\nassert next(original) == 1\nassert next(same) == 2\nassert next(original) == 3\n\n# === Multiple independent iterators ===\n# Creating multiple iterators over the same iterable should be independent\n\ndata = [1, 2, 3]\nit1 = iter(data)\nit2 = iter(data)\nassert next(it1) == 1\nassert next(it1) == 2\nassert next(it2) == 1\nassert next(it1) == 3\nassert next(it2) == 2\n",
  'builtin__map.py':
      "assert list(map(abs, [-1, 0, 1, -2])) == [1, 0, 1, 2]\nassert list(map(abs, [0, 0, 0])) == [0, 0, 0]\n\nassert list(map(str, [1, 2, 3])) == ['1', '2', '3']\nassert list(map(str, [True, False])) == ['True', 'False']\n\nassert list(map(int, ['1', '2', '3'])) == [1, 2, 3]\nassert list(map(int, [1.1, 2.9, 3.5])) == [1, 2, 3]\nassert list(map(int, [True, False, True])) == [1, 0, 1]\n\nassert list(map(bool, [0, 1, '', 'x'])) == [False, True, False, True]\nassert list(map(bool, [[], [1], (), (2,)])) == [False, True, False, True]\n\nassert list(map(len, ['', 'a', 'ab', 'abc'])) == [0, 1, 2, 3]\nassert list(map(len, [[], [1], [1, 2], [1, 2, 3]])) == [0, 1, 2, 3]\n\nassert list(map(float, [1, 2, 3])) == [1.0, 2.0, 3.0]\nassert list(map(float, ['1.5', '2.5'])) == [1.5, 2.5]\n\nassert list(map(abs, [1, -2, 3])) == [1, 2, 3]\n\nassert list(map(abs, (1, -2, 3))) == [1, 2, 3]\n\nassert list(map(ord, 'abc')) == [97, 98, 99]\n\nassert list(map(abs, range(-3, 3))) == [3, 2, 1, 0, 1, 2]\n\nresult = list(map(abs, {-1, 0, 1}))\nassert sorted(result) == [0, 1, 1]\n\nassert list(map(abs, [])) == []\nassert list(map(abs, ())) == []\nassert list(map(abs, '')) == []\nassert list(map(abs, range(0))) == []\n\nassert list(map(list, [(1, 2), (3, 4)])) == [[1, 2], [3, 4]]\nassert list(map(tuple, [[1, 2], [3, 4]])) == [(1, 2), (3, 4)]\n\nassert list(map(pow, [2, 3, 4], [3, 2, 2])) == [8, 9, 16]\n\nassert list(map(divmod, [10, 20, 30], [3, 6, 7])) == [(3, 1), (3, 2), (4, 2)]\n\nassert list(map(pow, [2, 3, 4, 5], [3, 2])) == [8, 9]\nassert list(map(pow, [2, 3], [3, 2, 1, 0])) == [8, 9]\n\nassert list(map(pow, [2], [3, 4, 5])) == [8]\n\n\ndef f(x):\n    return x * 2\n\n\nassert list(map(f, [1, 2, 3])) == [2, 4, 6]\n\n\ndef raise_exception(x):\n    raise ValueError('Intentional error')\n\n\ntry:\n    list(map(raise_exception, [1, 2, 3]))\n    assert False, 'should have failed with exception'\nexcept ValueError as e:\n    assert str(e) == 'Intentional error'\n\ntry:\n    map()\n    assert False, 'map() should require arguments'\nexcept TypeError as e:\n    assert str(e) == 'map() must have at least two arguments.', f'map() arity: {e}'\n\ntry:\n    map(None)\n    assert False, 'map() with single arg should fail'\nexcept TypeError as e:\n    assert str(e) == 'map() must have at least two arguments.', f'map(fn) arity: {e}'\n",
