  'class__attrs.py':
      "# === class attribute assignment ===\nclass Point:\n    kind = 'point'\n    lst = [1, 2]\n\n    def __init__(self, x):\n        self.x = x\n\n    def double(self):\n        return self.x * 2\n\n\np = Point(3)\nq = Point(4)\n\nPoint.count = 0\nassert Point.count == 0\nPoint.count += 1\nassert Point.count == 1\nassert p.count == 1\nassert q.count == 1\n\nPoint.kind = 'dot'\nassert Point.kind == 'dot'\nassert q.kind == 'dot'\n\n# a function assigned to the class becomes a method (binds self)\nPoint.triple = lambda self: self.x * 3\nassert p.triple() == 9\n\n# setattr builtin on a class object\nsetattr(Point, 'via_setattr', 42)\nassert Point.via_setattr == 42\nassert p.via_setattr == 42\n\n# === setattr/getattr on instances ===\nsetattr(p, 'x', 10)\nassert p.x == 10\nassert getattr(p, 'x') == 10\nsetattr(p, 'fresh', 'n')\nassert p.fresh == 'n'\nassert not hasattr(q, 'fresh'), 'instance attr not shared with other instances'\n\n# === unbound method access with explicit self ===\nassert Point.double(p) == 20\nassert Point.double(q) == 8\n\n# === instance attr shadowing a class variable ===\nq.kind = 'special'\nassert q.kind == 'special'\nassert Point.kind == 'dot'\nassert p.kind == 'dot'\n\n# === method reassigned on an instance ===\n# an instance-dict function is NOT bound (same as CPython): called with no args\np.double = lambda: 'shadowed'\nassert p.double() == 'shadowed'\nassert q.double() == 8\n\n# === mutable class variable mutated through an instance ===\n# `q.lst += [9]` mutates the shared list in place AND creates an instance\n# attr referencing the same list (CPython augmented-assignment semantics)\nq.lst += [9]\nassert Point.lst == [1, 2, 9]\nassert p.lst == [1, 2, 9]\nassert q.lst is Point.lst\nPoint.lst.append(7)\nassert q.lst == [1, 2, 9, 7]\n\n# === obj.__class__ ===\nassert p.__class__ is Point\nassert Point(0).__class__ is Point\nassert p.__class__.__name__ == 'Point'\nassert type(p) is p.__class__\n# calling `obj.__class__(...)` constructs a new instance, both when accessed as\n# a value first and when called directly (the two must be consistent)\ncls = p.__class__\nassert cls(5).x == 5\nassert p.__class__(6).x == 6\nassert p.__class__(7).__class__ is Point\n\n\n# === __doc__ ===\nclass Documented:\n    \"\"\"the docs\"\"\"\n\n    x = 1\n\n\nclass Undocumented:\n    pass\n\n\nclass ExplicitDoc:\n    __doc__ = 'explicit'\n\n\nclass OverriddenDoc:\n    \"\"\"original\"\"\"\n\n    __doc__ = 'overridden'\n\n\nassert Documented.__doc__ == 'the docs'\nassert Documented().__doc__ == 'the docs'\nassert Undocumented.__doc__ is None\nassert Undocumented().__doc__ is None\nassert ExplicitDoc.__doc__ == 'explicit'\nassert OverriddenDoc.__doc__ == 'overridden'\n\n\nclass DocRead:\n    \"doc\"\n\n    y = __doc__\n\n\nassert DocRead.y == 'doc'\n\n\n# === __name__ ===\nclass NamedBar:\n    __name__ = 'bar'\n\n\nassert NamedBar.__name__ == 'NamedBar'\nassert NamedBar().__name__ == 'bar'\n\n# `__name__` is always a plain str, so calling it raises the same TypeError\n# CPython gives for calling any non-callable str, not an AttributeError.\ntry:\n    NamedBar.__name__()\n    assert False, 'expected calling __name__ to fail'\nexcept TypeError as exc:\n    assert str(exc) == \"'str' object is not callable\"\n\n# === type-object attribute errors ===\ntry:\n    Point.nope\n    assert False, 'expected attribute get to fail'\nexcept AttributeError as exc:\n    assert str(exc) == \"type object 'Point' has no attribute 'nope'\"\ntry:\n    Point.nope(1)\n    assert False, 'expected attribute call to fail'\nexcept AttributeError as exc:\n    assert str(exc) == \"type object 'Point' has no attribute 'nope'\"\n\n\n# === keyword args to a class without __init__ ===\nclass Empty:\n    pass\n\n\ntry:\n    Empty(k=1)\n    assert False, 'expected keyword construction to fail'\nexcept TypeError as exc:\n    assert str(exc) == 'Empty() takes no arguments'\n\n\n# === walrus in a lambda body inside a class (binds in the lambda scope) ===\nclass WithLambda:\n    f = lambda self: (z := 3) + 1\n\n\nassert WithLambda().f() == 4\n\n# === reference cycle through the class namespace ===\nPoint.self_ref = Point\nassert Point.self_ref is Point\nPoint.self_ref = None\nassert Point.self_ref is None\n",
  'class__basic.py':
      "# Basic user-defined classes: construction, instance attributes, methods,\n# class variables, type()/isinstance(), identity equality and bound methods.\n\n\nclass Point:\n    # class variable shared across instances\n    origin_count = 0\n\n    def __init__(self, x: int, y: int) -> None:\n        self.x = x\n        self.y = y\n\n    def total(self) -> int:\n        return self.x + self.y\n\n    def scaled(self, factor: int = 2) -> int:\n        return self.total() * factor\n\n    def move(self, dx: int, dy: int) -> None:\n        self.x += dx\n        self.y += dy\n\n\n# === Construction and __init__ ===\np = Point(3, 4)\nassert p.x == 3\nassert p.y == 4\n\n# === Instance methods ===\nassert p.total() == 7\nassert p.scaled() == 14\nassert p.scaled(3) == 21\nassert p.scaled(factor=10) == 70\n\n# === Mutating attributes via a method ===\np.move(1, 1)\nassert p.x == 4\nassert p.y == 5\nassert p.total() == 9\n\n# === Mutating attributes directly ===\np.x = 100\nassert p.x == 100\nassert p.total() == 105\n\n# === Setting a new attribute not declared in __init__ ===\np.z = 7\nassert p.z == 7\n\n# === Class variables ===\nassert Point.origin_count == 0\nassert p.origin_count == 0\nq = Point(1, 1)\nassert q.origin_count == 0\n\n# === Independent instances ===\nassert p.x == 100 and q.x == 1, 'instances have independent attributes'\n\n# === type() returns the class object ===\nassert type(p) is Point\nassert type(p) is type(q)\nassert type(p).__name__ == 'Point'\n\n# === isinstance ===\nassert isinstance(p, Point)\nassert isinstance(p, (int, Point))\nassert not isinstance(5, Point), 'isinstance false for a non-instance'\n\n\nclass Other:\n    def __init__(self) -> None:\n        self.v = 1\n\n\no = Other()\nassert not isinstance(o, Point), 'isinstance false for a different class'\nassert type(o) is not Point\n\n# === Identity equality (no user __eq__) ===\nassert p == p\nassert p != q\nassert (p == q) is False\n\n# === Instances are always truthy ===\nassert bool(p) is True\nif q:\n    pass\nelse:\n    assert False, 'instance should be truthy in a condition'\n\n# === Bound methods ===\nm = p.total\nassert m() == 105\nmove = p.move\nmove(10, 10)\nassert p.x == 110 and p.y == 15, 'bound method with arguments mutates the instance'\n\n# === getattr() / hasattr() ===\nassert getattr(p, 'x') == 110\nassert getattr(p, 'total')() == 125\nassert getattr(p, 'nope', 'default') == 'default'\nassert hasattr(p, 'x')\nassert hasattr(p, 'total')\nassert not hasattr(p, 'nope'), 'hasattr false for a missing attribute'\n\n# === A class with no __init__ ===\n\n\nclass Empty:\n    pass\n\n\ne = Empty()\nassert type(e) is Empty\nassert type(e).__name__ == 'Empty'\nassert isinstance(e, Empty)\n\n# === A class whose only members are methods ===\n\n\nclass Counter:\n    def __init__(self) -> None:\n        self.n = 0\n\n    def inc(self) -> None:\n        self.n += 1\n\n    def get(self) -> int:\n        return self.n\n\n\nc = Counter()\nc.inc()\nc.inc()\nc.inc()\nassert c.get() == 3\n\n# === Error cases ===\ntry:\n    e.nope\n    assert False, 'expected AttributeError for missing attribute'\nexcept AttributeError as exc:\n    assert str(exc) == \"'Empty' object has no attribute 'nope'\"\n\ntry:\n    e.nope()\n    assert False, 'expected AttributeError for missing method'\nexcept AttributeError as exc:\n    assert str(exc) == \"'Empty' object has no attribute 'nope'\"\n\ntry:\n    Empty(1)\n    assert False, 'expected TypeError when passing args to a class with no __init__'\nexcept TypeError as exc:\n    assert str(exc) == 'Empty() takes no arguments'\n\n# === Exception raised inside __init__ propagates (and the half-built instance\n# is cleaned up — checked under memory-model-checks) ===\n\n\nclass Boom:\n    def __init__(self, x: int) -> None:\n        self.x = x\n        raise ValueError('boom')\n\n\ntry:\n    Boom(1)\n    assert False, 'expected ValueError from __init__'\nexcept ValueError as exc:\n    assert str(exc) == 'boom'\n\n# === Reference cycles between instances are reclaimable (exercises GC tracing\n# of Instance children) ===\n\n\nclass Link:\n    def __init__(self) -> None:\n        self.other = None\n\n\nn1 = Link()\nn2 = Link()\nn1.other = n2\nn2.other = n1  # cycle: n1 <-> n2\nassert n1.other.other is n1\n\n# Self reference.\nn1.other = n1\nassert n1.other is n1\n\n# === Bound methods hash by identity: the same bound-method object works as a\n# dict key (CPython hashes by (instance, func); see limitations/classes.md) ===\n\nm = c.inc\nd = {m: 'inc'}\nassert d[m] == 'inc'\nassert hash(m) == hash(m)\ns = {m, m}\nassert len(s) == 1\n\n# === A name bound more than once in the class body: last binding wins, the\n# replaced (heap-allocated) value is released ===\n\n\nclass Rebound:\n    items = [1]\n    items = [2, 3]\n\n\nassert Rebound.items == [2, 3]\n\n# === Exotic __init__ members: CPython's type.__call__ looks __init__ up with\n# descriptor binding, so only plain functions bind the new instance as self;\n# anything else is called with the constructor args unchanged and must still\n# return None ===\n\n\nclass _Helper:\n    def __init__(self, x=None):\n        self.x = x\n\n\nclass InitIsClass:\n    __init__ = _Helper\n\n\ntry:\n    InitIsClass()\n    assert False, 'expected InitIsClass() to raise'\nexcept TypeError as e:\n    assert str(e) == \"__init__() should return None, not '_Helper'\"\n\n\nclass InitNotCallable:\n    __init__ = 42\n\n\ntry:\n    InitNotCallable()\n    assert False, 'expected InitNotCallable() to raise'\nexcept TypeError as e:\n    assert str(e) == \"'int' object is not callable\"\n\n\nclass InitReturnsValue:\n    def __init__(self):\n        return 'nope'\n\n\ntry:\n    InitReturnsValue()\n    assert False, 'expected InitReturnsValue() to raise'\nexcept TypeError as e:\n    assert str(e) == \"__init__() should return None, not 'str'\"\n\n\nclass InitAsync:\n    async def __init__(self):\n        pass\n\n\ntry:\n    InitAsync()\n    assert False, 'expected InitAsync() to raise'\nexcept TypeError as e:\n    assert str(e) == \"__init__() should return None, not 'coroutine'\"\n\n\n# A builtin __init__ that returns None: the instance is constructed and the\n# builtin receives only the constructor args (no self).\nclass InitBuiltin:\n    __init__ = print\n\n\nib = InitBuiltin('init-builtin-arg')\nassert type(ib) is InitBuiltin\n\n\n# A bound method used as __init__ keeps its own receiver; the new instance is\n# not prepended.\nclass Recorder:\n    def __init__(self):\n        self.calls = []\n\n    def record(self, *args):\n        self.calls.append(args)\n\n\nrec = Recorder()\n\n\nclass InitBoundMethod:\n    __init__ = rec.record\n\n\nibm = InitBoundMethod(1, 2)\nassert type(ibm) is InitBoundMethod\nassert rec.calls == [(1, 2)]\n\n\n# === `...` as the class body (common stub idiom) ===\nclass Stub: ...\n\n\ns = Stub()\nassert type(s) is Stub\ns.x = 1\nassert s.x == 1\n",
  'class__body_external.py':
      "# call-external\n# A class *body* that suspends on an external call. Because the class body now\n# runs as a real, suspendable frame (Step 2), a class-variable value may call an\n# external function: the VM yields to the host mid-definition and resumes,\n# building the class with the resolved value.\n\n\nclass Config:\n    # `add_ints` is an external function resolved by the host. Evaluated in the\n    # class-body scope at class-definition time.\n    limit = add_ints(40, 2)\n    doubled = limit * 2\n\n    def describe(self):\n        return self.limit\n\n\nassert Config.limit == 42\nassert Config.doubled == 84\nassert Config().describe() == 42\n",
