  'class__closures.py':
      "# Classes defined inside functions: methods skip the class scope for name\n# resolution but can still capture enclosing *function* locals (matching CPython).\n\n\ndef make_multiplier(n: int):\n    class Multiplier:\n        def __init__(self, base: int) -> None:\n            self.base = base\n\n        def compute(self) -> int:\n            # `n` is captured from the enclosing function, not the class body.\n            return self.base * n\n\n    return Multiplier(10)\n\n\nm = make_multiplier(3)\nassert m.compute() == 30\nassert m.base == 10\n\nm2 = make_multiplier(5)\nassert m2.compute() == 50\nassert m.compute() == 30\n\n\ndef counter_factory():\n    count = 0\n\n    class Counter:\n        def bump(self) -> int:\n            nonlocal count\n            count += 1\n            return count\n\n    return Counter()\n\n\nc = counter_factory()\nassert c.bump() == 1\nassert c.bump() == 2\nassert c.bump() == 3\n\n\n# A class defined at module scope still resolves globals (not class members) by\n# bare name from inside methods.\nFACTOR = 4\n\n\nclass Scaled:\n    def __init__(self, v: int) -> None:\n        self.v = v\n\n    def scale(self) -> int:\n        return self.v * FACTOR\n\n\nassert Scaled(3).scale() == 12\n",
  'class__dynamic_type.py':
      "# === dynamic class creation via 3-arg type() ===\nA = type('A', (), {'x': 1})\nassert A.__name__ == 'A'\nassert A.x == 1\na = A()\nassert type(a) is A\nassert isinstance(a, A)\nassert a.x == 1\na.x = 2\nassert a.x == 2 and A.x == 1, 'instance attr shadows class var'\n\n\n# === methods in the namespace dict ===\ndef _init(self, v):\n    self.v = v\n\n\ndef _double(self):\n    return self.v * 2\n\n\nM = type('M', (), {'__init__': _init, 'double': _double, 'halve': lambda self: self.v / 2})\nm = M(21)\nassert m.v == 21\nassert m.double() == 42\nassert m.halve() == 10.5\n\n# === namespace dict is copied ===\nd = {'x': 1}\nB = type('B', (), d)\nd['x'] = 99\nd['y'] = 100\nassert B.x == 1\ntry:\n    B.y\n    assert False, 'expected B.y to fail'\nexcept AttributeError as exc:\n    assert str(exc) == \"type object 'B' has no attribute 'y'\"\n\n# === __doc__ ===\nassert type('N', (), {}).__doc__ is None\nassert type('D', (), {'__doc__': 'hi'}).__doc__ == 'hi'\n\n# === identity ===\nE = type('E', (), {})\nassert E is not type('E', (), {})\n\n# === indirect and starred calls ===\nt = type\nInd = t('Ind', (), {})\nassert Ind.__name__ == 'Ind'\nargs = ('S', (), {'v': 7})\nS = type(*args)\nassert S.__name__ == 'S' and S.v == 7, 'starred 3-arg call'\n\n# === setattr on a dynamic class ===\nE.z = 5\nassert E.z == 5\nsetattr(E, 'w', 6)\nassert E.w == 6\n\n# === dynamic name computed at runtime ===\nname = 'Dyn' + 'Cls'\nDC = type(name, (), {})\nassert DC.__name__ == 'DynCls'\ntry:\n    DC.nope\n    assert False, 'expected attribute error'\nexcept AttributeError as exc:\n    assert str(exc) == \"type object 'DynCls' has no attribute 'nope'\"\n\n# === 1-arg form still works ===\nassert type(1) is int\nassert type(A()) is A\n\n# === arity errors ===\nfor bad in [lambda: type(), lambda: type('A', ()), lambda: type('A', (), {}, 1)]:\n    try:\n        bad()\n        assert False, 'expected arity error'\n    except TypeError as exc:\n        assert str(exc) == 'type() takes 1 or 3 arguments'\n\n# === keyword argument errors ===\ntry:\n    type(1, x=1)\n    assert False, 'expected kwargs error'\nexcept TypeError as exc:\n    assert str(exc) == 'type() takes no keyword arguments'\n\ntry:\n    type('A', (), {}, x=1)\n    assert False, 'expected kwargs error'\nexcept TypeError as exc:\n    assert str(exc) == 'A.__init_subclass__() takes no keyword arguments'\n\n# === argument type errors (CPython validation order: name, bases, dict) ===\ntry:\n    type(1, (), {})\n    assert False, 'expected bad name error'\nexcept TypeError as exc:\n    assert str(exc) == 'type.__new__() argument 1 must be str, not int'\n\ntry:\n    type(None, (), {})\n    assert False, 'expected bad name error'\nexcept TypeError as exc:\n    assert str(exc) == 'type.__new__() argument 1 must be str, not None'\n\ntry:\n    type(1, [], {})\n    assert False, 'expected bad name error'\nexcept TypeError as exc:\n    assert str(exc) == 'type.__new__() argument 1 must be str, not int'\n\ntry:\n    type('A', [], {})\n    assert False, 'expected bad bases error'\nexcept TypeError as exc:\n    assert str(exc) == 'type.__new__() argument 2 must be tuple, not list'\n\ntry:\n    type('A', (), [])\n    assert False, 'expected bad dict error'\nexcept TypeError as exc:\n    assert str(exc) == 'type.__new__() argument 3 must be dict, not list'\n\ntry:\n    type('A', [], {}, x=1)\n    assert False, 'expected bad bases error'\nexcept TypeError as exc:\n    assert str(exc) == 'type.__new__() argument 2 must be tuple, not list'\n",
  'class__init_async.py':
      "# call-external\n# run-async\n# An __init__ that suspends while the module is driven in async mode: the\n# external call inside __init__ goes through the pending-futures path and\n# resumes mid-construction (the async-mode counterpart of\n# class__init_external.py).\n\n\nclass Accumulator:\n    def __init__(self, base: int) -> None:\n        # `add_ints` is an external function resolved by the host.\n        self.total = add_ints(base, 100)\n        self.base = base\n\n\nstart = await async_call(7)  # pyright: ignore\nacc = Accumulator(start)\nassert acc.base == 7\nassert acc.total == 107\nassert type(acc) is Accumulator\n\n# === awaiting a non-awaitable instance names the class ===\ntry:\n    await acc  # pyright: ignore\n    assert False, 'expected await to fail'\nexcept TypeError as exc:\n    assert str(exc) == \"'Accumulator' object can't be awaited\"\n",
  'class__init_external.py':
      "# call-external\n# An __init__ that suspends on an external call. Because __init__ runs as a real\n# frame, the VM yields to the host mid-construction and resumes — exercising the\n# initializer frame (and its is_initializer flag) across the suspend point.\n\n\nclass Accumulator:\n    def __init__(self, base: int) -> None:\n        # `add_ints` is an external function resolved by the host.\n        self.total = add_ints(base, 100)\n        self.base = base\n\n    def bump(self, amount: int) -> int:\n        self.total = add_ints(self.total, amount)\n        return self.total\n\n\na = Accumulator(5)\nassert a.base == 5\nassert a.total == 105\nassert type(a) is Accumulator\n\n# A method that also suspends on an external call resumes correctly.\nassert a.bump(10) == 115\nassert a.total == 115\n",
  'class__init_raises.py':
      "# An exception raised inside __init__ propagates with a traceback that includes\n# the constructor-call frame and the __init__ frame, matching CPython exactly\n# (the half-built instance is cleaned up, verified under memory-model-checks).\n\n\nclass Account:\n    def __init__(self, balance):\n        if balance < 0:\n            raise ValueError('balance must be non-negative')\n        self.balance = balance\n\n\nAccount(-5)\n\"\"\"\nTRACEBACK:\nTraceback (most recent call last):\n  File \"class__init_raises.py\", line 13, in <module>\n    Account(-5)\n    ~~~~~~~~~~~\n  File \"class__init_raises.py\", line 9, in __init__\n    raise ValueError('balance must be non-negative')\nValueError: balance must be non-negative\n\"\"\"\n",
  'class__init_return.py':
      "class Foo:\n    def __init__(self):\n        return 42\n\n\nFoo()\n\"\"\"\nTRACEBACK:\nTraceback (most recent call last):\n  File \"class__init_return.py\", line 6, in <module>\n    Foo()\n    ~~~~~\nTypeError: __init__() should return None, not 'int'\n\"\"\"\n",
  'class__method_raises.py':
      "class Account:\n    def __init__(self, balance: int) -> None:\n        self.balance = balance\n\n    def withdraw(self, amount: int) -> None:\n        if amount > self.balance:\n            raise ValueError('insufficient funds')\n        self.balance -= amount\n\n\na = Account(100)\na.withdraw(200)\n\"\"\"\nTRACEBACK:\nTraceback (most recent call last):\n  File \"class__method_raises.py\", line 12, in <module>\n    a.withdraw(200)\n    ~~~~~~~~~~~~~~~\n  File \"class__method_raises.py\", line 7, in withdraw\n    raise ValueError('insufficient funds')\nValueError: insufficient funds\n\"\"\"\n",
  'class__name_error.py':
      "# Methods skip the class scope: a bare member name is NOT the class attribute,\n# so with no matching global it raises NameError. The traceback (frames, line\n# numbers, caret markers) matches CPython exactly.\n#\n# (CPython appends a \"Did you mean: 'self.timeout'?\" suggestion to the final\n# line, which Monty does not implement; the traceback harness strips that\n# CPython-only suffix — see scripts/run_traceback.py.)\n\n\nclass Settings:\n    timeout = 30\n\n    def describe(self):\n        return timeout  # not Settings.timeout; no global -> NameError\n\n\nSettings().describe()\n\"\"\"\nTRACEBACK:\nTraceback (most recent call last):\n  File \"class__name_error.py\", line 17, in <module>\n    Settings().describe()\n    ~~~~~~~~~~~~~~~~~~~~~\n  File \"class__name_error.py\", line 14, in describe\n    return timeout  # not Settings.timeout; no global -> NameError\n           ~~~~~~~\nNameError: name 'timeout' is not defined\n\"\"\"\n",
  'class__repr.py':
      "# __repr__ / __str__ dispatch for user-defined classes, including use inside\n# repr()/str()/f-strings/print and nested containers, plus the default repr.\n\n\nclass Vec:\n    def __init__(self, x: int, y: int) -> None:\n        self.x = x\n        self.y = y\n\n    def __repr__(self) -> str:\n        return f'Vec({self.x}, {self.y})'\n\n\nv = Vec(1, 2)\n\n# === repr() / str() dispatch to __repr__ ===\nassert repr(v) == 'Vec(1, 2)'\nassert str(v) == 'Vec(1, 2)'\n\n# === f-strings ===\nassert f'{v!r}' == 'Vec(1, 2)'\nassert f'{v}' == 'Vec(1, 2)'\n\n# === repr inside containers uses __repr__ ===\nassert repr([v, v]) == '[Vec(1, 2), Vec(1, 2)]'\nassert repr((v,)) == '(Vec(1, 2),)'\nassert repr({'k': v}) == \"{'k': Vec(1, 2)}\"\n\n\nclass Temperature:\n    def __init__(self, celsius: int) -> None:\n        self.celsius = celsius\n\n    def __repr__(self) -> str:\n        return f'Temperature(celsius={self.celsius})'\n\n    def __str__(self) -> str:\n        return f'{self.celsius}°C'\n\n\nt = Temperature(20)\n\n# === __str__ overrides __repr__ for str()/print, repr() still uses __repr__ ===\nassert str(t) == '20°C'\nassert repr(t) == 'Temperature(celsius=20)'\nassert f'{t}' == '20°C'\nassert f'{t!r}' == 'Temperature(celsius=20)'\n\n# === __repr__ that references other instances ===\n\n\nclass Node:\n    def __init__(self, value: int, nxt) -> None:\n        self.value = value\n        self.nxt = nxt\n\n    def __repr__(self) -> str:\n        return f'Node({self.value}, {self.nxt!r})'\n\n\nchain = Node(1, Node(2, None))\nassert repr(chain) == 'Node(1, Node(2, None))'\n\n# === Default repr (no __repr__): bare class name + address ===\n# CPython qualifies the name (`<__main__.Plain object ...>`); Monty uses the bare\n# class name. Both contain \"Plain object at\" and an address, so check loosely.\n\n\nclass Plain:\n    def __init__(self) -> None:\n        self.a = 1\n\n\npl = Plain()\nassert repr(pl).startswith('<Plain object at 0x')\nassert str(pl) == repr(pl)\nassert type(pl).__name__ == 'Plain'\n\n# === __repr__/__str__ set to an already-bound method: no extra `self` is bound ===\n# `Bar.__repr__` here is a `BoundMethod`, not a plain function, so dispatch must\n# not re-inject `self` (unlike descriptor binding for a plain-function member).\n\n\nclass Greeter:\n    def greet(self) -> str:\n        return 'hi'\n\n\nclass Bar:\n    __repr__ = Greeter().greet\n    __str__ = Greeter().greet\n\n\nassert repr(Bar()) == 'hi'\nassert str(Bar()) == 'hi'\n",
  'class__scope.py':
      "# The class body has a real (CPython-like) scope: class variables run\n# top-to-bottom in their own namespace, may be arbitrary expressions, and may\n# reference earlier class variables. Methods skip the class scope for bare-name\n# resolution (a bare name resolves to a global, never a sibling class member).\n\n\n# === Class var referencing an earlier class var ===\nclass Stepwise:\n    a = 1\n    b = a + 1\n    c = a + b\n\n\nassert Stepwise.a == 1\nassert Stepwise.b == 2\nassert Stepwise.c == 3\n\n\n# === Class var as an arbitrary expression (call / comprehension) ===\nclass Computed:\n    name = 'abc'.upper()\n    squares = [i * i for i in range(4)]\n    total = sum(squares)\n\n\nassert Computed.name == 'ABC'\nassert Computed.squares == [0, 1, 4, 9]\nassert Computed.total == 14\n\n\n# === Class var evaluation order is top-to-bottom ===\norder = []\n\n\nclass Ordered:\n    x = order.append('x')\n    y = order.append('y')\n    z = order.append('z')\n\n\nassert order == ['x', 'y', 'z']\n\n\n# === A method does NOT see class members by bare name ===\n# `helper` and `value` are class members; the method must resolve the bare names\n# to module globals, not to the class attributes.\nhelper = 'global-helper'\nvalue = 'global-value'\n\n\nclass BareName:\n    helper = 'member-helper'\n    value = 'member-value'\n\n    def get_helper(self):\n        return helper  # the module global, not BareName.helper\n\n    def get_value(self):\n        return value  # the module global, not BareName.value\n\n\nbn = BareName()\nassert bn.get_helper() == 'global-helper'\nassert bn.get_value() == 'global-value'\nassert BareName.helper == 'member-helper'\nassert BareName.value == 'member-value'\n\n\n# === Class defined in a function captures enclosing locals (transitive) ===\n# `n` flows: enclosing function -> class body (pass-through) -> method.\ndef make_adder(n):\n    class Adder:\n        bias = 100  # a class member, not visible to the method by bare name\n\n        def add(self, x):\n            return x + n  # captures the enclosing `n`, two scopes up\n\n    return Adder\n\n\nAdder3 = make_adder(3)\nassert Adder3().add(10) == 13\nassert Adder3.bias == 100\nAdder5 = make_adder(5)\nassert Adder5().add(10) == 15\nassert Adder3().add(10) == 13\n\n\n# === Distinct enclosing-local and class-member names coexist ===\n# (The same-name collision is rejected at compile time; distinct names are fine.)\ndef factory(scale):\n    class Widget:\n        kind = 'widget'\n\n        def scaled(self, x):\n            return x * scale\n\n    return Widget\n\n\nw = factory(4)()\nassert w.scaled(5) == 20\nassert factory(4)().kind == 'widget'\n\n# The bare-name NameError case (a method referencing a class member by bare name)\n# is covered by the traceback test in class__name_error.py.\n\n\n# === LOAD_NAME semantics: a member read before its binding falls back to the\n# global namespace (never to enclosing function locals), like CPython ===\n\nx = 5\n\n\nclass ReadsGlobal:\n    x = x + 1\n\n\nassert ReadsGlobal.x == 6\nassert x == 5\n\nfwd = 10\n\n\nclass ForwardRef:\n    y = fwd\n    fwd = 1\n\n\nassert ForwardRef.y == 10\nassert ForwardRef.fwd == 1\nassert fwd == 10\n\ng_name = 'global'\n\n\ndef shadowed():\n    g_name = 'func'\n\n    class Inner:\n        g_name = g_name\n\n    assert g_name == 'func'\n    return Inner.g_name\n\n\nassert shadowed() == 'global'\n\n\n# A global created at runtime, mid-class-body, is visible to a later unbound-\n# member read (the fallback is late-bound, not a prepare-time snapshot).\ndef set_dyn():\n    global dyn\n    dyn = 99\n\n\nclass DynamicGlobal:\n    a = set_dyn()\n    b = dyn\n    dyn = 1\n\n\nassert DynamicGlobal.b == 99\nassert DynamicGlobal.dyn == 1\n\n\n# Unbound-member reads fall through globals to builtins.\nclass BuiltinFallback:\n    len = len\n    n = len('abc')\n\n\nassert BuiltinFallback.n == 3\n\n\n# Method parameter defaults evaluate in class scope at their statement's\n# position, so the same before/after-binding rule applies.\nw_default = 'module'\n\n\nclass DefaultsScope:\n    def before(self, a=w_default):\n        return a\n\n    w_default = 'member'\n\n    def after(self, a=w_default):\n        return a\n\n\nd = DefaultsScope()\nassert d.before() == 'module'\nassert d.after() == 'member'\n\n# A member with no global/builtin anywhere raises NameError (not\n# UnboundLocalError), matching CPython class bodies.\ntry:\n\n    class NoBinding:\n        z = missing_name + 1\n        missing_name = 1\n\n    assert False, 'expected NameError'\nexcept NameError as e:\n    assert str(e) == \"name 'missing_name' is not defined\"\n",
  'class__type_errors.py':
      "import json\n\n\n# Error messages involving a user-class instance must name the real class\n# (e.g. 'Foo'), not the generic 'object'.\nclass Foo:\n    pass\n\n\nf = Foo()\n\n# === binary operators ===\ntry:\n    f + 1\n    assert False, 'expected + to fail'\nexcept TypeError as exc:\n    assert str(exc) == \"unsupported operand type(s) for +: 'Foo' and 'int'\"\ntry:\n    1 + f\n    assert False, 'expected reflected + to fail'\nexcept TypeError as exc:\n    assert str(exc) == \"unsupported operand type(s) for +: 'int' and 'Foo'\"\ntry:\n    f - 1\n    assert False, 'expected - to fail'\nexcept TypeError as exc:\n    assert str(exc) == \"unsupported operand type(s) for -: 'Foo' and 'int'\"\ntry:\n    x = Foo()\n    x += 1\n    assert False, 'expected += to fail'\nexcept TypeError as exc:\n    assert str(exc) == \"unsupported operand type(s) for +=: 'Foo' and 'int'\"\ntry:\n    divmod(f, 1)\n    assert False, 'expected divmod to fail'\nexcept TypeError as exc:\n    assert str(exc) == \"unsupported operand type(s) for divmod(): 'Foo' and 'int'\"\ntry:\n    pow(f, 2)\n    assert False, 'expected pow to fail'\nexcept TypeError as exc:\n    assert str(exc) == \"unsupported operand type(s) for ** or pow(): 'Foo' and 'int'\"\n\n# === str/list concatenation special form ===\ntry:\n    '' + f\n    assert False, 'expected str concat to fail'\nexcept TypeError as exc:\n    assert str(exc) == 'can only concatenate str (not \"Foo\") to str'\ntry:\n    [] + f\n    assert False, 'expected list concat to fail'\nexcept TypeError as exc:\n    assert str(exc) == 'can only concatenate list (not \"Foo\") to list'\n\n# === unary operators ===\ntry:\n    -f\n    assert False, 'expected unary - to fail'\nexcept TypeError as exc:\n    assert str(exc) == \"bad operand type for unary -: 'Foo'\"\ntry:\n    +f\n    assert False, 'expected unary + to fail'\nexcept TypeError as exc:\n    assert str(exc) == \"bad operand type for unary +: 'Foo'\"\ntry:\n    ~f\n    assert False, 'expected unary ~ to fail'\nexcept TypeError as exc:\n    assert str(exc) == \"bad operand type for unary ~: 'Foo'\"\n\n# === len / iteration / membership / subscription ===\ntry:\n    len(f)\n    assert False, 'expected len to fail'\nexcept TypeError as exc:\n    assert str(exc) == \"object of type 'Foo' has no len()\"\ntry:\n    iter(f)\n    assert False, 'expected iter to fail'\nexcept TypeError as exc:\n    assert str(exc) == \"'Foo' object is not iterable\"\ntry:\n    for _ in f:\n        pass\n    assert False, 'expected for to fail'\nexcept TypeError as exc:\n    assert str(exc) == \"'Foo' object is not iterable\"\ntry:\n    1 in f\n    assert False, 'expected membership to fail'\nexcept TypeError as exc:\n    assert str(exc) == \"argument of type 'Foo' is not a container or iterable\"\ntry:\n    a, b = f\n    assert False, 'expected unpacking to fail'\nexcept TypeError as exc:\n    assert str(exc) == 'cannot unpack non-iterable Foo object'\ntry:\n    f[0]\n    assert False, 'expected subscript to fail'\nexcept TypeError as exc:\n    assert str(exc) == \"'Foo' object is not subscriptable\"\ntry:\n    f[0] = 1\n    assert False, 'expected subscript assignment to fail'\nexcept TypeError as exc:\n    assert str(exc) == \"'Foo' object does not support item assignment\"\n\n# === calling an instance ===\ntry:\n    f()\n    assert False, 'expected call to fail'\nexcept TypeError as exc:\n    assert str(exc) == \"'Foo' object is not callable\"\n\n# === numeric conversions ===\ntry:\n    abs(f)\n    assert False, 'expected abs to fail'\nexcept TypeError as exc:\n    assert str(exc) == \"bad operand type for abs(): 'Foo'\"\ntry:\n    int(f)\n    assert False, 'expected int() to fail'\nexcept TypeError as exc:\n    assert str(exc) == \"int() argument must be a string, a bytes-like object or a real number, not 'Foo'\"\ntry:\n    float(f)\n    assert False, 'expected float() to fail'\nexcept TypeError as exc:\n    assert str(exc) == \"float() argument must be a string or a real number, not 'Foo'\"\ntry:\n    round(f)\n    assert False, 'expected round to fail'\nexcept TypeError as exc:\n    assert str(exc) == \"type Foo doesn't define __round__ method\"\ntry:\n    hex(f)\n    assert False, 'expected hex to fail'\nexcept TypeError as exc:\n    assert str(exc) == \"'Foo' object cannot be interpreted as an integer\"\n\n# === ordering comparisons ===\ntry:\n    sorted([f, Foo()])\n    assert False, 'expected sorted to fail'\nexcept TypeError as exc:\n    assert str(exc) == \"'<' not supported between instances of 'Foo' and 'Foo'\"\n# the direct `<` / `>=` operators raise too (not just via sorted)\ntry:\n    f < Foo()\n    assert False, 'expected f < Foo() to fail'\nexcept TypeError as exc:\n    assert str(exc) == \"'<' not supported between instances of 'Foo' and 'Foo'\"\ntry:\n    f >= Foo()\n    assert False, 'expected f >= Foo() to fail'\nexcept TypeError as exc:\n    assert str(exc) == \"'>=' not supported between instances of 'Foo' and 'Foo'\"\n\n# === string / io / json sinks ===\ntry:\n    ''.join([f])\n    assert False, 'expected join to fail'\nexcept TypeError as exc:\n    assert str(exc) == 'sequence item 0: expected str instance, Foo found'\ntry:\n    json.dumps(f)\n    assert False, 'expected json.dumps to fail'\nexcept TypeError as exc:\n    assert str(exc) == 'Object of type Foo is not JSON serializable'\ntry:\n    print(1, 2, sep=f)\n    assert False, 'expected print sep to fail'\nexcept TypeError as exc:\n    assert str(exc) == 'sep must be None or a string, not Foo'\n\n# === context manager protocol ===\ntry:\n    with f:\n        pass\n    assert False, 'expected with to fail'\nexcept TypeError as exc:\n    assert str(exc) == \"'Foo' object does not support the context manager protocol (missed __exit__ method)\"\n\n\n# === two different classes in one message ===\nclass Bar:\n    pass\n\n\ntry:\n    f + Bar()\n    assert False, 'expected mixed-class + to fail'\nexcept TypeError as exc:\n    assert str(exc) == \"unsupported operand type(s) for +: 'Foo' and 'Bar'\"\n\n\n# === __repr__ / __str__ must return a str ===\nclass BadRepr:\n    def __repr__(self):\n        return 42\n\n\ntry:\n    repr(BadRepr())\n    assert False, 'expected repr to fail'\nexcept TypeError as exc:\n    assert str(exc) == '__repr__ returned non-string (type int)'\n\n\nclass BadStr:\n    def __str__(self):\n        return 42\n\n\ntry:\n    str(BadStr())\n    assert False, 'expected str to fail'\nexcept TypeError as exc:\n    assert str(exc) == '__str__ returned non-string (type int)'\n",
  'closure__multi_hop_capture.py':
      "# === Two-hop capture through pass-through scope (regression for #469 / #477) ===\n# `inner` reads `x` which is bound in `outer`; `middle` is a pass-through scope\n# that doesn't reference `x` itself but must propagate the cell.\ndef two_hop():\n    x = 1\n\n    def middle():\n        def inner():\n            return x\n\n        return inner()\n\n    return middle()\n\n\nassert two_hop() == 1\n\n\n# === Three-hop capture: f -> g -> h -> i ===\ndef three_hop():\n    x = 'deep'\n\n    def g():\n        def h():\n            def i():\n                return x\n\n            return i()\n\n        return h()\n\n    return g()\n\n\nassert three_hop() == 'deep'\n\n\n# === Multiple captures across nested scopes ===\ndef multi_capture():\n    a = 1\n    b = 2\n\n    def middle():\n        def inner():\n            return (a, b)\n\n        return inner()\n\n    return middle()\n\n\nassert multi_capture() == (1, 2)\n\n\n# === Pass-through scope reads the captured name itself too ===\ndef pass_through_reads():\n    x = 10\n\n    def middle():\n        local_y = x + 1  # middle reads x directly\n\n        def inner():\n            return x + local_y  # inner also reads x (capture) and middle's local\n\n        return inner()\n\n    return middle()\n\n\nassert pass_through_reads() == 10 + 10 + 1\n\n\n# === Mixed nonlocal + implicit multi-hop ===\ndef nonlocal_through_pass_through():\n    x = 100\n\n    def middle():\n        def inner():\n            nonlocal x\n            x = 200\n\n        inner()\n        return x\n\n    return middle()\n\n\nassert nonlocal_through_pass_through() == 200\n\n\n# === Lambda captures through pass-through ===\ndef lambda_pass_through():\n    x = 'lambda'\n\n    def middle():\n        return lambda: x\n\n    return middle()()\n\n\nassert lambda_pass_through() == 'lambda'\n\n\n# === Multiple inner functions, only one captures ===\ndef selective_capture():\n    x = 'captured'\n\n    def middle():\n        def reader():\n            return x  # captures\n\n        def non_reader():\n            return 'unrelated'  # does not capture\n\n        return reader() + ':' + non_reader()\n\n    return middle()\n\n\nassert selective_capture() == 'captured:unrelated'\n",
  'closure__param_shadows_outer.py':
      "# === Parameter shadows outer local (basic) ===\ndef outer_basic():\n    x = 42\n\n    def inner(x):\n        return x + 1\n\n    return inner(10)\n\n\nassert outer_basic() == 11\n\n\n# === Parameter shadows outer local (multiple params) ===\ndef outer_multi():\n    a = 100\n    b = 200\n\n    def inner(a, b):\n        return a + b\n\n    return inner(1, 2)\n\n\nassert outer_multi() == 3\n\n\n# === Mixed: one param shadows, one captures ===\ndef outer_mixed():\n    x = 10\n    y = 20\n\n    def inner(x):\n        return x + y\n\n    return inner(5)\n\n\nassert outer_mixed() == 25\n\n\n# === Parameter shadows with default value ===\ndef outer_default():\n    x = 99\n\n    def inner(x=7):\n        return x\n\n    return inner()\n\n\nassert outer_default() == 7\n\n\n# === Deeply nested: param shadows grandparent local ===\ndef outer_deep():\n    x = 1000\n\n    def middle():\n        def inner(x):\n            return x * 2\n\n        return inner(3)\n\n    return middle()\n\n\nassert outer_deep() == 6\n\n\n# === Parameter used in complex expression ===\ndef outer_expr():\n    scale = 100\n\n    def inner(n, scale):\n        return n * scale + 1\n\n    return inner(5, 10)\n\n\nassert outer_expr() == 51\n",
  'closure__pep448.py':
      "# Tests for PEP 448 unpacking inside closures.\n# These exercise the collect_*_from_expr helpers in prepare.rs which walk\n# expressions to find walrus-operator assignments, cell variables, and\n# referenced names in nested functions. Closures that reference variables\n# used in PEP 448 positions (dict unpack, list/tuple/set literal, call args)\n# are the only way to reach these code paths.\n\n# === Closure capturing variable used in dict unpack ===\ndef outer_dict():\n    d1 = {'a': 1, 'b': 2}\n    d2 = {'c': 3}\n\n    def inner():\n        return {**d1, **d2}\n\n    return inner()\n\n\nassert outer_dict() == {'a': 1, 'b': 2, 'c': 3}\n\n\n# === Closure capturing variable used in list unpack ===\ndef outer_list():\n    items = [1, 2, 3]\n    extra = [4, 5]\n\n    def inner():\n        return [*items, *extra]\n\n    return inner()\n\n\nassert outer_list() == [1, 2, 3, 4, 5]\n\n\n# === Closure capturing variable used in tuple unpack ===\ndef outer_tuple():\n    a = (1, 2)\n    b = (3, 4)\n\n    def inner():\n        return (*a, *b)\n\n    return inner()\n\n\nassert outer_tuple() == (1, 2, 3, 4)\n\n\n# === Closure capturing variable used in set unpack ===\ndef outer_set():\n    items = [1, 2, 3]\n\n    def inner():\n        return {*items}\n\n    return inner()\n\n\nassert outer_set() == {1, 2, 3}\n\n\n# === Closure using PEP 448 in a function call (single * and **) ===\ndef outer_call_star():\n    def f(*args, **kwargs):\n        return (args, kwargs)\n\n    args = [1, 2, 3]\n    kw = {'x': 10}\n\n    def inner():\n        return f(*args, **kw)\n\n    return inner()\n\n\nassert outer_call_star() == ((1, 2, 3), {'x': 10})\n\n\n# === Closure using multiple * and ** in a call ===\ndef outer_multi():\n    def f(*args, **kwargs):\n        return (args, kwargs)\n\n    a = [1, 2]\n    b = [3, 4]\n    kw1 = {'x': 10}\n    kw2 = {'y': 20}\n\n    def inner():\n        return f(*a, *b, **kw1, **kw2)\n\n    return inner()\n\n\nassert outer_multi() == ((1, 2, 3, 4), {'x': 10, 'y': 20})\n\n\n# === Closure calling with keyword-only args (ArgExprs::Kwargs) ===\n# The outer-function assignment `_precomp = f(a=val_a, b=val_b)` exercises\n# collect_assigned_names_from_args for the Kwargs arm.  The inner body exercises\n# collect_cell_vars_from_args and collect_referenced_names_from_args for Kwargs.\ndef outer_kwargs_call():\n    def f(**kwargs):\n        return kwargs\n\n    val_a = 10\n    val_b = 20\n    # Assignment RHS is a Kwargs call → triggers collect_assigned_names_from_args Kwargs arm\n    _precomp = f(a=val_a, b=val_b)\n\n    def inner():\n        # Kwargs call in inner body → collect_cell/referenced_names Kwargs arm\n        return f(a=val_a, b=val_b)\n\n    return inner()\n\n\nassert outer_kwargs_call() == {'a': 10, 'b': 20}\n\n\n# === Closure calling with positional + *star (ArgsKargs with args=Some) ===\n# Exercises ArgsKargs branch where the positional-args field is non-None.\ndef outer_argsstar():\n    def f(*args):\n        return list(args)\n\n    pos_val = 1\n    items = [2, 3]\n    # Assignment RHS has positional arg + star → ArgsKargs with args=Some([pos_val])\n    _precomp = f(pos_val, *items)\n\n    def inner():\n        return f(pos_val, *items)\n\n    return inner()\n\n\nassert outer_argsstar() == [1, 2, 3]\n\n\n# === Closure calling with named kwarg + **kw (ArgsKargs with kwargs=Some) ===\n# Exercises ArgsKargs branch where the named-kwargs field is non-None.\ndef outer_kwargsstar():\n    def f(**kwargs):\n        return kwargs\n\n    val = 1\n    extra = {'b': 2}\n    # Assignment RHS has named kwarg + double-star → ArgsKargs with kwargs=Some\n    _precomp = f(a=val, **extra)\n\n    def inner():\n        return f(a=val, **extra)\n\n    return inner()\n\n\nassert outer_kwargsstar() == {'a': 1, 'b': 2}\n\n\n# === Closure with GeneralizedCall and Named kwarg ===\n# Exercises the CallKwarg::Named arm in all three collect_*_names_from_args functions.\ndef outer_generalized_named():\n    def f(*args, **kwargs):\n        return (args, kwargs)\n\n    a = [1, 2]\n    b = [3]\n    key_val = 99\n    # Assignment RHS has GeneralizedCall with Named kwarg → collect_assigned_names Named arm\n    _precomp = f(*a, *b, key=key_val)\n\n    def inner():\n        # Named kwarg in GeneralizedCall → collect_cell/referenced_names Named arm\n        return f(*a, *b, key=key_val)\n\n    return inner()\n\n\nassert outer_generalized_named() == ((1, 2, 3), {'key': 99})\n\n\n# === Closure with GeneralizedCall and plain Value arg ===\n# Exercises the CallArg::Value path of the GeneralizedCall args loop,\n# covering the Value branch of the `CallArg::Value | CallArg::Unpack` OR-pattern.\ndef outer_generalized_mixed():\n    def f(*args):\n        return list(args)\n\n    const = 0\n    items1 = [1, 2]\n    items2 = [3, 4]\n    # GeneralizedCall with Value(const) + Unpack(items1) + Unpack(items2)\n    _precomp = f(const, *items1, *items2)\n\n    def inner():\n        return f(const, *items1, *items2)\n\n    return inner()\n\n\nassert outer_generalized_mixed() == [0, 1, 2, 3, 4]\n",
  'closure__transitive.py':
      "# Multi-level (transitive / pass-through) closure capture: a nested function\n# capturing a variable from a scope more than one level up. Each intermediate\n# scope threads the captured cell through, matching CPython.\n\n\n# === Two-level read ===\ndef outer_read(a):\n    def mid():\n        def inner():\n            return a  # captured from `outer_read`, through `mid`\n\n        return inner()\n\n    return mid()\n\n\nassert outer_read(10) == 10\n\n\n# === Four-level read ===\ndef a4(x):\n    def b():\n        def c():\n            def d():\n                return x * 2\n\n            return d()\n\n        return c()\n\n    return b()\n\n\nassert a4(21) == 42\n\n\n# === Two-level nonlocal write ===\ndef writer():\n    a = 0\n\n    def mid():\n        def inner():\n            nonlocal a\n            a += 5\n\n        inner()\n\n    mid()\n    return a\n\n\nassert writer() == 5\n\n\n# === Intermediate scope rebinds the name (shadowing) ===\ndef shadow(x):\n    def mid():\n        x = 99  # mid's own local shadows the outer `x`\n\n        def inner():\n            return x  # captures mid's x, NOT outer's\n\n        return inner()\n\n    return (mid(), x)\n\n\nassert shadow(1) == (99, 1)\n\n\n# === Owner reads its own variable before the capturing def appears ===\n# This pins the fix: the variable must be recognised as a cell up front, even\n# though it is only captured by a grand-nested function further down.\ndef early_use(n):\n    total = n  # read/assigned here, before `mid`/`inner` are defined\n    total += 1\n\n    def mid():\n        def inner():\n            return total  # captures `total` two levels up\n\n        return inner()\n\n    return (mid(), total)\n\n\nassert early_use(10) == (11, 11)\n\n\n# === Sibling closures two levels down share the same cell ===\ndef shared():\n    v = 0\n\n    def mid():\n        def setter(x):\n            nonlocal v\n            v = x\n\n        def getter():\n            return v\n\n        return setter, getter\n\n    return mid()\n\n\ns, g = shared()\ns(42)\nassert g() == 42\n\n\n# === Each instantiation captures its own cell ===\ndef make_adder(n):\n    def mid():\n        def add(x):\n            return x + n\n\n        return add\n\n    return mid()\n\n\nadd3 = make_adder(3)\nadd5 = make_adder(5)\nassert add3(10) == 13\nassert add5(10) == 15\nassert add3(10) == 13\n\n\n# === Comprehension nested two levels deep captures an enclosing variable ===\ndef comp(n):\n    def mid():\n        return [n + i for i in range(3)]\n\n    return mid()\n\n\nassert comp(10) == [10, 11, 12]\n\n\n# === Mixed capture from two different levels at once ===\ndef two_levels(a):\n    def mid(b):\n        def inner():\n            return a + b  # `a` from outer (2 levels), `b` from mid (1 level)\n\n        return inner()\n\n    return mid(5)\n\n\nassert two_levels(10) == 15\n\n\n# === Lambda capturing two levels up ===\ndef lam(a):\n    def mid():\n        return (lambda: a)()\n\n    return mid()\n\n\nassert lam(7) == 7\n\n\n# === Three-level nonlocal write ===\ndef writer3():\n    a = 0\n\n    def m1():\n        def m2():\n            def inner():\n                nonlocal a\n                a += 7\n\n            inner()\n\n        m2()\n\n    m1()\n    return a\n\n\nassert writer3() == 7\n\n\n# === Chained nonlocal: each intermediate scope also declares it ===\ndef chained():\n    a = 1\n\n    def m1():\n        nonlocal a\n\n        def inner():\n            nonlocal a\n            a = 99\n\n        inner()\n\n    m1()\n    return a\n\n\nassert chained() == 99\n\n\n# === Capturing function defined inside control-flow blocks ===\n# Exercises the transitive cell-var pre-pass recursing through if/for bodies.\ndef control_flow(a, flag):\n    if flag:\n\n        def mid():\n            for _ in range(1):\n\n                def inner():\n                    return a\n\n                return inner()\n\n        return mid()\n    return -1\n\n\nassert control_flow(5, True) == 5\n\n\n# === Owner mutates the captured variable after building the closure ===\n# The closure must observe the later value (a shared cell, not a snapshot).\ndef late_mutation():\n    x = 1\n\n    def mid():\n        def inner():\n            return x\n\n        return inner\n\n    f = mid()\n    x = 42  # mutated after the closure was created\n    return f()\n\n\nassert late_mutation() == 42\n\n\n# === Default argument in a nested function references a transitive capture ===\ndef with_default(a):\n    def mid():\n        def inner(y=a):  # default evaluated in mid; `a` captured from outer\n            return y\n\n        return inner()\n\n    return mid()\n\n\nassert with_default(11) == 11\n\n\n# === Owner reads the var BEFORE a nested default captures it ===\n# Pins the pre-pass bug: a transitive capture hidden in a nested function's\n# default expression must promote the variable to a cell up front, otherwise the\n# earlier `a + 1` read resolves it as a plain local and diverges at runtime.\ndef default_after_read(a):\n    y = a + 1  # owner reads `a` before `mid`/`inner` are defined\n\n    def mid():\n        def inner(b=a):  # default evaluated in mid; `a` captured from outer\n            return b\n\n        return inner()\n\n    return y, mid()\n\n\nassert default_after_read(10) == (11, 10)\n\n\n# === Single-level default capture with an earlier owner read ===\ndef default_one_level(a):\n    y = a + 1\n\n    def mid(x=a):  # default evaluated in outer; `a` captured one level up\n        return x\n\n    return y, mid()\n\n\nassert default_one_level(10) == (11, 10)\n\n\n# === `def f(a=a)` gotcha: default RHS captures the enclosing name ===\n# The right-hand `a` is evaluated in the enclosing scope (capturing the param),\n# even though the nested function also has a parameter named `a`.\ndef same_name_default(a):\n    def inner(a=a):  # RHS `a` is outer's param (10); param `a` shadows inside\n        return a\n\n    return inner()\n\n\nassert same_name_default(10) == 10\n\n\n# === Intermediate rebind shadows a default capture ===\n# `mid` rebinds `a`, so `inner`'s default captures mid's `a`, not outer's.\ndef default_shadowed(a):\n    def mid():\n        a = 99\n\n        def inner(b=a):  # captures mid's a (99), not outer's\n            return b\n\n        return inner()\n\n    return (mid(), a)\n\n\nassert default_shadowed(1) == (99, 1)\n\n\n# === `global` in an intermediate scope is not a capture candidate ===\n# A name declared `global` is not a local binding, so a nested function reading\n# it resolves to the module global rather than capturing a (non-existent) cell.\ng_counter = 100\n\n\ndef uses_global():\n    global g_counter\n    g_counter = 20\n\n    def inner():\n        return g_counter  # the module global, not a captured cell\n\n    return inner()\n\n\nassert uses_global() == 20\nassert g_counter == 20\n\n\n# The intermediate `global` even overrides an enclosing local of the same name.\ng_shadowed = 100\n\n\ndef outer_with_global_mid():\n    g_shadowed = 1  # outer local, shadowed for mid's chain by mid's `global`\n\n    def mid():\n        global g_shadowed\n\n        def inner():\n            return g_shadowed  # module global (100), not outer's local (1)\n\n        return inner()\n\n    return mid()\n\n\nassert outer_with_global_mid() == 100\n\n\n# === Lambda whose default is a capturing lambda ===\n# The default `(lambda: x)` is evaluated in the enclosing scope, so its `x`\n# captures the enclosing `x` — NOT the outer lambda's same-named param. The\n# cell-var pre-pass must therefore scan lambda defaults without filtering by the\n# lambda's own params, else the enclosing cell is missed (the closure build then\n# fails). `y` reads `x` first to pin that the owner stays consistent with the\n# late-promoted cell.\ndef lambda_default_capture():\n    x = 10\n    y = x + 1\n    g = lambda x=(lambda: x): x()\n    return y, g()\n\n\nassert lambda_default_capture() == (11, 10)\n\n\n# The same capture works two levels up and survives owner mutation after the\n# inner closure is built (a shared cell, not a snapshot).\ndef lambda_default_two_level():\n    v = 1\n\n    def mid():\n        g = lambda x=(lambda: v): x\n        return g()\n\n    inner = mid()\n    v = 42  # mutated after the default closure was created\n    return inner()\n\n\nassert lambda_default_two_level() == 42\n",
  'closure__undefined_nonlocal.py':
      "# accessing nonlocal before assignment should raise NameError\ndef outer():\n    def inner():\n        nonlocal x\n        return x  # x not yet defined\n\n    result = inner()\n    x = 10\n    return result\n\n\nouter()\n# Raise=NameError(\"cannot access free variable 'x' where it is not associated with a value in enclosing scope\")\n",
  'codecs__all.py':
      "# === Encoding name normalization and aliases ===\n# Names are normalized like CPython: case-insensitive, runs of spaces/hyphens\n# collapse to '_', leading/trailing punctuation dropped, dots kept.\nfor alias in ('utf-8', 'utf8', 'utf_8', 'UTF-8', 'utf', 'u8', 'cp65001', 'utf8-ucs2', 'utf8-ucs4', ' UTF 8 ', 'UTF--8'):\n    assert 'héllo'.encode(alias) == b'h\\xc3\\xa9llo', f'utf-8 alias {alias}'\n    assert b'h\\xc3\\xa9llo'.decode(alias) == 'héllo', f'utf-8 decode alias {alias}'\nfor alias in (\n    'ascii',\n    'ASCII',\n    '646',\n    'us',\n    'us-ascii',\n    'us_ascii',\n    'cp367',\n    'ibm367',\n    'csascii',\n    'ansi_x3.4-1968',\n    'ansi_x3.4-1986',\n    'iso646-us',\n    'ISO_646.IRV:1991',\n    'iso-ir-6',\n):\n    assert 'hello'.encode(alias) == b'hello', f'ascii alias {alias}'\n    assert b'hello'.decode(alias) == 'hello', f'ascii decode alias {alias}'\nfor alias in ('utf-16', 'utf16', 'utf_16', 'u16', 'UTF 16'):\n    assert 'a'.encode(alias) == b'\\xff\\xfea\\x00', f'utf-16 alias {alias}'\nfor alias in ('utf-16-le', 'utf-16le', 'UTF_16_LE', 'UnicodeLittleUnmarked'):\n    assert 'a'.encode(alias) == b'a\\x00', f'utf-16-le alias {alias}'\nfor alias in ('utf-16-be', 'utf-16be', 'UnicodeBigUnmarked'):\n    assert 'a'.encode(alias) == b'\\x00a', f'utf-16-be alias {alias}'\nfor alias in ('utf-32', 'utf32', 'u32'):\n    assert 'a'.encode(alias) == b'\\xff\\xfe\\x00\\x00a\\x00\\x00\\x00', f'utf-32 alias {alias}'\nassert 'a'.encode('utf-32-le') == b'a\\x00\\x00\\x00'\nassert 'a'.encode('utf-32le') == b'a\\x00\\x00\\x00'\nassert 'a'.encode('utf-32-be') == b'\\x00\\x00\\x00a'\nassert 'a'.encode('utf-32be') == b'\\x00\\x00\\x00a'\n\n# Dots are preserved by normalization, so 'utf.8' is NOT an alias of utf-8.\ntry:\n    'hi'.encode('utf.8')\n    assert False, 'utf.8 should not resolve'\nexcept LookupError as e:\n    assert str(e) == 'unknown encoding: utf.8', f'unknown encoding message: {e}'\n# The LookupError shows the original name, not the normalized form.\ntry:\n    b'hi'.decode(' Not A Real--Codec ')\n    assert False, 'unknown codec should error'\nexcept LookupError as e:\n    assert str(e) == 'unknown encoding:  Not A Real--Codec ', f'unknown encoding keeps original name: {e}'\n\n# === utf-16 / utf-32 encode ===\n# The bare variants prepend a BOM (little-endian), even for an empty string.\nassert 'ab'.encode('utf-16') == b'\\xff\\xfea\\x00b\\x00'\nassert ''.encode('utf-16') == b'\\xff\\xfe'\nassert ''.encode('utf-16-le') == b''\nassert ''.encode('utf-32') == b'\\xff\\xfe\\x00\\x00'\n# Explicit -le/-be variants write no BOM.\nassert 'ab'.encode('utf-16-le') == b'a\\x00b\\x00'\nassert 'ab'.encode('utf-16-be') == b'\\x00a\\x00b'\n# Astral characters become surrogate pairs in utf-16, single units in utf-32.\nassert '\\U0001f600'.encode('utf-16') == b'\\xff\\xfe=\\xd8\\x00\\xde'\nassert '\\U0001f600'.encode('utf-16-be') == b'\\xd8=\\xde\\x00'\nassert '\\U0001f600'.encode('utf-32-le') == b'\\x00\\xf6\\x01\\x00'\nassert '\\U0001f600'.encode('utf-32-be') == b'\\x00\\x01\\xf6\\x00'\n# Encoding can never fail (no lone surrogates exist), so `errors` is never\n# consulted or validated, matching CPython's lazy handler lookup.\nassert 'héllo ⚡'.encode('utf-16', 'bogus') == 'héllo ⚡'.encode('utf-16')\nassert 'héllo'.encode('utf-32-be', 'strict') == 'héllo'.encode('utf-32-be')\n\n# Round-trips through both endiannesses and the BOM variant.\ns = 'héllo wörld ⚡ 日本語 \\U0001f600 test'\nfor enc in ('utf-16', 'utf-16-le', 'utf-16-be', 'utf-32', 'utf-32-le', 'utf-32-be'):\n    assert s.encode(enc).decode(enc) == s, f'{enc} round-trip'\n\n# === utf-16 / utf-32 decode: BOM handling ===\n# The bare variants consume a BOM of either endianness.\nassert b'\\xff\\xfea\\x00'.decode('utf-16') == 'a'\nassert b'\\xfe\\xff\\x00a'.decode('utf-16') == 'a'\nassert b'\\xff\\xfe'.decode('utf-16') == ''\nassert b''.decode('utf-16') == ''\nassert b'\\xff\\xfe\\x00\\x00a\\x00\\x00\\x00'.decode('utf-32') == 'a'\nassert b'\\x00\\x00\\xfe\\xff\\x00\\x00\\x00a'.decode('utf-32') == 'a'\nassert b''.decode('utf-32') == ''\n# A second BOM is real content (U+FEFF, zero width no-break space).\nassert b'\\xff\\xfe\\xff\\xfe'.decode('utf-16') == '﻿'\n# Explicit -le/-be variants never consume a BOM.\nassert b'\\xff\\xfea\\x00'.decode('utf-16-le') == '﻿a'\nassert b'\\x00\\x00\\xfe\\xff'.decode('utf-32-be') == '﻿'\n\n# === utf-16 decode errors ===\n# Errors are reported under the resolved codec name ('utf-16-le', not\n# 'utf-16'), with byte positions; a consumed BOM still counts in positions.\ntry:\n    b'a\\x00b'.decode('utf-16-le')\n    assert False, 'odd-length utf-16 should error'\nexcept UnicodeDecodeError as e:\n    assert str(e) == \"'utf-16-le' codec can't decode byte 0x62 in position 2: truncated data\", (\n        f'utf-16 truncated single byte: {e}'\n    )\ntry:\n    b'\\x00\\xd8a\\x00'.decode('utf-16-le')\n    assert False, 'lone high surrogate should error'\nexcept UnicodeDecodeError as e:\n    assert str(e) == \"'utf-16-le' codec can't decode bytes in position 0-1: illegal UTF-16 surrogate\", (\n        f'utf-16 high surrogate without pair: {e}'\n    )\ntry:\n    b'\\x00\\xdca\\x00'.decode('utf-16-le')\n    assert False, 'lone low surrogate should error'\nexcept UnicodeDecodeError as e:\n    assert str(e) == \"'utf-16-le' codec can't decode bytes in position 0-1: illegal encoding\", (\n        f'utf-16 lone low surrogate: {e}'\n    )\ntry:\n    b'a\\x00\\x00\\xd8'.decode('utf-16-le')\n    assert False, 'high surrogate at end should error'\nexcept UnicodeDecodeError as e:\n    assert str(e) == \"'utf-16-le' codec can't decode bytes in position 2-3: unexpected end of data\", (\n        f'utf-16 high surrogate at end: {e}'\n    )\n# A high surrogate followed by a single trailing byte is one 3-byte error unit.\ntry:\n    b'a\\x00\\x00\\xd8a'.decode('utf-16-le')\n    assert False, 'high surrogate + stray byte should error'\nexcept UnicodeDecodeError as e:\n    assert str(e) == \"'utf-16-le' codec can't decode bytes in position 2-4: unexpected end of data\", (\n        f'utf-16 3-byte tail is one unit: {e}'\n    )\n# Positions include the consumed BOM.\ntry:\n    b'\\xff\\xfe\\x00\\xd8'.decode('utf-16')\n    assert False, 'high surrogate after BOM should error'\nexcept UnicodeDecodeError as e:\n    assert str(e) == \"'utf-16-le' codec can't decode bytes in position 2-3: unexpected end of data\", (\n        f'utf-16 position includes BOM: {e}'\n    )\n# Big-endian errors report the -be name.\ntry:\n    b'\\xd8\\x00a\\x00'.decode('utf-16-be')\n    assert False, 'utf-16-be lone high surrogate should error'\nexcept UnicodeDecodeError as e:\n    assert str(e) == \"'utf-16-be' codec can't decode bytes in position 0-1: illegal UTF-16 surrogate\", (\n        f'utf-16-be error name: {e}'\n    )\n\n# === utf-16 decode error handlers ===\nassert b'a\\x00\\x00\\xd8b\\x00'.decode('utf-16-le', 'replace') == 'a�b'\nassert b'a\\x00\\x00\\xd8'.decode('utf-16-le', 'replace') == 'a�'\nassert b'a\\x00\\x00\\xd8a'.decode('utf-16-le', 'replace') == 'a�'\nassert b'a\\x00\\x00\\xd8b\\x00'.decode('utf-16-le', 'ignore') == 'ab'\nassert b'a\\x00b'.decode('utf-16-le', 'ignore') == 'a'\nassert b'a\\x00\\x00\\xd8b\\x00'.decode('utf-16-le', 'backslashreplace') == 'a\\\\x00\\\\xd8b'\n# Handler names are validated lazily, and encode-only handlers raise TypeError.\nassert b'a\\x00'.decode('utf-16-le', 'bogus') == 'a'\ntry:\n    b'a\\x00b'.decode('utf-16-le', 'xmlcharrefreplace')\n    assert False, 'encode-only handler on decode should error'\nexcept TypeError as e:\n    assert str(e) == \"don't know how to handle UnicodeDecodeError in error callback\", (\n        f'utf-16 decode xmlcharrefreplace: {e}'\n    )\n\n# === utf-32 decode errors ===\ntry:\n    b'\\xff\\xff\\xff\\x00'.decode('utf-32-le')\n    assert False, 'out-of-range code point should error'\nexcept UnicodeDecodeError as e:\n    assert str(e) == \"'utf-32-le' codec can't decode bytes in position 0-3: code point not in range(0x110000)\", (\n        f'utf-32 out of range: {e}'\n    )\ntry:\n    b'\\x00\\xd8\\x00\\x00'.decode('utf-32-le')\n    assert False, 'surrogate code point should error'\nexcept UnicodeDecodeError as e:\n    assert str(e) == (\n        \"'utf-32-le' codec can't decode bytes in position 0-3: code point in surrogate code point range(0xd800, 0xe000)\"\n    ), f'utf-32 surrogate code point: {e}'\ntry:\n    b'a\\x00\\x00'.decode('utf-32-le')\n    assert False, 'truncated utf-32 should error'\nexcept UnicodeDecodeError as e:\n    assert str(e) == \"'utf-32-le' codec can't decode bytes in position 0-2: truncated data\", (\n        f'utf-32 truncated 3-byte tail: {e}'\n    )\n# A single trailing byte uses the byte-form message.\ntry:\n    b'a'.decode('utf-32-le')\n    assert False, 'single byte utf-32 should error'\nexcept UnicodeDecodeError as e:\n    assert str(e) == \"'utf-32-le' codec can't decode byte 0x61 in position 0: truncated data\", (\n        f'utf-32 single-byte form: {e}'\n    )\n# Positions include the consumed BOM.\ntry:\n    b'\\xff\\xfe\\x00\\x00a\\x00'.decode('utf-32')\n    assert False, 'truncated utf-32 after BOM should error'\nexcept UnicodeDecodeError as e:\n    assert str(e) == \"'utf-32-le' codec can't decode bytes in position 4-5: truncated data\", (\n        f'utf-32 position includes BOM: {e}'\n    )\nassert b'\\xff\\xff\\xff\\x00a\\x00\\x00\\x00'.decode('utf-32-le', 'replace') == '�a'\nassert b'\\xff\\xff\\xff\\x00a\\x00\\x00\\x00'.decode('utf-32-le', 'ignore') == 'a'\nassert b'\\x00\\xd8\\x00\\x00'.decode('utf-32-le', 'backslashreplace') == '\\\\x00\\\\xd8\\\\x00\\\\x00'\n\n# === utf-8 decode: precise strict messages ===\ntry:\n    b'a\\xffb'.decode('utf-8')\n    assert False, 'invalid start byte should error'\nexcept UnicodeDecodeError as e:\n    assert str(e) == \"'utf-8' codec can't decode byte 0xff in position 1: invalid start byte\", (\n        f'utf-8 invalid start byte: {e}'\n    )\ntry:\n    b'\\x80'.decode('utf-8')\n    assert False, 'stray continuation byte should error'\nexcept UnicodeDecodeError as e:\n    assert str(e) == \"'utf-8' codec can't decode byte 0x80 in position 0: invalid start byte\", (\n        f'utf-8 stray continuation byte: {e}'\n    )\ntry:\n    b'a\\xe2\\x28b'.decode('utf-8')\n    assert False, 'invalid continuation should error'\nexcept UnicodeDecodeError as e:\n    assert str(e) == \"'utf-8' codec can't decode byte 0xe2 in position 1: invalid continuation byte\", (\n        f'utf-8 invalid continuation byte: {e}'\n    )\n# A multi-byte maximal subpart uses the range-form message.\ntry:\n    b'\\xf0\\x9f(a'.decode('utf-8')\n    assert False, 'partial 4-byte sequence should error'\nexcept UnicodeDecodeError as e:\n    assert str(e) == \"'utf-8' codec can't decode bytes in position 0-1: invalid continuation byte\", (\n        f'utf-8 multi-byte subpart range form: {e}'\n    )\ntry:\n    b'a\\xe2\\x82'.decode('utf-8')\n    assert False, 'truncated sequence should error'\nexcept UnicodeDecodeError as e:\n    assert str(e) == \"'utf-8' codec can't decode bytes in position 1-2: unexpected end of data\", (\n        f'utf-8 truncated multi-byte sequence: {e}'\n    )\ntry:\n    b'\\xc3'.decode('utf-8')\n    assert False, 'truncated 2-byte sequence should error'\nexcept UnicodeDecodeError as e:\n    assert str(e) == \"'utf-8' codec can't decode byte 0xc3 in position 0: unexpected end of data\", (\n        f'utf-8 truncated single lead byte: {e}'\n    )\n# A CESU-8-encoded surrogate is rejected at its lead byte.\ntry:\n    b'a\\xed\\xa0\\x80b'.decode('utf-8')\n    assert False, 'CESU-8 surrogate should error'\nexcept UnicodeDecodeError as e:\n    assert str(e) == \"'utf-8' codec can't decode byte 0xed in position 1: invalid continuation byte\", (\n        f'utf-8 CESU-8 surrogate: {e}'\n    )\n\n# === utf-8 decode error handlers ===\n# replace substitutes one U+FFFD per maximal subpart (not per byte).\nassert b'a\\xe2\\x82b\\xf0\\x9f\\x98'.decode('utf-8', 'replace') == 'a�b�'\nassert b'a\\xf0\\x28\\x8c\\x28b'.decode('utf-8', 'replace') == 'a�(�(b'\nassert b'a\\xed\\xa0\\x80b'.decode('utf-8', 'replace') == 'a���b'\nassert b'a\\xe2\\x82b'.decode('utf-8', 'ignore') == 'ab'\nassert b'a\\xe2\\x82b'.decode('utf-8', 'backslashreplace') == 'a\\\\xe2\\\\x82b'\n# Handler validation stays lazy; surrogatepass re-raises for non-surrogate errors.\nassert b'hello'.decode('utf-8', 'bogus') == 'hello'\ntry:\n    b'h\\xffllo'.decode('utf-8', 'bogus')\n    assert False, 'unknown handler should error once needed'\nexcept LookupError as e:\n    assert str(e) == \"unknown error handler name 'bogus'\", f'utf-8 unknown handler: {e}'\ntry:\n    b'\\xff'.decode('utf-8', 'surrogatepass')\n    assert False, 'surrogatepass should re-raise for non-surrogate errors'\nexcept UnicodeDecodeError as e:\n    assert str(e) == \"'utf-8' codec can't decode byte 0xff in position 0: invalid start byte\", (\n        f'utf-8 surrogatepass re-raises strict: {e}'\n    )\ntry:\n    b'a\\xffb'.decode('utf-8', 'xmlcharrefreplace')\n    assert False, 'encode-only handler on utf-8 decode should error'\nexcept TypeError as e:\n    assert str(e) == \"don't know how to handle UnicodeDecodeError in error callback\", (\n        f'utf-8 decode xmlcharrefreplace: {e}'\n    )\n",
  'compare__mixed_types.py':
      "# === Bool == Int equality ===\nassert True == 1\nassert False == 0\nassert 1 == True\nassert 0 == False\nassert True != 2\nassert False != 1\n\n# === Bool == Float equality ===\nassert True == 1.0\nassert False == 0.0\nassert 1.0 == True\nassert 0.0 == False\nassert True != 2.0\nassert 0.5 != False\n\n# === Int == Float equality ===\nassert 5 == 5.0\nassert 5.0 == 5\nassert 5 != 5.5\nassert 0 == 0.0\nassert -3 == -3.0\n\n# === Int/Float ordering ===\nassert 5 < 5.5\nassert 5.5 > 5\nassert 5 <= 5.0\nassert 5.0 >= 5\nassert 5 > 4.9\nassert 4.9 < 5\n\n# === Bool ordering (promotes to int) ===\nassert True > False\nassert False < True\nassert True >= 1\nassert False <= 0\nassert True > 0\nassert True < 2\nassert True > 0.5\nassert True < 1.5\nassert False < 0.5\nassert False >= -1\n\n# === Cross-type non-equality ===\nassert 'hello' != 42\nassert 42 != 'hello'\nassert b'hello' != 'hello'\nassert 'hello' != b'hello'\nassert None != 0\nassert 0 != None\nassert [] != 'list'\nassert {} != 0\n\n# === LongInt cross-type comparisons ===\nbig = 2**100\nbig2 = 2**100\nassert big == big2\nassert big != 5\nassert big > 5\nassert 5 < big\nassert big >= 5\nassert 5 <= big\nsmall_big = 2**100\nlarge_big = 2**101\nassert small_big < large_big\nassert large_big > small_big\nassert big != 'hello'\n\n# === Float vs LongInt comparisons (exact, no precision loss) ===\n# Powers of two are exactly representable as f64, so these are exactly equal\nassert 2.0**100 == 2**100\nassert 2**100 == 2.0**100\nassert 2.0**100 != 2**100 + 1\nassert 2**100 + 1 != 2.0**100\n# Non-power-of-two big ints are not exactly representable; comparison is still exact\nassert 1e30 != 10**30\nassert 10**30 != 1e30\n# Non-integral float is never equal to any int\nassert 2.5 != 2**100\nassert 2**100 != 2.5\n# Ordering across float and LongInt\nassert 2.0**100 < 2**101\nassert 2**101 > 2.0**100\nassert 1e308 < 10**400\nassert 10**400 > 1e308\nassert 2.5 < 2**100\nassert 2**100 > 2.5\n# Infinities compare against LongInt without overflow\nassert float('inf') > 10**400\nassert 10**400 < float('inf')\nassert float('-inf') < 10**400\nassert 10**400 > float('-inf')\n\n# Equal float/LongInt pairs must hash equally and be interchangeable dict keys\nassert hash(2.0**100) == hash(2**100)\nassert {2**100: 'a'}[2.0**100] == 'a'\nassert {2.0**100: 'b'}[2**100] == 'b'\nassert 2.0**100 in {2**100, 3}\n\n# === Bytes ordering ===\nassert b'abc' < b'abd'\nassert b'abc' <= b'abc'\nassert b'abd' > b'abc'\nassert b'abc' >= b'abc'\nassert b'a' < b'b'\nassert b'' < b'a'\n\n# === String ordering ===\nassert 'abc' < 'abd'\nassert 'abc' <= 'abc'\nassert 'abd' > 'abc'\nassert 'abc' >= 'abc'\nassert 'a' < 'b'\n\n# === Heap-allocated string ordering (from split) ===\nparts = 'banana,apple'.split(',')\nassert parts[1] < parts[0]\nassert parts[0] > parts[1]\nassert parts[0] >= parts[0]\nassert parts[0] <= parts[0]\n\n# === Cross-type string ordering (interned vs heap) ===\nheap_str = 'banana,apple'.split(',')[0]\nassert heap_str > 'apple'\nassert 'cherry' > heap_str\nassert heap_str >= 'banana'\nassert 'banana' <= heap_str\n\n# === Containment: not in list ===\nassert 999 not in [1, 2, 3]\nassert 0 not in [1, 2, 3]\n\n# === Containment: not in tuple ===\nassert 'z' not in ('a', 'b', 'c')\nassert 0 not in (1, 2, 3)\n\n# === Containment: in/not in set ===\nassert 2 in {1, 2, 3}\nassert 99 not in {1, 2, 3}\n\n# === Containment: in/not in frozenset ===\nassert 2 in frozenset({1, 2, 3})\nassert 99 not in frozenset({1, 2, 3})\n\n# === Containment: in/not in list (found) ===\nassert 2 in [1, 2, 3]\nassert 'b' in ['a', 'b', 'c']\n\n# === Containment: in/not in tuple (found) ===\nassert 'b' in ('a', 'b', 'c')\nassert 2 in (1, 2, 3)\n\n# === List ordering (lexicographic, like tuples) ===\nassert [1, 2] < [1, 3]\nassert [1, 2, 3] > [1, 2]\nassert [1] < [1, 2]\nassert [1, 2] <= [1, 2]\nassert [1, 2] >= [1, 2]\nassert ['a', 'b'] < ['a', 'c']\nassert [[1], [2]] < [[1], [3]]\nassert not ([2] < [1]), 'list not lt'\n# equal-but-unorderable elements don't block ordering (None == None), like CPython\nassert [None, 1] < [None, 2]\n\n# === Unorderable comparisons raise TypeError (not silently False) ===\ntry:\n    1 < 'a'\n    assert False, 'expected int < str to raise'\nexcept TypeError as exc:\n    assert str(exc) == \"'<' not supported between instances of 'int' and 'str'\"\n\ntry:\n    None < None\n    assert False, 'expected None < None to raise'\nexcept TypeError as exc:\n    assert str(exc) == \"'<' not supported between instances of 'NoneType' and 'NoneType'\"\n\ntry:\n    [1] >= 'a'\n    assert False, 'expected list >= str to raise'\nexcept TypeError as exc:\n    assert str(exc) == \"'>=' not supported between instances of 'list' and 'str'\"\n\n# === NaN ordering returns False, never raises (NaN is unordered, not incomparable) ===\n# CPython: every ordering operator against a NaN yields False, for both directions\n# and for two NaNs. This is distinct from a type mismatch, which raises.\nnan = float('nan')\nassert not (nan < 1), 'nan < int is False'\nassert not (nan <= 1), 'nan <= int is False'\nassert not (nan > 1), 'nan > int is False'\nassert not (nan >= 1), 'nan >= int is False'\nassert not (1 < nan), 'int < nan is False'\nassert not (1 >= nan), 'int >= nan is False'\nassert not (nan < nan), 'nan < nan is False'\nassert not (nan >= nan), 'nan >= nan is False'\nassert not (nan < 10**30), 'nan < LongInt is False'\nassert not (nan < 1.5), 'nan < float is False'\nassert not (nan < True), 'nan < bool is False'\n\n# NaN combined with a genuine type mismatch still raises (numeric-vs-str)\ntry:\n    nan < 'a'\n    assert False, 'expected nan < str to raise'\nexcept TypeError as exc:\n    assert str(exc) == \"'<' not supported between instances of 'float' and 'str'\"\n\n# === NaN inside containers ===\n# The first differing element decides: a NaN element makes the container unordered\n# (False), a type-mismatched element makes it incomparable (raises).\nassert not ([nan] < [1]), 'list with nan element is unordered'\nassert not ((nan,) < (1,)), 'tuple with nan element is unordered'\nassert not ([1, nan] < [1, 2]), 'nan as second element is unordered'\ntry:\n    [nan] < ['a']\n    assert False, 'expected list with float/str element mismatch to raise'\nexcept TypeError:\n    # Both raise TypeError; only the message text diverges (Monty names the\n    # outer 'list'/'list', CPython the inner 'float'/'str') — see\n    # limitations/language.md, so the exact message is not asserted here.\n    pass\n\n# === sorted / min / max with NaN do not raise ===\n# NaN compares as neither less nor greater, so it never triggers a swap; CPython\n# leaves such elements in place rather than erroring.\nassert sorted([3, 1, 2]) == [1, 2, 3]\nassert sorted([nan, 1, 2, nan])[1:3] == [1, 2]\nassert min([nan, 1, 2]) != min([nan, 1, 2])\nassert max([1, nan, 2]) == 2\nassert min([1, 2, nan]) == 1\n",
  'comprehension__all.py':
      "# === Basic list comprehension ===\nassert [x for x in [1, 2, 3]] == [1, 2, 3]\nassert [x * 2 for x in [1, 2, 3]] == [2, 4, 6]\nassert [x + 1 for x in range(5)] == [1, 2, 3, 4, 5]\n\n# === With filter ===\nassert [x for x in [1, 2, 3, 4] if x > 2] == [3, 4]\nassert [x for x in [1, 2, 3, 4, 5] if x % 2 == 0] == [2, 4]\nassert [x for x in range(20) if x % 2 == 0 if x % 3 == 0] == [0, 6, 12, 18]\nassert [x * 2 for x in [1, 2, 3, 4] if x > 1 if x < 4] == [4, 6]\n\n# === Nested for ===\nassert [x + y for x in [1, 2] for y in [10, 20]] == [11, 21, 12, 22]\nassert [(x, y) for x in [1, 2] for y in ['a', 'b']] == [(1, 'a'), (1, 'b'), (2, 'a'), (2, 'b')]\nassert [x * y for x in [1, 2, 3] for y in [10, 100]] == [10, 100, 20, 200, 30, 300]\n\n# === Nested with filter ===\nassert [x + y for x in [1, 2, 3] if x > 1 for y in [10, 20] if y > 10] == [22, 23]\n\n# === Set comprehension ===\nassert {x for x in [1, 2, 2, 3]} == {1, 2, 3}\nassert {x for x in [1, 2, 3] if x > 1} == {2, 3}\nassert {x * 2 for x in [1, 2, 3]} == {2, 4, 6}\nassert {x % 3 for x in range(10)} == {0, 1, 2}\n\n# === Dict comprehension ===\nassert {x: x * 2 for x in [1, 2, 3]} == {1: 2, 2: 4, 3: 6}\nassert {x: x for x in [1, 2, 3] if x > 1} == {2: 2, 3: 3}\nassert {str(x): x for x in [1, 2, 3]} == {'1': 1, '2': 2, '3': 3}\nassert {x: y for x in [1, 2] for y in [10, 20]} == {1: 20, 2: 20}\n\n# === Scope isolation ===\nx = 'outer'\nresult = [x for x in [1, 2, 3]]\nassert x == 'outer'\n\ny = 'before'\nresult2 = [y * 2 for y in [1, 2]]\nassert y == 'before'\n\n# === Access enclosing scope ===\nmultiplier = 10\nassert [x * multiplier for x in [1, 2]] == [10, 20]\n\nprefix = 'item_'\nassert [prefix + str(x) for x in [1, 2, 3]] == ['item_1', 'item_2', 'item_3']\n\nbase = [1, 2, 3]\nassert [x + 10 for x in base] == [11, 12, 13]\n\n\n# === Capture when iter uses same name as target ===\ndef outer_capture_same_name():\n    x = [1, 2, 3]\n\n    def inner():\n        return [x for x in x]\n\n    return inner()\n\n\nassert outer_capture_same_name() == [1, 2, 3]\n\n# === Empty iterables ===\nassert [x for x in []] == []\nassert {x for x in []} == set()\nassert {x: x for x in []} == {}\n\n# === Filter removes all ===\nassert [x for x in [1, 2, 3] if x > 10] == []\nassert {x for x in [1, 2, 3] if x > 10} == set()\nassert {x: x for x in [1, 2, 3] if x > 10} == {}\n\n# === Complex expressions ===\nassert [x**2 for x in [1, 2, 3, 4]] == [1, 4, 9, 16]\nassert [len(s) for s in ['a', 'bb', 'ccc']] == [1, 2, 3]\nassert [[y for y in range(x)] for x in [1, 2, 3]] == [[0], [0, 1], [0, 1, 2]]\n\n# === Nested generator referencing prior loop var ===\n# Second generator's iter references first generator's loop variable\nassert [y for x in [[1, 2], [3, 4]] for y in x] == [1, 2, 3, 4]\nassert [(x, y) for x in [1, 2] for y in range(x)] == [(1, 0), (2, 0), (2, 1)]\n\n\ndef outer_nested_comp():\n    xs = [[1, 2], [3, 4]]\n\n    def inner():\n        return [y for x in xs for y in x]\n\n    return inner()\n\n\nassert outer_nested_comp() == [1, 2, 3, 4]\n\n# === Tuple unpacking in comprehensions ===\npairs = [(1, 'a'), (2, 'b'), (3, 'c')]\nassert [x for x, y in pairs] == [1, 2, 3]\nassert [y for x, y in pairs] == ['a', 'b', 'c']\nassert [str(x) + str(y) for x, y in [(1, 2), (3, 4)]] == ['12', '34']\nassert [(y, x) for x, y in pairs] == [('a', 1), ('b', 2), ('c', 3)]\n\n# Tuple unpacking with filter\nassert [x for x, y in pairs if x > 1] == [2, 3]\nassert [y for x, y in pairs if y != 'b'] == ['a', 'c']\n\n# Triple unpacking\ntriples = [(1, 2, 3), (4, 5, 6)]\nassert [a + b + c for a, b, c in triples] == [6, 15]\nassert [b for a, b, c in triples] == [2, 5]\n\n# Dict comprehension with unpacking\nd = {k: v for k, v in pairs}\nassert d == {1: 'a', 2: 'b', 3: 'c'}\nassert {v: k for k, v in pairs} == {'a': 1, 'b': 2, 'c': 3}\n\n# Set comprehension with unpacking\nassert {x for x, y in pairs} == {1, 2, 3}\nassert {y for x, y in pairs} == {'a', 'b', 'c'}\n\n# Unpacking with dict.items()\nd2 = {'x': 10, 'y': 20, 'z': 30}\nassert [k for k, v in d2.items()] == ['x', 'y', 'z']\nassert [v for k, v in d2.items()] == [10, 20, 30]\nassert {v: k for k, v in d2.items()} == {10: 'x', 20: 'y', 30: 'z'}\n\n# Nested comprehension with unpacking\nmatrix = [[(1, 2), (3, 4)], [(5, 6), (7, 8)]]\nassert [[a + b for a, b in row] for row in matrix] == [[3, 7], [11, 15]]\n\n# Scope isolation with unpacking (vars don't leak)\nx = 'outer_x'\ny = 'outer_y'\nresult = [x + y for x, y in [(1, 2)]]\nassert x == 'outer_x'\nassert y == 'outer_y'\n\n\n# Unpacking in closure\ndef outer_unpack():\n    items = [(1, 2), (3, 4)]\n\n    def inner():\n        return [a * b for a, b in items]\n\n    return inner()\n\n\nassert outer_unpack() == [2, 12]\n\n\n# Capture variable used in unpacking pattern\ndef outer_shadow_unpack():\n    x = 100\n\n    def inner():\n        # x in unpacking shadows the outer x, but we can still reference outer x in expression\n        # Actually, the x in the comprehension shadows outer x, so this tests scope isolation\n        pairs = [(1, 2), (3, 4)]\n        return [x + y for x, y in pairs]\n\n    return inner()\n\n\nassert outer_shadow_unpack() == [3, 7]\n\n# === Generator expressions (temporary: treated as list comprehensions) ===\n# TODO: When proper generators are implemented, these should return generator objects\n# instead of lists. For now, generator expressions are parsed as list comprehensions.\n# See iter__generator_expr.py for tests, and iter__generator_expr_type.py for\n# a type check test (xfail=cpython since CPython has real generators).\n\n# Generator in list() call - works identically in both Monty and CPython\nassert list(x for x in [1, 2, 3]) == [1, 2, 3]\nassert tuple(x for x in [1, 2, 3]) == (1, 2, 3)\n\n# Generator with condition\nassert list(x for x in range(10) if x % 2 == 0) == [0, 2, 4, 6, 8]\n\n# Nested generators\nassert list(x + y for x in range(3) for y in range(2)) == [0, 1, 1, 2, 2, 3]\n\n# Generator in sum()\nassert sum(x for x in range(5)) == 10\n\n# Generator with unpacking\npairs = [(1, 2), (3, 4)]\nassert list(a + b for a, b in pairs) == [3, 7]\n\n# list of strings join\nassert ''.join(str(x) for x in range(5)) == '01234'\na = '1', '2', '3'\nassert ''.join(a) == '123'\n\n# === Regression: Iterator panic with try/except inside loop ===\n# Issue: https://github.com/pydantic/monty/issues/177\n# Verifies that exception handling in a comprehension inside a loop doesn't\n# corrupt the outer loop's iterator (causing \"expected Iterator on heap\" panic).\n# A prior loop is needed to potentially trigger incorrect stack depth tracking.\nfor _ in range(1):\n    pass\n\nfor s in ['hello']:\n    try:\n        # Inner comprehension raises exception\n        [int(c) for c in s]\n    except ValueError:\n        pass\n",
  'comprehension__scope.py':
      "# === Target absence in globals() at module scope ===\n[x for x in range(10)]\n\ntry:\n    x\n    assert False, \"Expected NameError for 'x' after comprehension\"\nexcept NameError:\n    pass\n\n# === Outer variable preservation ===\nouter_x = 5\n[outer_x for outer_x in [1, 2, 3]]\nassert outer_x == 5\n\n# === Walrus binds in enclosing scope ===\n# PEP 572: walrus targets are assigned in the enclosing scope, even when written\n# inside a comprehension.\nwalrus_result = [(walrus_y := walrus_w) for walrus_w in [1, 2, 3]]\nassert walrus_result == [1, 2, 3]\nassert walrus_y == 3\n\n# === Nested same-name targets simultaneously live ===\nmatrix = [[1, 2], [3, 4]]\nnested = [[inner_x * 10 for inner_x in inner_x] for inner_x in matrix]\nassert nested == [[10, 20], [30, 40]]\n\n# === Sibling comps reusing the same comp-var stack slot ===\n# Each RaiseUnboundLocal carries its own name in the opcode, so an unbound-name\n# error in the second sibling must report the second sibling's target name —\n# not whichever name the compiler emitted first for the shared slot.\n[first_name for first_name in [1, 2]]\ntry:\n    [_s for _s in [1] for _ignored in [second_late] for second_late in [[2]]]\n    assert False, 'expected UnboundLocalError from second sibling comp'\nexcept UnboundLocalError as exc:\n    assert str(exc) == \"cannot access local variable 'second_late' where it is not associated with a value\"\n\n# === Nested-tuple comp target (exercises LiftToTop) ===\n# Flat parts of the tuple stay at their UNPACK position; the inner (b, c)\n# requires a Lift to bring it to TOS for further unpacking. The compiler\n# tracks each leaf's final operand-stack offset.\nitems = [(1, (2, 3), 4), (5, (6, 7), 8)]\nflat_nested = [a + b + c + d for a, (b, c), d in items]\nassert flat_nested == [10, 26]\n\n# Doubly-nested tuple\nnested_pairs = [((1, 2), (3, 4))]\ndoubly_nested = [(a, b, c, d) for (a, b), (c, d) in nested_pairs]\nassert doubly_nested == [(1, 2, 3, 4)]\n\n# Starred sub-target in a comp\nstarred = [(a, rest, last) for a, *rest, last in [(1, 2, 3, 4, 5)]]\nassert starred == [(1, [2, 3, 4], 5)]\n",
  'comprehension__unbound_local.py':
      "# Test that comprehension scoping raises UnboundLocalError when a generator's iter\n# references a later generator's loop variable (which is local but not yet assigned)\n\nz = ['outer']\n\nresult = [x for x in [1] for y in z for z in [[2], [3]]]\n\"\"\"\nTRACEBACK:\nTraceback (most recent call last):\n  File \"comprehension__unbound_local.py\", line 6, in <module>\n    result = [x for x in [1] for y in z for z in [[2], [3]]]\n                                      ~\nUnboundLocalError: cannot access local variable 'z' where it is not associated with a value\n\"\"\"\n",
  'dataclass__basic.py':
      "# call-external\n# === Basic dataclass tests ===\n\n# Get immutable dataclass from external function\npoint = make_point()\n\n# === repr and str ===\nassert repr(point) == 'Point(x=1, y=2)', f'point repr {point=!r}'\nassert str(point) == 'Point(x=1, y=2)'\n\n# === Boolean truthiness ===\n# Dataclasses are always truthy (like Python class instances)\nassert bool(point)\n\n# === Hash for immutable dataclass ===\n# Immutable (frozen) dataclasses are hashable\nh1 = hash(point)\nassert h1 != 0\n\n# Hash is consistent - same object hashes to same value\nh2 = hash(point)\nassert h1 == h2\n\n# Equal frozen dataclasses hash to same value\npoint2 = make_point()\nassert hash(point) == hash(point2)\n\n# Frozen dataclass can be used as dict key\nd = {point: 'first'}\nassert d[point] == 'first'\nassert d[point2] == 'first'\n\n# Frozen dataclass can be added to set\ns = {point, point2}\nassert len(s) == 1\n\n# Different field values produce different hash\nalice = make_user('Alice')\nbob = make_user('Bob')\nassert hash(alice) != hash(bob)\n\n# === Equality ===\nassert point == point2\nassert alice != bob\nassert point != alice\n# A dataclass is never equal to a non-dataclass, even with matching fields\nassert point != (1, 2)\nassert point != {'x': 1, 'y': 2}\n\n# === Mutable dataclass ===\nmut_point = make_mutable_point()\nassert repr(mut_point) == 'MutablePoint(x=1, y=2)', f'mutable point repr {mut_point=!r}'\n# Distinct classes are not equal even with identical field names and values\n# (Point and MutablePoint are both (x=1, y=2)).\nassert point != mut_point\nassert mut_point != point\n\n# === Dataclass with string argument ===\nalice = make_user('Alice')\nassert repr(alice) == \"User(name='Alice', active=True)\", f'user repr with string field {alice=!r}'\n\n# === Dataclass in list (using existing variables) ===\npoints = [point, mut_point, alice]\nassert len(points) == 3\n\n# === Attribute access (get) ===\n# Access fields on immutable dataclass\nassert point.x == 1\nassert point.y == 2\n\n# Access fields on mutable dataclass\nassert mut_point.x == 1\nassert mut_point.y == 2\n\n# Access fields on dataclass with string field\nassert alice.name == 'Alice'\nassert alice.active == True\n\n# === Attribute assignment (set) ===\n# Modify mutable dataclass\nmut_point.x = 10\nassert mut_point.x == 10\nmut_point.y = 20\nassert mut_point.y == 20\nassert repr(mut_point) == 'MutablePoint(x=10, y=20)', f'repr after attribute update {mut_point=!r}'\n\n# === set other attributes\nmut_point.z = 30\nassert mut_point.z == 30\nassert repr(mut_point) == 'MutablePoint(x=10, y=20)'\n\n# === Augmented attribute assignment (+=, -=, etc.) ===\naug_point = make_mutable_point()\naug_point.x += 5\nassert aug_point.x == 6\naug_point.y -= 1\nassert aug_point.y == 1\naug_point.x *= 3\nassert aug_point.x == 18\n\n# === Chained augmented attribute assignment ===\nouter_aug = make_mutable_point()\ninner_aug = make_mutable_point()\nouter_aug.x = inner_aug\nouter_aug.x.y += 100\nassert inner_aug.y == 102\n\n# === Chained attribute assignment (a.x = b.x = value) ===\nca = make_mutable_point()\ncb = make_mutable_point()\nca.x = cb.x = 77\nassert ca.x == 77\nassert cb.x == 77\n\n# === Chained mixed attribute/name/subscript assignment ===\n# Attribute in the *middle* of a chain, between a name and a subscript target.\nholder = [0]\ncm = make_mutable_point()\nval = cm.y = holder[0] = 321\nassert val == 321\nassert cm.y == 321\nassert holder[0] == 321\n\n# === Attribute as the *last* target of a chain ===\nattr_last_name_box = [0]\nattr_last_obj = make_mutable_point()\nattr_last_name = attr_last_name_box[0] = attr_last_obj.y = 555\nassert attr_last_name == 555\nassert attr_last_name_box[0] == 555\nassert attr_last_obj.y == 555\n\n# === Attribute as the *first* (non-last) target of a chain ===\nattr_first_obj = make_mutable_point()\nattr_first_obj.x = attr_first_name = 556\nassert attr_first_obj.x == 556\nassert attr_first_name == 556\n\n# === Three attribute targets in one chain ===\npa = make_mutable_point()\npb = make_mutable_point()\npc = make_mutable_point()\npa.x = pb.x = pc.x = 999\nassert pa.x == 999\nassert pb.x == 999\nassert pc.x == 999\n\n# === Nested attribute target as part of a chain ===\nnest_outer = make_mutable_point()\nnest_inner = make_mutable_point()\nnest_outer.x = nest_inner\nnested_chain_name = nest_outer.x.y = 444\nassert nested_chain_name == 444\nassert nest_inner.y == 444\nassert nest_outer.x.y == 444\n\n# === Chain with attribute + tuple unpack into attribute values ===\n# Each chain step must see the same RHS value.\nunpack_dst = make_mutable_point()\n(ua1, ua2) = unpack_dst.x = unpack_chain_name = (13, 14)\nassert ua1 == 13 and ua2 == 14, 'attr-unpack chain: unpack'\nassert unpack_dst.x == (13, 14)\nassert unpack_chain_name == (13, 14)\n\n# === Nested attribute access (chained get) ===\n# Create outer dataclass with inner dataclass as field\nouter = make_mutable_point()\ninner = make_mutable_point()\ninner.x = 100\ninner.y = 200\nouter.x = inner\n\n# Chained attribute get: outer.x.y\nassert outer.x.x == 100\nassert outer.x.y == 200\n\n# === Nested attribute assignment (chained set) ===\n# Modify nested field via chained access\nouter.x.x = 999\nassert outer.x.x == 999\nouter.x.y = 888\nassert outer.x.y == 888\n\n# Verify inner was modified (same object)\nassert inner.x == 999\nassert inner.y == 888\n\n# === Deeper nesting (3 levels) ===\nlevel1 = make_mutable_point()\nlevel2 = make_mutable_point()\nlevel3 = make_mutable_point()\nlevel3.x = 42\nlevel2.x = level3\nlevel1.x = level2\n\n# 3-level chained get\nassert level1.x.x.x == 42\n\n# 3-level chained set\nlevel1.x.x.x = 7\nassert level1.x.x.x == 7\nassert level3.x == 7\n\n# === Empty dataclass ===\nempty = make_empty()\nassert repr(empty) == 'Empty()'\nassert str(empty) == 'Empty()'\n\n# === FrozenInstanceError is subclass of AttributeError ===\n# Catching AttributeError should also catch FrozenInstanceError\nfrozen_point = make_point()\ncaught = False\ntry:\n    frozen_point.x = 10\nexcept AttributeError:\n    caught = True\nassert caught\n\n# === Error: accessing non-existent attribute ===\ntry:\n    point.nonexistent\n    assert False, 'should have raised AttributeError for missing attr'\nexcept AttributeError as e:\n    assert str(e) == \"'Point' object has no attribute 'nonexistent'\", f'wrong message: {e}'\n\n# === Error: accessing non-existent private attribute ===\ntry:\n    point._private\n    assert False, 'should have raised AttributeError for private attr'\nexcept AttributeError as e:\n    assert str(e) == \"'Point' object has no attribute '_private'\", f'wrong message: {e}'\n\n# === Error: calling a dunder that doesn't exist ===\ntry:\n    point.__nonexistent__()\n    assert False, 'should have raised AttributeError for dunder'\nexcept AttributeError as e:\n    assert str(e) == \"'Point' object has no attribute '__nonexistent__'\", f'wrong message: {e}'\n\n# === Error: calling a private method that doesn't exist ===\ntry:\n    point._private_method()\n    assert False, 'should have raised AttributeError for private method'\nexcept AttributeError as e:\n    assert str(e) == \"'Point' object has no attribute '_private_method'\", f'wrong message: {e}'\n\n# === Error: calling a field value (not callable) ===\ntry:\n    point.x()\n    assert False, 'should have raised TypeError for calling int field'\nexcept TypeError as e:\n    assert str(e) == \"'int' object is not callable\", f'wrong message: {e}'\n\n# === Error: calling a non-existent public method ===\ntry:\n    point.nonexistent_method()\n    assert False, 'should have raised AttributeError for missing method'\nexcept AttributeError as e:\n    assert str(e) == \"'Point' object has no attribute 'nonexistent_method'\", f'wrong message: {e}'\n\n# === Error: same errors on mutable dataclass ===\ntry:\n    mut_point.nonexistent\n    assert False, 'should have raised AttributeError on mutable dc'\nexcept AttributeError as e:\n    assert str(e) == \"'MutablePoint' object has no attribute 'nonexistent'\", f'wrong message: {e}'\n\ntry:\n    mut_point.x()\n    assert False, 'should have raised TypeError on mutable dc field call'\nexcept TypeError as e:\n    assert str(e) == \"'int' object is not callable\", f'wrong message: {e}'\n\n# === Method calls: no args (exercises ArgValues::prepend on Empty) ===\nresult = point.sum()\nassert result == 3, f'Point.sum() should be 3, got {result}'\n\n# === Method calls: two positional args (exercises ArgValues::prepend on Two) ===\nnew_point = point.add(10, 20)\nassert new_point.x == 11, f'Point.add x should be 11, got {new_point.x}'\nassert new_point.y == 22, f'Point.add y should be 22, got {new_point.y}'\n\n# === Method calls: one positional arg (exercises ArgValues::prepend on One) ===\nscaled = point.scale(3)\nassert scaled.x == 3, f'Point.scale x should be 3, got {scaled.x}'\nassert scaled.y == 6, f'Point.scale y should be 6, got {scaled.y}'\n\n# === Method calls: returning a string ===\ndesc = point.describe('pt')\nassert desc == 'pt(1, 2)', f'Point.describe should be pt(1, 2), got {desc}'\n\n# === Method calls on mutable dataclass ===\nmut_p2 = make_mutable_point()\nmut_sum = mut_p2.sum()\nassert mut_sum == 3, f'MutablePoint.sum() should be 3, got {mut_sum}'\n\n# === Method calls on User dataclass (string field) ===\nalice2 = make_user('Alice')\ngreeting = alice2.greeting()\nassert greeting == 'Hello, Alice!', f'User.greeting should be Hello, Alice!, got {greeting}'\n\n# === Method call returning dataclass - chained access ===\np3 = point.add(0, 0)\nassert p3.x == 1, f'chained method access: p3.x should be 1, got {p3.x}'\nassert p3.y == 2, f'chained method access: p3.y should be 2, got {p3.y}'\n\n# === Method calls with keyword-only args (exercises ArgValues::prepend on Kwargs) ===\ndesc_kw = point.describe(label='custom')\nassert desc_kw == 'custom(1, 2)', f'Point.describe(label=) should be custom(1, 2), got {desc_kw}'\n\n# === Error: calling non-existent method on mutable dataclass ===\ntry:\n    mut_p2.nonexistent_method()\n    assert False, 'should have raised AttributeError for missing method on mutable dc'\nexcept AttributeError as e:\n    assert str(e) == \"'MutablePoint' object has no attribute 'nonexistent_method'\", f'wrong message: {e}'\n\n# === Error: calling non-existent method on User ===\ntry:\n    alice2.missing()\n    assert False, 'should have raised AttributeError for missing method on User'\nexcept AttributeError as e:\n    assert str(e) == \"'User' object has no attribute 'missing'\", f'wrong message: {e}'\n",
