  'execute_ok__all.py':
      "# === Basic arithmetic ===\nassert 1 + 1 == 2\nassert 'a' + 'b' == 'ab'\n\n# === Equality tests ===\nassert (1 == 1) == True\nassert (1 == 2) == False\nassert ('a' == 'a') == True\nassert ('a' == 'b') == False\nassert ([1, 2] == [1, 2]) == True\nassert ((1, 2) == (1, 2)) == True\nassert (b'hello' == b'hello') == True\n\n# === Boolean repr/str ===\nassert repr(True) == 'True'\nassert str(True) == 'True'\nassert repr(False) == 'False'\nassert str(False) == 'False'\n\n# === None repr/str ===\nassert repr(None) == 'None'\nassert str(None) == 'None'\n\n# === Ellipsis repr/str ===\nassert repr(...) == 'Ellipsis'\nassert str(...) == 'Ellipsis'\n\n# === List repr/str ===\nassert repr([1, 2]) == '[1, 2]'\nassert str([1, 2]) == '[1, 2]'\n\n# === Discard expression result ===\na = 1\n[1, 2, 3]  # this list is created and discarded\nassert a == 1\n\n# === Shared list append ===\na = [1]\nb = a\nb.append(2)\nassert len(a) == 2\n\n# === For loop string append ===\nv = ''\nfor i in range(1000):\n    if i % 13 == 0:\n        v = v + 'x'\nassert len(v) == 77\n\nv = ''\nfor i in range(1000):\n    if i % 13 == 0:\n        v += 'x'\nassert len(v) == 77\n",
