  'ext_call__arg_side_effect_bug.py':
      "# call-external\n# BUG: Side effects in arguments are duplicated when external call suspends\n#\n# When an external call is in one argument position and there's a side effect\n# in another argument position, the side effect may be executed multiple times\n# because argument evaluation is repeated during resumption.\n\ncall_count = 0\n\n\ndef side_effect(val):\n    global call_count\n    call_count += 1\n    return val\n\n\n# Side effect before external call in args\n# Expected: side_effect runs once, result is 10 + 3 = 13\ncall_count = 0\nresult = add_ints(side_effect(10), add_ints(1, 2))\nassert result == 13\nassert call_count == 1\n",
  'ext_call__augmented.py':
      "# call-external\n# External calls in augmented assignment expressions\n\n# += with external call\nx = 10\nx += add_ints(5, 5)\nassert x == 20\n\n# -= with external call\nx = 100\nx -= add_ints(20, 30)\nassert x == 50\n\n# *= with external call\nx = 5\nx *= add_ints(2, 1)\nassert x == 15\n",
  'ext_call__augmented_refcount_bug.py':
      "# call-external\n# BUG: Reference counting bug with string augmented assignment and external calls\n\n# String += with external call causes reference counting error\ns = 'hello'\ns += concat_strings(' ', 'world')\nassert s == 'hello world'\n",
  'ext_call__bare_raise_after_resume.py':
      "# call-external\n# Test bare raise after external call resumption in except handler\n# This tests that current_exception is properly restored after resuming\n# Note: bare raise after resumption only works when exception is bound (as e)\n\ncaught_reraised = False\ntry:\n    try:\n        raise ValueError('original error')\n    except ValueError as e:\n        # Make an external call, which will cause a suspend/resume\n        x = add_ints(1, 2)\n        # After resuming, bare raise should still work (exception restored from binding)\n        raise\nexcept ValueError as outer_e:\n    caught_reraised = repr(outer_e) == \"ValueError('original error')\"\n\nassert caught_reraised\n\n# === Nested handler bare raise after resumption ===\nouter_nested_reraise = False\ntry:\n    try:\n        raise ValueError('outer error')\n    except ValueError:\n        try:\n            raise KeyError('inner error')\n        except KeyError:\n            _ = add_ints(1, 2)\n        raise\nexcept ValueError as reraised:\n    outer_nested_reraise = repr(reraised) == \"ValueError('outer error')\"\n\nassert outer_nested_reraise\n",
  'ext_call__basic.py':
      "# call-external\n# === Basic external function tests ===\n\n# Simple calls\na = add_ints(10, 20)\nassert a == 30\n\nb = add_ints(-5, 15)\nassert b == 10\n\ns = concat_strings('hello', ' world')\nassert s == 'hello world'\n\nx = return_value(42)\nassert x == 42\n\ny = return_value('test')\nassert y == 'test'\n\n# === Assignment with external calls ===\nresult = add_ints(100, 200)\nassert result == 300\n\nname = concat_strings('foo', 'bar')\nassert name == 'foobar'\n\n# === Nested calls ===\nnested = add_ints(1, add_ints(2, 3))\nassert nested == 6\n\nnested2 = add_ints(add_ints(1, 2), 3)\nassert nested2 == 6\n\nnested3 = add_ints(add_ints(1, 2), add_ints(3, 4))\nassert nested3 == 10\n\ndeep = add_ints(add_ints(add_ints(1, 2), 3), 4)\nassert deep == 10\n\n# === Chained operations ===\nchained = add_ints(1, 2) + add_ints(3, 4)\nassert chained == 10\n\nchained2 = add_ints(10, 20) - add_ints(5, 10)\nassert chained2 == 15\n\nchained3 = add_ints(2, 3) * add_ints(4, 5)\nassert chained3 == 45\n\nstr_chain = concat_strings('a', 'b') + concat_strings('c', 'd')\nassert str_chain == 'abcd'\n\n# === External calls in assert statements ===\nassert add_ints(5, 5) == 10\nassert return_value(True)\nassert concat_strings('x', 'y') == 'xy'\nassert add_ints(1, add_ints(2, 3)) == 6\n\n# === Mixed with builtins ===\nlength = len(concat_strings('hello', 'world'))\nassert length == 10\n\nitems = [add_ints(1, 2), add_ints(3, 4)]\nassert items[0] == 3\nassert items[1] == 7\n\n# === Multiple external calls in single expression ===\n\n# Two ext calls added together\nsum_result = add_ints(1, 2) + add_ints(3, 4)\nassert sum_result == 10\n\n# Three ext calls in one expression\ntriple = add_ints(1, 1) + add_ints(2, 2) + add_ints(3, 3)\nassert triple == 12\n\n# Ext calls in multiplication\nmul_result = add_ints(2, 3) * add_ints(1, 1)\nassert mul_result == 10\n\n# Ext calls in subtraction\nsub_result = add_ints(10, 5) - add_ints(3, 2)\nassert sub_result == 10\n\n# Complex expression with multiple ext calls\ncomplex_expr = (add_ints(1, 2) + add_ints(3, 4)) * add_ints(0, 2)\nassert complex_expr == 20\n\n# String concatenation with multiple ext calls\nstr_result = concat_strings(return_value('a'), return_value('b')) + concat_strings('c', 'd')\nassert str_result == 'abcd'\n\n# Comparison with multiple ext calls\ncmp_result = add_ints(5, 5) == add_ints(3, 7)\nassert cmp_result == True\n\n# Nested ext calls in expression\nnested_expr = add_ints(add_ints(1, 2), add_ints(3, 4))\nassert nested_expr == 10\n",
  'ext_call__boolean.py':
      "# call-external\n# External calls in boolean short-circuit expressions\n\n# === Basic boolean operations ===\nresult = return_value(True) and return_value(42)\nassert result == 42\n\nresult = return_value(False) and return_value(42)\nassert result == False\n\nresult = return_value(0) or return_value(42)\nassert result == 42\n\nresult = return_value(99) or return_value(42)\nassert result == 99\n\n\n# === Chained boolean with external calls ===\nresult = return_value(True) and return_value(True) and return_value(42)\nassert result == 42\n\nresult = return_value(True) and return_value(False) and return_value(42)\nassert result == False\n\nresult = return_value(0) or return_value(0) or return_value(42)\nassert result == 42\n\nresult = return_value(0) or return_value(99) or return_value(42)\nassert result == 99\n\n\n# === Mixed and/or ===\nresult = return_value(True) and return_value(0) or return_value(42)\nassert result == 42\n\nresult = return_value(0) or return_value(True) and return_value(42)\nassert result == 42\n",
  'ext_call__boolean_side_effect_hang.py':
      "# call-external\n# BUG: This test hangs (infinite loop) - external calls in boolean expressions\n# with side effects cause incorrect behavior.\n\ncall_count = 0\n\n\ndef side_effect(val):\n    global call_count\n    call_count += 1\n    return val\n\n\n# This specific pattern causes a hang in Monty\nresult = return_value(True) and return_value(side_effect(42))\nassert result == 42\nassert call_count == 1\n",
  'ext_call__closure_bug.py':
      "# call-external\n# BUG: External calls in closures cannot access captured variables\n# When an external call is inside a closure, it fails to access free variables\n# Error: \"cannot access free variable 'x' where it is not associated with a value\"\n\n\ndef make_adder(x):\n    def adder(y):\n        return add_ints(x, y)\n\n    return adder\n\n\nadd5 = make_adder(5)\nresult = add5(10)\nassert result == 15\n",
  'ext_call__comparison.py':
      "# call-external\n# External calls in comparison expressions\n\n# External call on left side of comparison\nresult = add_ints(1, 2) == 3\nassert result == True\n\n# External call on right side\nresult = 3 == add_ints(1, 2)\nassert result == True\n\n# Both sides external calls\nresult = add_ints(1, 2) == add_ints(2, 1)\nassert result == True\n\n# Less than\nresult = add_ints(1, 1) < add_ints(2, 2)\nassert result == True\n\n# Greater than\nresult = add_ints(5, 5) > add_ints(2, 2)\nassert result == True\n\n# Not equal\nresult = add_ints(1, 2) != add_ints(3, 4)\nassert result == True\n",
  'ext_call__deep_call_stack.py':
      "# call-external\n# External function calls in deep call stacks (function calling function).\n# Tests that the outer function receives the return value correctly when\n# the inner function makes an external call.\n\n\ndef depth1(n):\n    return add_ints(n, 1)\n\n\ndef depth2(n):\n    return depth1(n) + 10\n\n\nresult = depth2(5)\n# depth2(5) should be: depth1(5) + 10 = 6 + 10 = 16\n\nassert result == 16, f'ext call through 2 levels of functions {result=}'\n",
  'ext_call__elif.py':
      "# call-external\n# === External calls in elif conditions ===\n\n# External call in elif condition - true\nresult1 = 0\nif add_ints(1, 1) == 3:\n    result1 = 1\nelif add_ints(2, 2) == 4:\n    result1 = 2\nelse:\n    result1 = 3\nassert result1 == 2, f'elif condition with ext call should be evaluated, {result1=}'\n\n# External call in elif condition - falls through to else\nresult2 = 0\nif add_ints(1, 1) == 3:\n    result2 = 1\nelif add_ints(2, 2) == 5:\n    result2 = 2\nelse:\n    result2 = 3\nassert result2 == 3\n\n# Multiple elif with external calls\nresult3 = 0\nif add_ints(1, 1) == 10:\n    result3 = 1\nelif add_ints(2, 2) == 10:\n    result3 = 2\nelif add_ints(3, 3) == 6:\n    result3 = 3\nelif add_ints(4, 4) == 10:\n    result3 = 4\nelse:\n    result3 = 5\nassert result3 == 3\n\n# === External calls in elif bodies ===\n\n# Ext call in elif body\nval1 = 0\nif False:\n    val1 = 1\nelif True:\n    val1 = add_ints(10, 20)\nelse:\n    val1 = 3\nassert val1 == 30\n\n# Ext call in else body after elif chain\nval2 = 0\nif False:\n    val2 = 1\nelif False:\n    val2 = 2\nelse:\n    val2 = add_ints(15, 25)\nassert val2 == 40\n\n# Multiple ext calls in elif body\nval3 = 0\nif False:\n    val3 = 1\nelif True:\n    a = add_ints(5, 5)\n    b = add_ints(10, 10)\n    val3 = add_ints(a, b)\nelse:\n    val3 = 3\nassert val3 == 30\n\n# === Nested ext calls ===\n\n# Nested ext calls in elif condition\nresult4 = 0\nif False:\n    result4 = 1\nelif add_ints(add_ints(1, 2), add_ints(3, 4)) == 10:\n    result4 = 2\nelse:\n    result4 = 3\nassert result4 == 2\n\n# === Short-circuit with ext calls ===\n\n# Ext call should not be evaluated if earlier condition is true\ncall_count = 0\n\n\ndef counting_add(a, b):\n    global call_count\n    call_count = call_count + 1\n    return a + b\n\n\n# This uses a regular function, not ext call, to verify short-circuit\n# but the ext calls in bodies still test suspension\nx = 0\nif True:\n    x = add_ints(1, 1)\nelif False:\n    x = add_ints(2, 2)\nassert x == 2\n\n# === Ext call in both condition and body ===\n\nresult5 = 0\nif add_ints(1, 1) == 3:\n    result5 = add_ints(100, 100)\nelif add_ints(2, 2) == 4:\n    result5 = add_ints(50, 50)\nelse:\n    result5 = add_ints(25, 25)\nassert result5 == 100\n\n# === Ext call in if body when condition is true ===\n\nif_body_result = 0\nif add_ints(5, 5) == 10:\n    if_body_result = add_ints(100, 200)\nelif add_ints(1, 1) == 2:\n    if_body_result = add_ints(10, 20)\nelse:\n    if_body_result = add_ints(1, 2)\nassert if_body_result == 300\n\n# === Ext calls returning values used as conditions ===\n\n# return_value returns its argument, so we can use it to test boolean coercion\ncond_result = 0\nif return_value(0):\n    cond_result = 1\nelif return_value(1):\n    cond_result = 2\nelse:\n    cond_result = 3\nassert cond_result == 2\n\n# === Ext calls with string concatenation ===\n\nstr_result = ''\nif add_ints(1, 1) == 3:\n    str_result = concat_strings('a', 'b')\nelif add_ints(2, 2) == 4:\n    str_result = concat_strings('hello', ' world')\nelse:\n    str_result = concat_strings('x', 'y')\nassert str_result == 'hello world'\n\n# === Multiple conditions with ext calls in same expression ===\n\nmulti_cond = 0\nif add_ints(1, 1) > 5:\n    multi_cond = 1\nelif add_ints(2, 2) < add_ints(3, 3):\n    multi_cond = 2\nelse:\n    multi_cond = 3\nassert multi_cond == 2\n\n# === Ext call in all three branches ===\n\nall_branches = 0\nval = add_ints(5, 5)\nif val < 5:\n    all_branches = add_ints(1, 0)\nelif val < 15:\n    all_branches = add_ints(2, 0)\nelse:\n    all_branches = add_ints(3, 0)\nassert all_branches == 2\n",
