  'ext_call__exc_nested_functions.py':
      "# call-external\ndef inner():\n    raise_error('TypeError', 'nested error')\n\n\ndef middle():\n    inner()\n\n\ndef outer():\n    middle()\n\n\nouter()\n\"\"\"\nTRACEBACK:\nTraceback (most recent call last):\n  File \"ext_call__exc_nested_functions.py\", line 14, in <module>\n    outer()\n    ~~~~~~~\n  File \"ext_call__exc_nested_functions.py\", line 11, in outer\n    middle()\n    ~~~~~~~~\n  File \"ext_call__exc_nested_functions.py\", line 7, in middle\n    inner()\n    ~~~~~~~\n  File \"ext_call__exc_nested_functions.py\", line 3, in inner\n    raise_error('TypeError', 'nested error')\n    ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\nTypeError: nested error\n\"\"\"\n",
  'ext_call__ext_exc.py':
      "# call-external\n# === External function exceptions ===\n# Tests for exceptions raised by external functions\n\n# === Basic exception propagation ===\n\n# External function raising ValueError\ncaught_value_error = False\ntry:\n    result = raise_error('ValueError', 'test error')\n    assert False, 'should not reach here'\nexcept ValueError:\n    caught_value_error = True\nassert caught_value_error\n\n# External function raising TypeError\ncaught_type_error = False\ntry:\n    result = raise_error('TypeError', 'type error message')\n    assert False, 'should not reach here'\nexcept TypeError:\n    caught_type_error = True\nassert caught_type_error\n\n# External function raising KeyError\ncaught_key_error = False\ntry:\n    result = raise_error('KeyError', 'missing key')\n    assert False, 'should not reach here'\nexcept KeyError:\n    caught_key_error = True\nassert caught_key_error\n\n# External function raising RuntimeError\ncaught_runtime_error = False\ntry:\n    result = raise_error('RuntimeError', 'runtime error')\n    assert False, 'should not reach here'\nexcept RuntimeError:\n    caught_runtime_error = True\nassert caught_runtime_error\n\n# === Exception not caught by wrong handler ===\n\n# ValueError not caught by TypeError handler\ncaught_outer = False\ntry:\n    try:\n        raise_error('ValueError', 'inner error')\n    except TypeError:\n        assert False, 'TypeError should not catch ValueError'\nexcept ValueError:\n    caught_outer = True\nassert caught_outer\n\n# === Exception in expression with multiple ext calls ===\n\n# First ext call raises, second should not be called\ntry:\n    x = raise_error('ValueError', 'first') + add_ints(1, 2)\n    assert False, 'should not reach here'\nexcept ValueError:\n    pass  # Expected\n\n# === External exception in try body with finally ===\n\nfinally_ran = False\ntry:\n    raise_error('ValueError', 'in try')\nexcept ValueError:\n    pass  # Caught\nfinally:\n    finally_ran = True\nassert finally_ran\n\n# External exception propagating through finally\nouter_caught = False\nfinally_ran2 = False\ntry:\n    try:\n        raise_error('KeyError', 'will propagate')\n    except ValueError:\n        assert False, 'ValueError should not catch KeyError'\n    finally:\n        finally_ran2 = True\nexcept KeyError:\n    outer_caught = True\nassert finally_ran2\nassert outer_caught\n\n# === Mix of normal returns and exceptions ===\n\n# Normal return, then exception\nvalue1 = add_ints(10, 20)\nassert value1 == 30\ntry:\n    raise_error('ValueError', 'after success')\n    assert False, 'should not reach here'\nexcept ValueError:\n    pass  # Expected\n\n# Exception, then normal return (after catching)\ncaught_exc = False\ntry:\n    raise_error('TypeError', 'will be caught')\nexcept TypeError:\n    caught_exc = True\nvalue2 = add_ints(5, 5)\nassert caught_exc\nassert value2 == 10\n\n# === Exception in except handler from external function ===\n\nouter_catch = False\ntry:\n    try:\n        raise ValueError('inner')\n    except ValueError:\n        raise_error('TypeError', 'from handler')\nexcept TypeError:\n    outer_catch = True\nassert outer_catch\n\n# === Exception in else block from external function ===\n\nelse_exc_caught = False\ntry:\n    try:\n        pass  # No exception\n    except:\n        assert False, 'should not reach except'\n    else:\n        raise_error('RuntimeError', 'from else')\nexcept RuntimeError:\n    else_exc_caught = True\nassert else_exc_caught\n\n# === Exception in finally block ===\n\n# Note: exception in finally replaces any pending exception\nfinally_exc_caught = False\ntry:\n    try:\n        pass\n    finally:\n        raise_error('ValueError', 'from finally')\nexcept ValueError:\n    finally_exc_caught = True\nassert finally_exc_caught\n\n# === Nested try blocks with external exceptions ===\n\ninner_handled = False\nouter_handled = False\nfinally_count = 0\ntry:\n    try:\n        raise_error('ValueError', 'inner error')\n    except ValueError:\n        inner_handled = True\n        raise_error('TypeError', 'from inner handler')\n    finally:\n        finally_count += 1\nexcept TypeError:\n    outer_handled = True\nfinally:\n    finally_count += 1\n\nassert inner_handled\nassert outer_handled\nassert finally_count == 2\n",
  'ext_call__for.py':
      "# call-external\n# === External calls in for loops ===\n\n# Ext call in loop body\ntotal = 0\nfor i in range(3):\n    total = add_ints(total, 1)\nassert total == 3, f'ext call accumulator in loop, {total=}'\n\n# Ext call with loop variable\nsum_val = 0\nfor i in range(4):\n    sum_val = add_ints(sum_val, i)\nassert sum_val == 6\n\n# Multiple ext calls per iteration\nresult = 0\nfor i in range(3):\n    result = add_ints(result, add_ints(i, i))\nassert result == 6\n\n# Building list with ext calls\nitems = []\nfor i in range(3):\n    items.append(add_ints(i, 10))\nassert items[0] == 10\nassert items[1] == 11\nassert items[2] == 12\n\n# Chained ext calls in loop\nacc = 0\nfor i in range(3):\n    acc = add_ints(acc, 1) + add_ints(0, 1)\nassert acc == 6\n\n# Nested loops with ext calls\nmatrix_sum = 0\nfor i in range(2):\n    for j in range(2):\n        matrix_sum = add_ints(matrix_sum, add_ints(i, j))\nassert matrix_sum == 4\n\n# === More nested loop edge cases ===\n\n# Nested loops building a result list\nresults = []\nfor i in range(2):\n    for j in range(2):\n        results.append(concat_strings(return_value(str(i)), return_value(str(j))))\nassert results[0] == '00'\nassert results[1] == '01'\nassert results[2] == '10'\nassert results[3] == '11'\n\n# If inside for loop with external call condition\nfiltered = []\nfor i in range(3):\n    if return_value(i) == i:\n        filtered.append(i)\nassert filtered == [0, 1, 2]\n\n# If inside for loop - some iterations match\nresults2 = []\nfor i in range(4):\n    # Only append even numbers (using modulo check with add_ints)\n    if add_ints(i, 0) % 2 == 0:\n        results2.append(return_value(i))\nassert results2 == [0, 2]\n\n# Nested for with different ranges\nouter_sum = 0\nfor i in range(2):\n    inner_sum = 0\n    for j in range(3):\n        inner_sum = add_ints(inner_sum, add_ints(i, j))\n    outer_sum = add_ints(outer_sum, inner_sum)\n# i=0: (0+0)+(0+1)+(0+2) = 0+1+2 = 3\n# i=1: (1+0)+(1+1)+(1+2) = 1+2+3 = 6\n# total = 3 + 6 = 9\nassert outer_sum == 9\n\n# Three levels of nested loops\ncount = 0\nfor i in range(2):\n    for j in range(2):\n        for k in range(2):\n            count = add_ints(count, 1)\nassert count == 8\n\n# multiple ext calls in iterable\n\next_ints = []\nfor i in add_ints(1, 1), add_ints(2, 2), add_ints(3, 3):\n    ext_ints.append(i)\nassert ext_ints == [2, 4, 6]\n\n# ext call iterable, get_list() returns [1, 2, 3]\ntotal = 0\nfor x in get_list():\n    total = add_ints(total, x)\nassert total == 6\n\n# string iteration with ext call in body\nchars = []\nfor c in 'abc':\n    chars.append(return_value(c))\nassert chars == ['a', 'b', 'c'], f'string iteration with ext call: {chars}'\n\n# unicode string iteration with ext call in body\n# Tests decr() handling of multi-byte UTF-8 characters (1-4 bytes each)\nunicode_chars = []\nfor c in 'aé中😀b':  # a (1 byte), e-acute (2), chinese (3), emoji (4), b (1)\n    unicode_chars.append(return_value(c))\nassert unicode_chars == ['a', 'é', '中', '😀', 'b'], f'unicode iteration: {unicode_chars}'\n",
  'ext_call__fstring.py':
      "# call-external\n# External calls in f-strings\n\ns = f'result is {add_ints(10, 20)}'\nassert s == 'result is 30'\n\ns = f'a={add_ints(1, 2)}, b={add_ints(3, 4)}'\nassert s == 'a=3, b=7'\n\n# Nested external call in f-string\ns = f'nested={add_ints(add_ints(1, 2), 3)}'\nassert s == 'nested=6'\n",
  'ext_call__if.py':
      "# call-external\n# === External calls in if/else expressions ===\n\n# Ternary expression with ext call in condition\nresult = 'yes' if add_ints(1, 1) == 2 else 'no'\nassert result == 'yes'\n\nresult2 = 'yes' if add_ints(1, 1) == 3 else 'no'\nassert result2 == 'no'\n\n# Ext call in true branch\nval = add_ints(10, 20) if True else 0\nassert val == 30\n\n# Ext call in false branch\nval2 = 0 if False else add_ints(5, 5)\nassert val2 == 10\n\n# Ext calls in both branches\nval3 = add_ints(1, 2) if True else add_ints(3, 4)\nassert val3 == 3\n\nval4 = add_ints(1, 2) if False else add_ints(3, 4)\nassert val4 == 7\n\n# === If statements with external calls ===\n\n# Ext call in if condition\nx = 0\nif add_ints(1, 1) == 2:\n    x = 100\nassert x == 100\n\ny = 0\nif add_ints(1, 1) == 3:\n    y = 100\nassert y == 0\n\n# Ext call in if body\nz = 0\nif True:\n    z = add_ints(50, 50)\nassert z == 100\n\n# Ext call in else body\nw = 0\nif False:\n    w = 1\nelse:\n    w = add_ints(25, 75)\nassert w == 100\n\n# Nested ext calls in condition\nnested = 0\nif add_ints(add_ints(1, 2), add_ints(3, 4)) == 10:\n    nested = 1\nassert nested == 1\n\n# Chained conditions with ext calls\nresult3 = 0\nif add_ints(1, 1) == 2 and add_ints(2, 2) == 4:\n    result3 = 1\nassert result3 == 1\n\nresult4 = 0\nif add_ints(1, 1) == 3 or add_ints(2, 2) == 4:\n    result4 = 1\nassert result4 == 1\n\n# Comparison with ext call results\ncmp = add_ints(10, 5) > add_ints(5, 5)\nassert cmp == True\n\n# === Nested if statements with external calls ===\n\n# Nested if with ext calls in both conditions (both true)\nresult = 'none'\nif return_value(1) == 1:\n    if return_value(2) == 2:\n        result = 'inner'\n    else:\n        result = 'outer_only'\nelse:\n    result = 'failed'\nassert result == 'inner'\n\n# Nested if - outer true, inner false\nresult2 = 'none'\nif return_value(1) == 1:\n    if return_value(2) == 999:\n        result2 = 'inner'\n    else:\n        result2 = 'outer_only'\nelse:\n    result2 = 'failed'\nassert result2 == 'outer_only'\n\n# Nested if - outer false\nresult3 = 'none'\nif return_value(1) == 999:\n    if return_value(2) == 2:\n        result3 = 'inner'\n    else:\n        result3 = 'outer_only'\nelse:\n    result3 = 'xxx'\nassert result3 == 'xxx'\n\n# Triple nested if - all true\nresult4 = 0\nif return_value(1) == 1:\n    if return_value(2) == 2:\n        if return_value(3) == 3:\n            result4 = 123\nassert result4 == 123\n\n# If condition with multiple ext calls (addition)\nresult5 = 0\nif add_ints(1, 2) + add_ints(3, 4) == 10:\n    result5 = 1\nassert result5 == 1\n\n# For loop inside if with external condition\ntotal = 0\nif return_value(1) == 1:\n    for i in range(3):\n        total = add_ints(total, return_value(i))\nassert total == 3\n\n# For loop inside if - condition false\ntotal2 = 0\nif return_value(1) == 999:\n    for i in range(3):\n        total2 = add_ints(total2, i)\nassert total2 == 0\n",
  'ext_call__if_condition.py':
      "# call-external\n# External calls in if conditions\n\n\ndef check_positive():\n    if add_ints(1, 2) > 0:\n        return 'positive'\n    return 'not positive'\n\n\nresult = check_positive()\nassert result == 'positive'\n\n\ndef check_with_else():\n    if add_ints(-5, 3) > 0:\n        return 'positive'\n    else:\n        return 'negative or zero'\n\n\nresult = check_with_else()\nassert result == 'negative or zero'\n\n\ndef check_elif():\n    val = add_ints(5, 5)\n    if val > 15:\n        return 'big'\n    elif val > 5:\n        return 'medium'\n    else:\n        return 'small'\n\n\nresult = check_elif()\nassert result == 'medium'\n",
  'ext_call__in_closure.py':
      "# call-external\n# External function calls inside closures (nested functions with captured variables).\n\n\ndef outer_with_nested():\n    x = 10\n\n    def inner():\n        return add_ints(x, 5)\n\n    return inner()\n\n\nassert outer_with_nested() == 15\n\n\n# An external call (which suspends the frame) inside a closure capturing a\n# variable *two* levels up — exercises suspend/resume of frames holding a\n# transitively threaded cell.\ndef outer_two_levels():\n    x = 100\n\n    def mid():\n        def inner():\n            return add_ints(x, 7)\n\n        return inner()\n\n    return mid()\n\n\nassert outer_two_levels() == 107\n",
  'ext_call__in_function.py':
      "# call-external\n# === External function calls inside user-defined functions ===\n\n# Basic function calling external function\ndef add_wrapper(a, b):\n    return add_ints(a, b)\n\n\nresult = add_wrapper(10, 20)\nassert result == 30\n\n\n# Function with multiple external calls (sequential)\ndef multi_ext():\n    x = add_ints(1, 2)\n    y = add_ints(3, 4)\n    return add_ints(x, y)\n\n\nassert multi_ext() == 10\n\n\n# External call in function with local variable usage\ndef with_locals():\n    x = 100\n    y = add_ints(x, 50)\n    z = y * 2\n    return z\n\n\nassert with_locals() == 300\n\n\n# Function returning external call result\ndef get_sum(a, b, c):\n    temp = add_ints(a, b)\n    return add_ints(temp, c)\n\n\nassert get_sum(1, 2, 3) == 6\n",
  'ext_call__in_function_simple.py':
      "# call-external\ndef foo():\n    return add_ints(1, 2)\n\n\nresult = foo()\nassert result == 3\n",
  'ext_call__literals.py':
      "# call-external\n# External calls in list and dict literals\n\n# External call in list literal\nlst = [add_ints(1, 2), add_ints(3, 4)]\nassert lst[0] == 3\nassert lst[1] == 7\n\n# External call in tuple literal\ntup = (add_ints(1, 1), add_ints(2, 2))\nassert tup[0] == 2\nassert tup[1] == 4\n\n# External call in dict value\nd = {'a': add_ints(5, 5), 'b': add_ints(10, 10)}\nassert d['a'] == 10\nassert d['b'] == 20\n",
  'ext_call__multi_in_func.py':
      "# call-external\n# Multiple external calls within user-defined functions\n\n\ndef compute_sum():\n    a = add_ints(1, 2)\n    b = add_ints(3, 4)\n    c = add_ints(5, 6)\n    return a + b + c\n\n\nresult = compute_sum()\nassert result == 21\n\n\ndef compute_nested():\n    return add_ints(add_ints(1, 2), add_ints(3, 4))\n\n\nresult = compute_nested()\nassert result == 10\n\n\ndef outer():\n    def inner():\n        return add_ints(10, 20)\n\n    return inner() + add_ints(1, 2)\n\n\nresult = outer()\nassert result == 33\n",
  'ext_call__name_lookup.py':
      "# call-external\n# Tests for NameLookup resolution with various value types.\n# Verifies that the host can inject non-function values (constants)\n# into the sandbox namespace via the NameLookup mechanism.\n\n# === Integer constant ===\nassert CONST_INT == 42, f'CONST_INT should be 42, got {CONST_INT}'\nassert CONST_INT + 8 == 50\nassert type(CONST_INT) == int, f'CONST_INT type should be int, got {type(CONST_INT)}'\n\n# === String constant ===\nassert CONST_STR == 'hello', f'CONST_STR should be hello, got {CONST_STR}'\nassert CONST_STR + ' world' == 'hello world'\nassert len(CONST_STR) == 5, f'CONST_STR length should be 5, got {len(CONST_STR)}'\nassert type(CONST_STR) == str, f'CONST_STR type should be str, got {type(CONST_STR)}'\n\n# === Float constant ===\nassert CONST_FLOAT == 3.14, f'CONST_FLOAT should be 3.14, got {CONST_FLOAT}'\nassert CONST_FLOAT + 0.86 == 4.0\nassert type(CONST_FLOAT) == float, f'CONST_FLOAT type should be float, got {type(CONST_FLOAT)}'\n\n# === Boolean constant ===\nassert CONST_BOOL == True, f'CONST_BOOL should be True, got {CONST_BOOL}'\nassert CONST_BOOL and True, 'CONST_BOOL in boolean expression'\nassert type(CONST_BOOL) == bool, f'CONST_BOOL type should be bool, got {type(CONST_BOOL)}'\n\n# === List constant ===\nassert CONST_LIST == [1, 2, 3], f'CONST_LIST should be [1, 2, 3], got {CONST_LIST}'\nassert len(CONST_LIST) == 3, f'CONST_LIST length should be 3, got {len(CONST_LIST)}'\nassert CONST_LIST[0] == 1\nassert CONST_LIST[-1] == 3\nassert type(CONST_LIST) == list, f'CONST_LIST type should be list, got {type(CONST_LIST)}'\n\n# === None constant ===\nassert CONST_NONE is None, f'CONST_NONE should be None, got {CONST_NONE}'\nassert type(CONST_NONE) == type(None), f'CONST_NONE type should be NoneType, got {type(CONST_NONE)}'\n\n# === Caching: same constant used twice should work ===\nx = CONST_INT\ny = CONST_INT\nassert x == y == 42, 'cached CONST_INT should be consistent'\n\n# === Mixed: constants and external functions in the same code ===\nresult = add_ints(CONST_INT, 8)\nassert result == 50, f'add_ints(CONST_INT, 8) should be 50, got {result}'\n\nstr_result = concat_strings(CONST_STR, ' world')\nassert str_result == 'hello world', f'concat with CONST_STR should be hello world, got {str_result}'\n\n# === Constants used in control flow ===\nif CONST_BOOL:\n    flag = 'yes'\nelse:\n    flag = 'no'\nassert flag == 'yes', f'CONST_BOOL in if should take true branch, got {flag}'\n\n# === Constants used in loops ===\ntotal = 0\nfor item in CONST_LIST:\n    total = total + item\nassert total == 6, f'sum of CONST_LIST should be 6, got {total}'\n\n\n# === Constants in function scope ===\ndef use_constant():\n    return CONST_INT * 2\n\n\nassert use_constant() == 84, f'CONST_INT in function should be 84, got {use_constant()}'\n",
  'ext_call__name_lookup_undefined.py':
      "# call-external\n# When NameLookup returns Undefined for an unknown name, NameError is raised.\ntotally_unknown_name\n# Raise=NameError(\"name 'totally_unknown_name' is not defined\")\n",
  'ext_call__nested_calls.py':
      "# call-external\n# External calls in nested call expressions\n\n# Nested external calls - inner first\nresult = add_ints(add_ints(1, 2), 3)\nassert result == 6\n\n# Triple nested\nresult = add_ints(add_ints(add_ints(1, 1), 2), 3)\nassert result == 7\n\n# Two separate nested calls\nresult = add_ints(add_ints(1, 2), add_ints(3, 4))\nassert result == 10\n",
  'ext_call__recursion_bug.py':
      "# call-external\n# BUG: External calls in recursive functions produce wrong results\n# Recursion with external calls doesn't compute the correct value\n\n\ndef sum_with_ext(n):\n    if n <= 0:\n        return 0\n    return add_ints(n, sum_with_ext(n - 1))\n\n\n# sum_with_ext(3) should compute:\n#   add_ints(3, sum_with_ext(2))\n#   add_ints(3, add_ints(2, sum_with_ext(1)))\n#   add_ints(3, add_ints(2, add_ints(1, sum_with_ext(0))))\n#   add_ints(3, add_ints(2, add_ints(1, 0)))\n#   = 3 + 2 + 1 = 6\nresult = sum_with_ext(3)\nassert result == 6\n",
  'ext_call__return.py':
      "# call-external\n# External calls in return statements\n\n\ndef direct_return():\n    return add_ints(10, 20)\n\n\nresult = direct_return()\nassert result == 30\n\n\ndef return_with_expression():\n    return add_ints(1, 2) + add_ints(3, 4)\n\n\nresult = return_with_expression()\nassert result == 10\n\n\ndef conditional_return():\n    if return_value(True):\n        return add_ints(100, 200)\n    return add_ints(1, 1)\n\n\nresult = conditional_return()\nassert result == 300\n",
  'ext_call__side_effects.py':
      "# call-external\ndef log(msg):\n    print(msg)\n    return 1\n\n\ndef inner(x):\n    print('Inner called')\n    val = add_ints(x, 1)  # External call\n    print('Inner resumed')\n    return val\n\n\ndef outer():\n    print('Outer calling inner')\n    # If side effects are duplicated, we'll see \"Evaluating arg\" twice\n    res = inner(log('Evaluating arg'))\n    print('Outer returned')\n    return res\n\n\nprint('Starting')\nres = outer()\nprint(f'Result: {res}')\nassert res == 2\n",
  'ext_call__subscript.py':
      "# call-external\n# External calls in subscript operations\n\n# External call as subscript index\nitems = [10, 20, 30]\nresult = items[add_ints(0, 1)]\nassert result == 20\n",
  'ext_call__ternary.py':
      "# call-external\n# External calls in ternary expressions (if/else expressions)\n\n# External call in true branch\nresult = add_ints(1, 2) if True else add_ints(10, 20)\nassert result == 3\n\n# External call in false branch\nresult = add_ints(1, 2) if False else add_ints(10, 20)\nassert result == 30\n\n# External call in condition\nresult = 'yes' if return_value(True) else 'no'\nassert result == 'yes'\n\nresult = 'yes' if return_value(False) else 'no'\nassert result == 'no'\n\n# External calls in both branches\nresult = add_ints(1, 2) if return_value(True) else add_ints(10, 20)\nassert result == 3\n\nresult = add_ints(1, 2) if return_value(False) else add_ints(10, 20)\nassert result == 30\n\n# Nested ternary with external calls\nresult = add_ints(1, 1) if return_value(True) else (add_ints(2, 2) if return_value(False) else add_ints(3, 3))\nassert result == 2\n",
  'ext_call__try.py':
      "# call-external\n# === External calls in try blocks ===\n\n# Basic external call in try body\nresult = None\ntry:\n    result = add_ints(10, 20)\nexcept:\n    result = -1\nassert result == 30\n\n# Multiple external calls in try body\ntry:\n    a = add_ints(1, 2)\n    b = add_ints(3, 4)\n    c = add_ints(a, b)\nexcept:\n    c = -1\nassert c == 10\n\n# Nested external calls in try body\ntry:\n    nested = add_ints(add_ints(1, 2), add_ints(3, 4))\nexcept:\n    nested = -1\nassert nested == 10\n\n# === External calls in except blocks ===\n\n# External call in except handler\nhandler_result = None\ntry:\n    raise ValueError('error')\nexcept ValueError:\n    handler_result = add_ints(100, 200)\nassert handler_result == 300\n\n# Multiple external calls in except handler\ntry:\n    raise TypeError('error')\nexcept TypeError:\n    x = add_ints(5, 5)\n    y = add_ints(10, 10)\n    handler_sum = add_ints(x, y)\nassert handler_sum == 30\n\n# External call with exception variable\nexc_with_ext = None\ntry:\n    raise ValueError('test')\nexcept ValueError as e:\n    prefix = concat_strings('caught: ', repr(e))\n    exc_with_ext = prefix\nassert exc_with_ext == \"caught: ValueError('test')\"\n\n# === External calls in else blocks ===\n\n# External call in else block\nelse_result = None\ntry:\n    x = 1  # No exception\nexcept:\n    else_result = -1\nelse:\n    else_result = add_ints(50, 50)\nassert else_result == 100\n\n# Multiple external calls in else block\ntry:\n    pass\nexcept:\n    else_multi = -1\nelse:\n    p = add_ints(1, 2)\n    q = add_ints(3, 4)\n    else_multi = add_ints(p, q)\nassert else_multi == 10\n\n# === External calls in finally blocks ===\n\n# External call in finally block\nfinally_result = None\ntry:\n    x = 1\nfinally:\n    finally_result = add_ints(25, 75)\nassert finally_result == 100\n\n# Finally with external call after exception caught\nfinally_after_exc = None\ntry:\n    raise ValueError('error')\nexcept ValueError:\n    pass\nfinally:\n    finally_after_exc = add_ints(1, 99)\nassert finally_after_exc == 100\n\n# Multiple external calls in finally\ntry:\n    pass\nfinally:\n    f1 = add_ints(10, 20)\n    f2 = add_ints(30, 40)\n    finally_multi = add_ints(f1, f2)\nassert finally_multi == 100\n\n# === External calls across multiple phases ===\n\n# External calls in try, except, and finally\nall_phases = []\ntry:\n    all_phases.append(add_ints(1, 0))  # 1\n    raise ValueError('error')\nexcept ValueError:\n    all_phases.append(add_ints(2, 0))  # 2\nfinally:\n    all_phases.append(add_ints(3, 0))  # 3\nassert all_phases == [1, 2, 3]\n\n# External calls in try, else, and finally (no exception)\nno_exc_phases = []\ntry:\n    no_exc_phases.append(add_ints(10, 0))  # 10\nexcept:\n    no_exc_phases.append(-1)\nelse:\n    no_exc_phases.append(add_ints(20, 0))  # 20\nfinally:\n    no_exc_phases.append(add_ints(30, 0))  # 30\nassert no_exc_phases == [10, 20, 30]\n\n# === External calls in nested try blocks ===\n\n# Nested try with external calls at each level\nouter_val = None\ninner_val = None\ntry:\n    outer_val = add_ints(100, 0)\n    try:\n        inner_val = add_ints(200, 0)\n        raise ValueError('inner')\n    except ValueError:\n        inner_val = add_ints(inner_val, 50)\nexcept:\n    outer_val = -1\nassert outer_val == 100\nassert inner_val == 250\n\n# === External calls in exception type expression ===\n# (Exception type is evaluated at handler matching time)\n\n# External call producing value used after try\npost_try = None\ntry:\n    pre = add_ints(5, 5)\nexcept:\n    pre = -1\npost_try = add_ints(pre, 10)\nassert post_try == 20\n\n# === External call in finally with unhandled exception ===\n# Finally should still run even when exception propagates\nfinally_with_propagate = None\ntry:\n    try:\n        finally_with_propagate = add_ints(0, 0)  # Initialize\n        raise KeyError('unhandled')\n    except ValueError:\n        pass  # Won't catch KeyError\n    finally:\n        finally_with_propagate = add_ints(42, 0)  # Should still run\nexcept KeyError:\n    pass  # Catch propagated exception\nassert finally_with_propagate == 42\n\n# === External call in except handler that then raises ===\nhandler_before_raise = None\ntry:\n    try:\n        raise ValueError('original')\n    except ValueError:\n        handler_before_raise = add_ints(10, 0)  # External call before raising\n        raise TypeError('from handler')\nexcept TypeError:\n    pass\nassert handler_before_raise == 10\n\n# === External call in else block that then raises ===\nelse_before_raise = None\ntry:\n    try:\n        pass  # No exception\n    except:\n        pass\n    else:\n        else_before_raise = add_ints(20, 0)  # External call before raising\n        raise ValueError('from else')\nexcept ValueError:\n    pass\nassert else_before_raise == 20\n\n# === External call preserves state across try/except ===\nstate_before = add_ints(1000, 0)\nstate_after = None\ntry:\n    state_after = add_ints(state_before, 1)\n    raise ValueError('test')\nexcept ValueError:\n    state_after = add_ints(state_after, 10)\nfinally:\n    state_after = add_ints(state_after, 100)\nassert state_after == 1111\n\n# === Multiple except handlers with external calls ===\nwhich_handler = None\ntry:\n    raise TypeError('test')\nexcept ValueError:\n    which_handler = add_ints(1, 0)\nexcept TypeError:\n    which_handler = add_ints(2, 0)\nexcept KeyError:\n    which_handler = add_ints(3, 0)\nassert which_handler == 2\n\n# === External call in finally with pending exception (after handler raises) ===\nfinally_after_handler_raise = None\ntry:\n    try:\n        raise ValueError('original')\n    except ValueError:\n        finally_after_handler_raise = add_ints(10, 0)  # External call before raising\n        raise TypeError('from handler')\n    finally:\n        # This external call should work even though there's a pending exception\n        finally_after_handler_raise = add_ints(finally_after_handler_raise, 5)\nexcept TypeError:\n    pass\nassert finally_after_handler_raise == 15\n\n# === External call in finally with pending exception (no matching handler) ===\nfinally_with_pending_exc = None\ntry:\n    try:\n        finally_with_pending_exc = add_ints(0, 0)\n        raise KeyError('no handler')\n    except ValueError:\n        pass  # Won't catch KeyError\n    finally:\n        # This external call should work even though KeyError is pending\n        finally_with_pending_exc = add_ints(100, 0)\nexcept KeyError:\n    pass  # Catch it here\nassert finally_with_pending_exc == 100\n\n# === External call in finally with return (uses simple values) ===\n# Note: External calls in user-defined functions are not supported,\n# so we test pending return with built-in operations only\nfinally_return_result = None\ntry:\n    finally_return_result = 'in_try'\nfinally:\n    pass  # finally runs but doesn't override\nassert finally_return_result == 'in_try'\n\n# === Multiple external calls in finally with pending exception ===\nmulti_finally = None\ntry:\n    try:\n        raise ValueError('test')\n    except TypeError:\n        pass  # Won't match\n    finally:\n        a = add_ints(1, 2)\n        b = add_ints(3, 4)\n        multi_finally = add_ints(a, b)\nexcept ValueError:\n    pass\nassert multi_finally == 10\n",
  'ext_call__try_simple.py':
      "# call-external\n# Test external call with exception variable\n\nexc_with_ext = None\ntry:\n    raise ValueError('test')\nexcept ValueError as e:\n    prefix = concat_strings('caught: ', repr(e))\n    exc_with_ext = prefix\nassert exc_with_ext == \"caught: ValueError('test')\"\n",
  'ext_call__unary.py':
      "# call-external\n# External calls in unary expressions\n\n# Negation of external call result\nresult = -add_ints(3, 4)\nassert result == -7\n\n# Not of external call\nresult = not return_value(False)\nassert result == True\n\nresult = not return_value(True)\nassert result == False\n",
  'float__mod.py':
      "# === float modulo: result takes the divisor's sign ===\nassert 7.5 % 2 == 1.5\nassert -7.0 % 3.0 == 2.0\nassert 7.0 % -3.0 == -2.0\nassert -7.0 % -3.0 == -1.0\nassert -7 % 3.0 == 2.0\nassert -7.0 % 3 == 2.0\nassert str(-6.0 % 3.0) == '0.0'\nassert str(6.0 % -3.0) == '-0.0'\n\n# === infinite divisor ===\nassert 5.0 % float('inf') == 5.0\nassert -5.0 % float('inf') == float('inf')\nassert 5.0 % -float('inf') == -float('inf')\n\n# === `%` agrees with divmod's remainder ===\nassert divmod(-7.0, 3.0)[1] == -7.0 % 3.0\nassert divmod(7.0, -3.0)[1] == 7.0 % -3.0\n\n# === `%` inside a comparison ===\nassert (-7.0 % 3.0 == 2) is True\nassert (7.0 % -3.0 == -2) is True\nassert (5.0 % 3.0 == 2) is True\n\n# === unsupported operands ===\ntry:\n    [1] % 2\n    assert False, 'expected TypeError from %'\nexcept TypeError as e:\n    assert str(e) == \"unsupported operand type(s) for %: 'list' and 'int'\"\n\n# === zero divisor raises for every numeric combination ===\nfor a, b in [(5.0, 0.0), (5.0, 0), (5, 0.0), (5, 0)]:\n    try:\n        a % b\n        assert False, 'expected ZeroDivisionError from %'\n    except ZeroDivisionError as e:\n        assert str(e) == 'division by zero'\n",
  'frozenset__ops.py':
      "# === Construction ===\nfs = frozenset()\nassert len(fs) == 0\nassert fs == frozenset()\n\nfs = frozenset([1, 2, 3])\nassert len(fs) == 3\n\n# === Copy ===\nfs = frozenset([1, 2, 3])\nfs2 = fs.copy()\nassert fs == fs2\n\n# === Union ===\nfs1 = frozenset([1, 2])\nfs2 = frozenset([2, 3])\nu = fs1.union(fs2)\nassert len(u) == 3\n\n# === Intersection ===\nfs1 = frozenset([1, 2, 3])\nfs2 = frozenset([2, 3, 4])\ni = fs1.intersection(fs2)\nassert len(i) == 2\n\n# === Difference ===\nfs1 = frozenset([1, 2, 3])\nfs2 = frozenset([2, 3, 4])\nd = fs1.difference(fs2)\nassert len(d) == 1\n\n# === Symmetric Difference ===\nfs1 = frozenset([1, 2, 3])\nfs2 = frozenset([2, 3, 4])\nsd = fs1.symmetric_difference(fs2)\nassert len(sd) == 2\n\n# === Binary operators ===\nfs = frozenset([1, 2])\nother_fs = frozenset([2, 3])\ns = {2, 3}\n\nassert fs & other_fs == frozenset([2])\nassert fs | other_fs == frozenset([1, 2, 3])\nassert fs ^ other_fs == frozenset([1, 3])\nassert fs - other_fs == frozenset([1])\n\nassert fs & s == frozenset([2])\nassert fs | s == frozenset([1, 2, 3])\nassert fs ^ s == frozenset([1, 3])\nassert fs - s == frozenset([1])\n\nkeys = {'a': 1, 'b': 2}.keys()\nitems = {'a': 1, 'b': 2}.items()\nassert frozenset({'a'}) & keys == frozenset({'a'})\nassert frozenset({'a'}) | keys == frozenset({'a', 'b'})\nassert frozenset({('a', 1)}) ^ items == frozenset({('b', 2)})\nassert frozenset({('a', 1), ('b', 2)}) - items == frozenset()\n\nassert type(fs | s).__name__ == 'frozenset'\n\ntry:\n    fs & [1, 2]\n    assert False, 'frozenset operators reject non-set rhs'\nexcept TypeError as e:\n    assert str(e) == \"unsupported operand type(s) for &: 'frozenset' and 'list'\"\n\n# === Issubset ===\nfs1 = frozenset([1, 2])\nfs2 = frozenset([1, 2, 3])\nassert fs1.issubset(fs2) is True\nassert fs2.issubset(fs1) is False\n\n# === Issuperset ===\nfs1 = frozenset([1, 2, 3])\nfs2 = frozenset([1, 2])\nassert fs1.issuperset(fs2) is True\nassert fs2.issuperset(fs1) is False\n\n# === Isdisjoint ===\nfs1 = frozenset([1, 2])\nfs2 = frozenset([3, 4])\nfs3 = frozenset([2, 3])\nassert fs1.isdisjoint(fs2) is True\nassert fs1.isdisjoint(fs3) is False\n\n# === Bool ===\nassert bool(frozenset()) == False\nassert bool(frozenset([1])) == True\n\n# === repr ===\nassert repr(frozenset()) == 'frozenset()'\n\n# === Hashing ===\nfs = frozenset([1, 2, 3])\nh = hash(fs)\nassert isinstance(h, int)\n\n# Same elements should have same hash\nfs1 = frozenset([1, 2, 3])\nfs2 = frozenset([3, 2, 1])  # Different order\nassert hash(fs1) == hash(fs2)\n\n# === As dict key ===\nd = {}\nfs = frozenset([1, 2])\nd[fs] = 'value'\nassert d[fs] == 'value'\nassert d[frozenset([2, 1])] == 'value'\n\n# === Construction from various iterables ===\nfs = frozenset('abc')\nassert len(fs) == 3\nassert 'a' in fs and 'b' in fs and 'c' in fs, 'frozenset from string elements'\n\nfs = frozenset((1, 2, 3))\nassert fs == frozenset({1, 2, 3})\n\nfs = frozenset(range(5))\nassert fs == frozenset({0, 1, 2, 3, 4})\n\nfs = frozenset({1, 2, 3})\nassert len(fs) == 3\n\n# === Containment (in / not in) ===\nfs = frozenset({1, 2, 3})\nassert 1 in fs\nassert 4 not in fs\nassert 'x' not in frozenset({'a', 'b'})\n\n# === Iteration ===\nresult = []\nfor x in frozenset({1, 2, 3}):\n    result.append(x)\nassert len(result) == 3\nassert set(result) == {1, 2, 3}\n\nresult = []\nfor x in frozenset():\n    result.append(x)\nassert result == []\n\n# === Inequality (!=) ===\nassert frozenset({1, 2}) != frozenset({1, 3})\nassert not (frozenset({1, 2}) != frozenset({1, 2})), 'frozenset ne same'\n\n# === Methods accepting iterables ===\nassert frozenset({1, 2}).union([3, 4]) == frozenset({1, 2, 3, 4})\nassert frozenset({1, 2, 3}).intersection([2, 3, 4]) == frozenset({2, 3})\nassert frozenset({1, 2, 3}).difference([2]) == frozenset({1, 3})\nassert frozenset({1, 2}).symmetric_difference([2, 3]) == frozenset({1, 3})\nassert frozenset({1}).union(range(3)) == frozenset({0, 1, 2})\nassert frozenset({1}).union((2, 3)) == frozenset({1, 2, 3})\n\n# === issubset/issuperset/isdisjoint with non-set iterables ===\nfs = frozenset({1, 2, 3})\nassert fs.issubset(range(10))\nassert fs.issuperset([1, 2])\nassert fs.isdisjoint([4, 5, 6])\nassert not fs.isdisjoint([3, 4]), 'not isdisjoint with list'\n\n# === Different hashes for different frozensets ===\nfs1 = frozenset({1, 2})\nfs2 = frozenset({3, 4})\n# Not guaranteed to be different, but very likely\n# Instead just verify they're integers and stable\nassert hash(fs1) == hash(frozenset({2, 1}))\nassert hash(frozenset()) == hash(frozenset())\n\n# === Frozenset as set element ===\ns = {frozenset({1, 2}), frozenset({3, 4})}\nassert len(s) == 2\nassert frozenset({1, 2}) in s\n# Duplicate frozenset should dedup\ns2 = {frozenset({1}), frozenset({1})}\nassert len(s2) == 1\n\n# === set <-> frozenset cross-type equality (compare by members) ===\nassert frozenset({1, 2, 3}) == {1, 2, 3}\nassert {1, 2, 3} == frozenset({1, 2, 3})\nassert frozenset({1, 2}) != {1, 2, 3}\nassert {1, 2, 3} != frozenset({1, 2})\nassert frozenset() == set()\nassert set() == frozenset()\nassert {1: 'a', 2: 'b'}.keys() == frozenset({1, 2})\n",
  'fstring__all.py':
      "# === Basic f-strings ===\nassert f'hello' == 'hello'\nassert f'' == ''\n\n# === Simple interpolation ===\nx = 'world'\nassert f'hello {x}' == 'hello world'\n\n# multiple interpolations\na = 1\nb = 2\nassert f'{a} + {b} = {a + b}' == '1 + 2 = 3'\n\n# expression in f-string\nassert f'{1 + 2 + 3}' == '6'\n\n# === Value types ===\n# list value\nx = [1, 2, 3]\nassert f'list: {x}' == 'list: [1, 2, 3]'\n\n# bool value\nx = True\nassert f'value: {x}' == 'value: True'\n\n# int value\nassert f'{42}' == '42'\n\n# float value\nassert f'{3.14}' == '3.14'\n\n# None value\nassert f'{None}' == 'None'\n\n# === Conversion flags (!s, !r, !a) ===\n# conversion !s (str)\nassert f'{42!s}' == '42'\n\n# conversion !r (repr)\nassert f'{\"hello\"!r}' == \"'hello'\"\n\n# conversion !r on int (should be same as str for int)\nassert f'{42!r}' == '42'\n\n# conversion !r on list\nassert f'{[1, 2]!r}' == '[1, 2]'\n\n# conversion !s on string (no quotes)\nassert f'{\"hello\"!s}' == 'hello'\n\n# conversion !a (ascii) - escapes non-ASCII characters\nassert f'{\"café\"!a}' == \"'caf\\\\xe9'\"\nassert f'{\"hello\"!a}' == \"'hello'\"\nassert f'{\"日本\"!a}' == \"'\\\\u65e5\\\\u672c'\"\n\n# === String padding and alignment ===\n# format spec: width (left-aligned by default for strings)\nassert f'{\"hi\":10}' == 'hi        '\n\n# format spec: left align\nassert f'{\"hi\":<10}' == 'hi        '\n\n# format spec: right align\nassert f'{\"hi\":>10}' == '        hi'\n\n# format spec: center align\nassert f'{\"hi\":^10}' == '    hi    '\n\n# center align with odd padding\nassert f'{\"zip\":^6}' == ' zip  '\n\n# format spec: fill character\nassert f'{\"hi\":*>10}' == '********hi'\nassert f'{\"hi\":_<10}' == 'hi________'\nassert f'{\"hi\":*^10}' == '****hi****'\n\n# string truncation with precision\nassert f'{\"xylophone\":.5}' == 'xylop'\nassert f'{\"xylophone\":10.5}' == 'xylop     '\n\n# === Integer formatting ===\n# basic integer\nassert f'{42}' == '42'\n\n# integer with :d type\nassert f'{42:d}' == '42'\n\n# integer padding\nassert f'{42:4d}' == '  42'\nassert f'{42:04d}' == '0042'\n\n# integer with sign\nassert f'{42:+d}' == '+42'\nassert f'{42: d}' == ' 42'\nassert f'{-42:+d}' == '-42'\nassert f'{-42: d}' == '-42'\n\n# sign-aware padding\nassert f'{-23:=5d}' == '-  23'\n\n# i64::MIN: formatting must not overflow when taking abs of the minimum int\nassert f'{-9223372036854775808:d}' == '-9223372036854775808'\nassert f'{-9223372036854775808:+d}' == '-9223372036854775808'\nassert f'{-9223372036854775808:=22d}' == '-  9223372036854775808'\n\n# integer fill character with alignment\nassert f'{42:*>10d}' == '********42'\nassert f'{42:*<10d}' == '42********'\nassert f'{42:*^10d}' == '****42****'\n\n# === Integer non-decimal bases ===\n# binary\nassert f'{10:b}' == '1010'\nassert f'{-10:b}' == '-1010'\nassert f'{0:b}' == '0'\n\n# octal\nassert f'{8:o}' == '10'\nassert f'{-8:o}' == '-10'\n\n# hexadecimal (lower and upper)\nassert f'{255:x}' == 'ff'\nassert f'{-255:x}' == '-ff'\nassert f'{255:X}' == 'FF'\n\n# Uppercase `X` uppercases only the hex digits and the `0x` prefix (`0X`), NOT an\n# alphabetic fill char — the fill must stay as written.\nassert f'{180:a>8X}' == 'aaaaaaB4'\nassert f'{0xABC:f>8X}' == 'fffffABC'\nassert f'{255:#X}' == '0XFF'\nassert f'{255:b>#8X}' == 'bbbb0XFF'\n# Same rules for big integers (LongInt path).\nassert f'{2**70:a>25X}' == 'aaaaaaa400000000000000000'\nassert f'{2**68 + 0xAB:#X}' == '0X1000000000000000AB'\nassert f'{2**68 + 0xAB:#x}' == '0x1000000000000000ab'\n\n# === Sign-aware (`=`) padding applies to every numeric format, not just :d/:f ===\n# Previously pad_string's SignAware arm fell through, so width was silently\n# dropped for hex/oct/bin/exponential/general/percent.\nassert f'{255:=10x}' == '        ff'\nassert f'{-255:=10x}' == '-       ff'\nassert f'{8:=8b}' == '    1000'\nassert f'{8:=8o}' == '      10'\nassert f'{3.14:=10g}' == '      3.14'\nassert f'{-3.14:=10g}' == '-     3.14'\nassert f'{0.5:=12.2%}' == '      50.00%'\n# format_char has no sign; CPython accepts `=` here and degrades to right-align.\nassert f'{65:=10c}' == '         A'\n\n# === Sign prefix (`+`, ` `) applies to non-decimal integer bases too ===\n# format_int_base previously ignored spec.sign and only emitted '-' for negatives.\nassert f'{255:+x}' == '+ff'\nassert f'{255: x}' == ' ff'\nassert f'{8:+b}' == '+1000'\nassert f'{-255:X}' == '-FF'\n\n# === Integer as Unicode character (:c) ===\nassert f'{65:c}' == 'A'\nassert f'{0x4E2D:c}' == '中'\n\n# === Bool with format spec ===\n# bool is a subclass of int, so :d works\nassert f'{True:d}' == '1'\nassert f'{False:d}' == '0'\nassert f'{True:04d}' == '0001'\n\n# === Float formatting ===\n# basic float\nassert f'{3.14159}' == '3.14159'\n\n# float with :f type\nassert f'{3.141592653589793:f}' == '3.141593'\n\n# float precision\nassert f'{3.141592653589793:.2f}' == '3.14'\nassert f'{3.141592653589793:.4f}' == '3.1416'\n\n# float width and precision\nassert f'{3.141592653589793:06.2f}' == '003.14'\nassert f'{3.141592653589793:10.2f}' == '      3.14'\n\n# float with sign\nassert f'{3.14:+.2f}' == '+3.14'\nassert f'{-3.14:+.2f}' == '-3.14'\nassert f'{3.14:-.2f}' == '3.14'\nassert f'{-3.14:-.2f}' == '-3.14'\n\n# exponential notation\nassert f'{1234.5678:e}' == '1.234568e+03'\nassert f'{1234.5678:E}' == '1.234568E+03'\nassert f'{1234.5678:.2e}' == '1.23e+03'\nassert f'{0.00012345:.2e}' == '1.23e-04'\n\n# general format (g/G) - uses exponential for very large/small numbers\nassert f'{1.5:g}' == '1.5'\nassert f'{1.500:g}' == '1.5'\nassert f'{1234567890:g}' == '1.23457e+09'\n\n# percentage\nassert f'{0.25:%}' == '25.000000%'\nassert f'{0.25:.1%}' == '25.0%'\nassert f'{0.125:.0%}' == '12%'\n\n# zero precision rounds (banker's/half-even style per Python)\nassert f'{3.7:.0f}' == '4'\nassert f'{3.4:.0f}' == '3'\nassert f'{1234.5:.0e}' == '1e+03'\n\n# uppercase exponential\nassert f'{1234.5:E}' == '1.234500E+03'\n\n# float fill character with alignment + precision\nassert f'{3.14:*>10.2f}' == '******3.14'\nassert f'{3.14:*<10.2f}' == '3.14******'\nassert f'{3.14:*^10.2f}' == '***3.14***'\n\n# large and small magnitude exponents\nassert f'{1e100:.3e}' == '1.000e+100'\nassert f'{1e-100:.3e}' == '1.000e-100'\n\n# high precision reveals f64 representation\nassert f'{0.1:.20f}' == '0.10000000000000000555'\n\n# === Large dynamic precision ===\n# Precision > u16::MAX (65535) must not overflow Rust's `format!` precision\n# argument. Each of these exercises a different internal format code path.\nassert f'{1:.{10**6}f}' == '1.' + '0' * 10**6\nassert f'{1:.{10**6}e}' == '1.' + '0' * 10**6 + 'e+00'\nassert f'{1:.{10**6}E}' == '1.' + '0' * 10**6 + 'E+00'\nassert f'{0.5:.{10**6}%}' == '50.' + '0' * 10**6 + '%'\n# :g strips trailing zeros, so the visible result is short, but the\n# underlying format call still uses the full precision internally.\nassert f'{1.5:.{10**6}g}' == '1.5'\nassert f'{1e-10:.{10**6}g}' == '1.0000000000000000364321973154977415791655470655996396089904010295867919921875e-10'\n\n# === Large static width/precision ===\n# Static format specs are parsed at parse time and packed into a compact\n# bytecode constant; values around the previous u16 boundary must still\n# round-trip correctly.\nassert len(f'{1.5:.65535f}') == 65537\nassert len(f'{1.5:.65536f}') == 65538\nassert len(f'{42:65536d}') == 65536\n\n# Specs whose width or precision exceed the compact bytecode encoding\n# (MAX_ENCODED_WIDTH = 2**20 - 1, MAX_ENCODED_PRECISION = 2**21 - 2)\n# must still compile — the parser falls back to a dynamic spec so the\n# VM re-parses at runtime.\nassert len(f'{42:1048576d}') == 1048576\nassert len(f'{1.5:.2097151f}') == 2097153\n\n# Fill characters above Latin-1 (codepoint > 0xFF) don't fit the 8-bit\n# fill slot of the compact encoding either — they must also round-trip\n# through the dynamic-spec fallback rather than corrupting the encoded form.\nassert f'{\"hi\":日^10}' == '日日日日hi日日日日'\nassert f'{42:🐍>5d}' == '🐍🐍🐍42'\n\n# === Integer with float format types ===\n# Python allows formatting integers with float types\nassert f'{42:f}' == '42.000000'\nassert f'{42:.2f}' == '42.00'\nassert f'{42:.2e}' == '4.20e+01'\nassert f'{1234:g}' == '1234'\nassert f'{5:%}' == '500.000000%'\n\n# === Negative zero preserves sign ===\nassert f'{-0.0}' == '-0.0'\nassert f'{-0.0:f}' == '-0.000000'\nassert f'{-0.0:+.2f}' == '-0.00'\n\n# === The `z` flag coerces negative zero to positive zero ===\n# Coercion happens AFTER rounding to the target precision: a negative value that\n# rounds to zero becomes +0, but one that rounds to a nonzero value keeps its sign.\nassert f'{-0.0:z}' == '0.0'\nassert f'{-0.0:z.2f}' == '0.00'\nassert f'{-0.001:z.1f}' == '0.0'\nassert f'{-0.001:z.3f}' == '-0.001'\nassert f'{-0.04:z.1f}' == '0.0'\nassert f'{-0.05:z.1f}' == '-0.1'\nassert f'{-0.49:z.0f}' == '0'\nassert f'{-0.5:z.0f}' == '0'\nassert f'{-0.0:ze}' == '0.000000e+00'\nassert f'{-0.0:zg}' == '0'\nassert f'{-0.0:z%}' == '0.000000%'\nassert f'{0.0:z.2f}' == '0.00'\nassert f'{3.14:z.1f}' == '3.1'\nassert f'{-3.14:z.1f}' == '-3.1'\nassert f'{-0.0:+z.1f}' == '+0.0'\nassert f'{-0.0:z010.1f}' == '00000000.0'\nassert f'{0:zf}' == '0.000000'\nassert f'{True:zf}' == '1.000000'\n# `z` in fill position (followed by an align char) is a fill char, not the flag.\nassert f'{-0.0:z>8.1f}' == 'zzzz-0.0'\n\n\n# `z` is only valid for floating-point presentations.\ndef _z_err(fn):\n    try:\n        fn()\n        assert False, 'expected ValueError'\n    except ValueError as exc:\n        return str(exc)\n\n\nassert _z_err(lambda: f'{-5:z}') == 'Negative zero coercion (z) not allowed in integer format specifier'\nassert _z_err(lambda: f'{-5:zx}') == 'Negative zero coercion (z) not allowed in integer format specifier'\nassert _z_err(lambda: f'{True:z}') == 'Negative zero coercion (z) not allowed in integer format specifier'\nassert _z_err(lambda: f'{\"x\":z}') == 'Negative zero coercion (z) not allowed in string format specifier'\nassert _z_err(lambda: f'{5:z#}') == 'Negative zero coercion (z) not allowed in integer format specifier'\nassert _z_err(lambda: f'{\"x\":z#}') == 'Negative zero coercion (z) not allowed in string format specifier'\n# Precedence: a bad type code or grouping error still wins over the z error.\nassert _z_err(lambda: f'{5:z.2}') == 'Precision not allowed in integer format specifier'\n\n# === Infinity formatting across format codes ===\n# inf bypasses precision/width-pad zero rules and renders as 'inf'\nassert f'{float(\"inf\"):f}' == 'inf'\nassert f'{float(\"inf\"):e}' == 'inf'\nassert f'{float(\"inf\"):.3f}' == 'inf'\nassert f'{float(\"inf\"):+f}' == '+inf'\nassert f'{float(\"-inf\"):f}' == '-inf'\n\n# === Nested format specs ===\nwidth = 10\nassert f'{\"hi\":{width}}' == 'hi        '\n\n# nested alignment and width\nalign = '^'\nassert f'{\"test\":{align}{width}}' == '   test   '\n\nwidth, prec = 10, 3\nassert f'{3.14159:{width}.{prec}f}' == '     3.142'\n\n# nested precision\nprec = 3\nassert f'{\"xylophone\":.{prec}}' == 'xyl'\n\n\n# === f-string in function ===\ndef greet(name):\n    return f'Hello, {name}!'\n\n\nassert greet('World') == 'Hello, World!'\n\n\n# function returning formatted value\ndef format_num(n, w):\n    return f'{n:>{w}}'\n\n\nassert format_num('x', 5) == '    x'\n\n# === Escaping ===\n# double braces to escape\nassert f'{{}}' == '{}'\nassert f'{{x}}' == '{x}'\nassert f'{{{42}}}' == '{42}'\n\n# === Complex expressions ===\n# TODO: method call on literal - parser doesn't support this yet\n# assert f'{\"hello\".upper()}' == 'HELLO', 'method call on literal'\n\n# TODO: method call on variable - str.upper() not implemented yet\n# s = 'hello'\n# assert f'{s.upper()}' == 'HELLO', 'method call on variable'\n\n# subscript in f-string\nlst = [10, 20, 30]\nassert f'{lst[1]}' == '20'\n\n# dict lookup\nd = {'a': 1, 'b': 2}\nassert f'{d[\"a\"]}' == '1'\n\n# TODO: conditional expression - parser doesn't support IfExp yet\n# x = 5\n# assert f'{x if x > 0 else -x}' == '5', 'conditional positive'\n# x = -5\n# assert f'{-x if x < 0 else x}' == '5', 'conditional negative'\n\n# === String concatenation ===\nname = 'world'\n# regular string + f-string (implicit concatenation)\nassert f'hello {name}' == 'hello world'\n\n# === Empty interpolation expression ===\n# (this should be a syntax error, but test current behavior)\n# assert f'{}' would be syntax error\n\n# === Whitespace in format spec ===\n# no extra whitespace handling needed, width handles it\nassert f'{\"x\":5}' == 'x    '\n\n# === Empty format spec with various types ===\n# trailing `:` with no spec behaves like no spec\nassert f'{42:}' == '42'\nassert f'{3.14:}' == '3.14'\nassert f'{\"hi\":}' == 'hi'\n\n# === Unicode character counting in padding ===\nx = 'café'\nassert f'{x:_<10}' == 'café______'\nassert f'{x:_>10}' == '______café'\nassert f'{x:_^10}' == '___café___'\nassert f'{x:_^11}' == '___café____'\nassert f'{x:é<10}' == 'cafééééééé'\nassert f'{x:é>10}' == 'éééééécafé'\nassert f'{x:é^10}' == 'ééécaféééé'\nassert f'{x:é^11}' == 'ééécafééééé'\n\n# === Conversion flag with type spec ===\n# conversion flag produces string, so 's' format should work\nassert f'{42!r:s}' == '42'\n\n# === Conversion flag + spec: the spec is validated as a *string* spec ===\n# `!s`/`!r`/`!a` convert to a string first, so flags that are illegal for text\n# must be rejected exactly as they are for a real string value — and the value\n# and its converted form must raise the *same* error. Valid string flags work:\nassert f'{123!s:05}' == '12300'\nassert f'{123!r:>6}' == '   123'\nassert f'{3.14159!r:.4}' == '3.14'\n\n\n# Illegal-for-text flags raise the same ValueError as on a bare string.\ndef _conv_err(fn):\n    try:\n        fn()\n        assert False, 'expected ValueError'\n    except ValueError as exc:\n        return str(exc)\n\n\nassert _conv_err(lambda: f'{123!s:#}') == 'Alternate form (#) not allowed in string format specifier'\nassert _conv_err(lambda: f'{123!r:,}') == \"Cannot specify ',' with 's'.\"\nassert _conv_err(lambda: f'{123!r:_}') == \"Cannot specify '_' with 's'.\"\nassert _conv_err(lambda: f'{123!s:+}') == 'Sign not allowed in string format specifier'\nassert _conv_err(lambda: f'{123!s: }') == 'Space not allowed in string format specifier'\nassert _conv_err(lambda: f'{123!s:=}') == \"'=' alignment not allowed in string format specifier\"\nassert _conv_err(lambda: f'{123!r:#x}') == \"Unknown format code 'x' for object of type 'str'\"\nassert _conv_err(lambda: f'{123!s:.2f}') == \"Unknown format code 'f' for object of type 'str'\"\n\n# Precedence among multiple violations matches CPython (grouping > type > sign >\n# alternate > `=`), and a value formats identically with or without `!s`/`!r`.\nassert (\n    _conv_err(lambda: f'{\"x\":=#}')\n    == _conv_err(lambda: f'{1!r:=#}')\n    == 'Alternate form (#) not allowed in string format specifier'\n), 'alternate beats = align'\nassert (\n    _conv_err(lambda: f'{\"x\":+#}') == _conv_err(lambda: f'{1!s:+#}') == 'Sign not allowed in string format specifier'\n), 'sign beats alternate'\nassert _conv_err(lambda: f'{\"x\":,x}') == _conv_err(lambda: f'{1!r:,x}') == \"Cannot specify ',' with 'x'.\", (\n    'grouping beats type'\n)\n\n# === Zero-padding with negative numbers ===\n# zero-padding should use sign-aware alignment\nx = -42\nassert f'{x:05d}' == '-0042'\n\n# === Debug/self-documenting expressions (=) ===\na = 42\nassert f'{a=}' == 'a=42'\nassert f'{a = }' == 'a = 42'\nname = 'test'\nassert f'{name=}' == \"name='test'\"\nassert f'{name = }' == \"name = 'test'\"\nassert f'{name=!s}' == 'name=test'\nassert f'{name=!r}' == \"name='test'\"\nassert f'{1+1=}' == '1+1=2'\n# a format spec applies to the *value*, not the (default-repr) string — the\n# implicit repr only kicks in when there is no spec and no conversion\n_v = 6.28318\nassert f'{_v=:.3f}' == '_v=6.283'\nassert f'{_v=:>10.2f}' == '_v=      6.28'\nassert f'{_v=!r:>12}' == '_v=     6.28318'\nassert f'{_v=}' == '_v=6.28318'\n# an *explicit empty* spec (`{x=:}`) formats with str, NOT the repr default —\n# `format(x, \"\")` equals `str(x)`, so the colon disables the debug repr default\nassert f'{name=:}' == 'name=test'\nassert f'{a=:}' == 'a=42'\n_b = True\nassert f'{_b=:}' == '_b=True'\nassert f'{name = :}' == 'name = test'\nassert f'{name=!r:}' == \"name='test'\"\n\n# === Comma thousands separator ===\nassert f'{1234567:,}' == '1,234,567'\nassert f'{1234:,}' == '1,234'\nassert f'{12:,}' == '12'\nassert f'{0:,}' == '0'\nassert f'{-1234567:,}' == '-1,234,567'\nassert f'{1234567:,d}' == '1,234,567'\nassert f'{1234567.891:,f}' == '1,234,567.891000'\nassert f'{1234567.891:,.2f}' == '1,234,567.89'\nassert f'{-1234567.891:,.2f}' == '-1,234,567.89'\nassert f'{1234567.891:,e}' == '1.234568e+06'\nassert f'{1234.5:,g}' == '1,234.5'\nassert f'{12.3456:,%}' == '1,234.560000%'\nassert f'{1234:+,}' == '+1,234'\nassert f'{-1234:+,}' == '-1,234'\nassert f'{1234: ,}' == ' 1,234'\n\n# === Underscore thousands separator ===\nassert f'{1234567:_}' == '1_234_567'\nassert f'{1234567:_d}' == '1_234_567'\nassert f'{1234567.891:_.2f}' == '1_234_567.89'\n# Underscore groups binary/octal/hex in fours\nassert f'{255:_b}' == '1111_1111'\nassert f'{0xABCDEF:_x}' == 'ab_cdef'\nassert f'{0xABCDEF:_X}' == 'AB_CDEF'\nassert f'{0o12345670:_o}' == '1234_5670'\n\n# === Grouping with zero-padding (padding is itself grouped) ===\nassert f'{1234567:012,d}' == '0,001,234,567'\nassert f'{1234:010,}' == '00,001,234'\nassert f'{-1234:010,}' == '-0,001,234'\nassert f'{1234:08,}' == '0,001,234'\nassert f'{1234:07,}' == '001,234'\nassert f'{1234:05,}' == '1,234'\nassert f'{1234567.891:020,.2f}' == '0,000,001,234,567.89'\nassert f'{255:010_b}' == '0_1111_1111'\n\n# === Grouping with explicit alignment (fill is not grouped) ===\nassert f'{1234:=10,}' == '     1,234'\nassert f'{1234:=+10,}' == '+    1,234'\nassert f'{1234:>12,}' == '       1,234'\nassert f'{1234:*>12,}' == '*******1,234'\n\n# === Alternate form (#) on integer bases adds the 0b/0o/0x prefix ===\nassert f'{255:#x}' == '0xff'\nassert f'{255:#X}' == '0XFF'\nassert f'{5:#b}' == '0b101'\nassert f'{8:#o}' == '0o10'\nassert f'{-255:#x}' == '-0xff'\nassert f'{0:#x}' == '0x0'\nassert f'{255:#d}' == '255'\n# prefix counts toward width and sits before zero padding\nassert f'{255:#10x}' == '      0xff'\nassert f'{255:#010x}' == '0x000000ff'\nassert f'{-255:#010x}' == '-0x00000ff'\nassert f'{255:+#x}' == '+0xff'\n# prefix with alignment / grouping\nassert f'{255:<#10x}' == '0xff      '\nassert f'{255:^#10x}' == '   0xff   '\nassert f'{255:=#10x}' == '0x      ff'\nassert f'{255:*=#10x}' == '0x******ff'\nassert f'{0xABCDEF:#_x}' == '0xab_cdef'\nassert f'{0xABCDEF:#010_x}' == '0x0ab_cdef'\n\n# === Alternate form (#) on floats forces a decimal point ===\nassert f'{1.0:#.0f}' == '1.'\nassert f'{0.0:#.0f}' == '0.'\nassert f'{1.0:#.0e}' == '1.e+00'\nassert f'{3.14:+#.2f}' == '+3.14'\nassert f'{0.5:#.0%}' == '50.%'\n# explicit g/G keeps trailing zeros under #\nassert f'{1.0:#g}' == '1.00000'\nassert f'{100.0:#g}' == '100.000'\nassert f'{1.5:#.3g}' == '1.50'\nassert f'{1234.0:#.4g}' == '1234.'\n# default float presentation: # is a no-op (shortest repr already has a point)\nassert f'{3.14:#}' == '3.14'\n# `#g`/`#G`/type-less keep every trailing zero, so the digit count scales with\n# precision past Rust's formatter cap (regression: it used to silently truncate\n# to ~65k digits). Verify the count is exact, not clamped.\nassert f'{1.0:#.10g}' == '1.000000000'\nassert f'{1.0:#.10G}' == '1.000000000'\nassert f'{123456.0:#.10}' == '123456.0000'\nassert len(f'{1.0:#.70000g}') == 70001\nassert len(f'{1.0:#.70000}') == 70001\n\n# === inf / nan: case follows the presentation, never `.0` ===\n_inf = float('inf')\n_nan = float('nan')\nassert f'{_inf}' == 'inf'\nassert f'{-_inf}' == '-inf'\nassert f'{_nan}' == 'nan'\nassert str(_inf) == 'inf' and repr(_nan) == 'nan', 'inf/nan str/repr'\nassert f'{_inf:f}' == 'inf' and f'{_inf:F}' == 'INF', 'inf f vs F case'\nassert f'{_nan:e}' == 'nan' and f'{_nan:E}' == 'NAN', 'nan e vs E case'\nassert f'{_inf:g}' == 'inf' and f'{_inf:G}' == 'INF', 'inf g vs G case'\nassert f'{_nan:%}' == 'nan%'\nassert f'{_inf:+.2f}' == '+inf'\n# grouping/zero-pad on a non-finite value must not panic and ignores the comma\nassert f'{_inf:08,}' == '00000inf'\nassert f'{-_inf:+020,}' == '-0000000000000000inf'\nassert f'{_nan:,}' == 'nan'\n\n# === float repr uses scientific notation past CPython's thresholds ===\nassert f'{1e16}' == '1e+16'\nassert f'{1e15}' == '1000000000000000.0'\nassert f'{1e-5}' == '1e-05'\nassert f'{1e-4}' == '0.0001'\nassert f'{1.2345678901234568e16}' == '1.2345678901234568e+16'\nassert f'{1e100}' == '1e+100'\n\n# === type-less float spec uses repr digits, not g (precision-6) ===\nassert f'{1234567.0:}' == '1234567.0'\nassert f'{1234567.0:>12}' == '   1234567.0'\nassert f'{1234.5678:+,}' == '+1,234.5678'\n\n# === bool is an int subclass under a (non-empty) format spec ===\nassert f'{True}' == 'True' and f'{True:}' == 'True', 'bare bool is the word'\nassert f'{True: }' == ' 1'\nassert f'{False:05}' == '00000'\nassert f'{True:#06x}' == '0x0001'\nassert f'{True:.2f}' == '1.00'\n\n# === big integers honour the full mini-language ===\n_big = 2**70\nassert f'{_big:,}' == '1,180,591,620,717,411,303,424'\nassert f'{_big:+}' == '+1180591620717411303424'\nassert f'{_big:#x}' == '0x400000000000000000'\nassert f'{_big:#o}' == '0o200000000000000000000000'\nassert f'{-(2**63):>25}' == '     -9223372036854775808'\nassert f'{2**63:.3e}' == '9.223e+18'\n\n# === precision is rejected on integer presentations ===\nfor _spec in ('.2d', '.2', '.2x', '.2b', '.0c'):\n    try:\n        f'{42:{_spec}}'\n        assert False, f'expected precision on int spec {_spec!r} to fail'\n    except ValueError as _e:\n        assert str(_e) == 'Precision not allowed in integer format specifier', f'{_spec}: {_e}'\n\n# === c rejects a sign; strings reject signs and `=` alignment ===\ntry:\n    f'{65:+c}'\n    assert False, 'expected sign with c to fail'\nexcept ValueError as _e:\n    assert str(_e) == \"Sign not allowed with integer format specifier 'c'\", f'sign+c: {_e}'\ntry:\n    f'{\"x\":+}'\n    assert False, 'expected sign on string to fail'\nexcept ValueError as _e:\n    assert str(_e) == 'Sign not allowed in string format specifier', f'sign+str: {_e}'\ntry:\n    f'{\"x\": }'\n    assert False, 'expected space on string to fail'\nexcept ValueError as _e:\n    assert str(_e) == 'Space not allowed in string format specifier', f'space+str: {_e}'\ntry:\n    f'{\"x\":=5}'\n    assert False, 'expected = alignment on string to fail'\nexcept ValueError as _e:\n    assert str(_e) == \"'=' alignment not allowed in string format specifier\", f'=+str: {_e}'\n\n# === `0` flag with an explicit alignment is just a `0` fill, not sign-aware ===\nassert f'{-42:<05}' == '-4200'\nassert f'{42:^05}' == '04200'\nassert f'{42:>05}' == '00042'\nassert f'{42:*<05}' == '42***'\nassert f'{-42:05}' == '-0042'\nassert f'{\"hi\":05}' == 'hi000'\n\n# === `c` is a numeric presentation: right-aligned by default ===\nassert f'{65:5c}' == '    A'\nassert f'{65:<5c}' == 'A    '\nassert f'{65:05c}' == '0000A'\n\n# === `n` (locale number): like `d` for int, `g` for float (C locale here) ===\nassert f'{1234567:n}' == '1234567'\nassert f'{1234567.0:n}' == '1.23457e+06'\nassert f'{-42:+n}' == '-42'\nassert f'{2**70:n}' == '1180591620717411303424'\nassert f'{True:n}' == '1'\n# n forbids an explicit grouping and (for ints) a precision\ntry:\n    f'{1234:,n}'\n    assert False, 'expected , with n to fail'\nexcept ValueError as _e:\n    assert str(_e) == \"Cannot specify ',' with 'n'.\", f',n: {_e}'\ntry:\n    f'{42:.2n}'\n    assert False, 'expected precision with int n to fail'\nexcept ValueError as _e:\n    assert str(_e) == 'Precision not allowed in integer format specifier', f'.2n: {_e}'\n\n# === Fractional grouping (Python 3.14): [.precision][grouping] ===\nassert f'{1234.5678:.6_f}' == '1234.567_800'\nassert f'{1234567.89:,.4_f}' == '1,234,567.890_0'\nassert f'{12345.678:._f}' == '12345.678_000'\nassert f'{1234567.891:,._f}' == '1,234,567.891_000'\n\n# === Type-less float with an explicit precision (g-like, one exp earlier) ===\nassert f'{100.0:.3}' == '1e+02'\nassert f'{1.0:.0}' == '1e+00'\nassert f'{1234.5678:.6}' == '1234.57'\nassert f'{9.99:.1g}' == '1e+01'\n\n# === Error precedence: an invalid type code beats the #/sign checks ===\ntry:\n    f'{3.14:#c}'\n    assert False, 'expected #c on float to fail'\nexcept ValueError as _e:\n    assert str(_e) == \"Unknown format code 'c' for object of type 'float'\", f'#c float: {_e}'\ntry:\n    f'{42:#s}'\n    assert False, 'expected #s on int to fail'\nexcept ValueError as _e:\n    assert str(_e) == \"Unknown format code 's' for object of type 'int'\", f'#s int: {_e}'\n",
  'fstring__error_eq_align_on_str.py':
