  'fstring__pyformat.py':
      "# Every example from https://pyformat.info/ , converted to f-strings.\n#\n# pyformat.info presents each example in old `%` style and new `str.format()`\n# style. Monty implements the format mini-language ONLY through f-strings (no\n# `str.format()` / `%` / general `__format__` protocol — see\n# limitations/format.md), so each `.format()` example is written here as the\n# equivalent f-string. Examples that rely on a user-defined class (`Data`,\n# `Plant`, `HAL9000`) can't be represented verbatim — Monty has no `class`\n# statement — so they are adapted to built-in values that exercise the same\n# formatting feature, with a note.\n\nfrom datetime import datetime\n\n# === Basic formatting ===\n# '{} {}'.format('one', 'two') / '{} {}'.format(1, 2) / '{1} {0}'.format(...)\nassert f'{\"one\"} {\"two\"}' == 'one two'\nassert f'{1} {2}' == '1 2'\n# `{1} {0}` reorders args; f-strings inline the values in the wanted order.\nassert f'{\"two\"} {\"one\"}' == 'two one'\n\n# === Value conversion (!s / !r / !a) ===\n# Original uses a Data() class whose __str__/__repr__ differ. A plain string\n# shows the same distinction: !s -> str(), !r -> repr() (adds quotes).\nassert f'{\"text\"!s} {\"text\"!r}' == \"text 'text'\"\n# '{0!r} {0!a}' on a non-ASCII value: !r keeps it, !a escapes to ASCII.\nassert f'{\"räpr\"!r} {\"räpr\"!a}' == \"'räpr' 'r\\\\xe4pr'\"\n\n# === Padding and aligning strings ===\nassert f'{\"test\":>10}' == '      test'\nassert f'{\"test\":10}' == 'test      '\nassert f'{\"test\":_<10}' == 'test______'\nassert f'{\"test\":^10}' == '   test   '\nassert f'{\"zip\":^6}' == ' zip  '\n\n# === Truncating long strings ===\nassert f'{\"xylophone\":.5}' == 'xylop'\n\n# === Combining truncating and padding ===\nassert f'{\"xylophone\":10.5}' == 'xylop     '\n\n# === Numbers ===\nassert f'{42:d}' == '42'\nassert f'{3.141592653589793:f}' == '3.141593'\n\n# === Padding numbers ===\nassert f'{42:4d}' == '  42'\nassert f'{3.141592653589793:06.2f}' == '003.14'\nassert f'{42:04d}' == '0042'\n\n# === Signed numbers ===\nassert f'{42:+d}' == '+42'\nassert f'{-23: d}' == '-23'\nassert f'{42: d}' == ' 42'\nassert f'{-23:=5d}' == '-  23'\nassert f'{23:=+5d}' == '+  23'\n\n# === Named placeholders ===\n# '{first} {last}'.format(first='Hodor', last='Hodor!') -> just reference vars.\nfirst = 'Hodor'\nlast = 'Hodor!'\nassert f'{first} {last}' == 'Hodor Hodor!'\n\n# === Getitem and getattr ===\n# '{p[first]} {p[last]}'.format(p=person) — dict subscript in the expression.\nperson = {'first': 'Jean-Luc', 'last': 'Picard'}\nassert f'{person[\"first\"]} {person[\"last\"]}' == 'Jean-Luc Picard'\n# '{d[4]} {d[5]}'.format(d=data) — list indexing.\ndata = [0, 1, 2, 3, 23, 42]\nassert f'{data[4]} {data[5]}' == '23 42'\n# '{p.type}: {p.kinds[0][name]}' uses a custom class; demonstrate the same\n# attribute-access + chained-getitem capability with built-in values.\ndt = datetime(2001, 2, 3, 4, 5)\nassert f'{dt.year}' == '2001'\nplant = {'kinds': [{'name': 'oak'}]}\nassert f'tree: {plant[\"kinds\"][0][\"name\"]}' == 'tree: oak'\n\n# === Datetime ===\nassert f'{dt:%Y-%m-%d %H:%M}' == '2001-02-03 04:05'\n\n# === Parametrized (nested) formats ===\n# '{:{align}{width}}'.format('test', align='^', width='10')\nalign = '^'\nwidth = 10\nassert f'{\"test\":{align}{width}}' == '   test   '\n# '{:.{prec}} = {:.{prec}f}'.format('Gibberish', 2.7182, prec=3)\nprec = 3\nassert f'{\"Gibberish\":.{prec}} = {2.7182:.{prec}f}' == 'Gib = 2.718'\n# '{:{width}.{prec}f}'.format(2.7182, width=5, prec=2)\nw = 5\np = 2\nassert f'{2.7182:{w}.{p}f}' == ' 2.72'\n# '{:{prec}} = {:{prec}}'.format('Gibberish', 2.7182, prec='.3')\nprec_str = '.3'\nassert f'{\"Gibberish\":{prec_str}} = {2.7182:{prec_str}}' == 'Gib = 2.72'\n# '{:{dfmt} {tfmt}}'.format(dt, dfmt='%Y-%m-%d', tfmt='%H:%M') — nested strftime.\ndfmt = '%Y-%m-%d'\ntfmt = '%H:%M'\nassert f'{dt:{dfmt} {tfmt}}' == '2001-02-03 04:05'\n# '{:{}{}{}.{}}'.format(2.7182818284, '>', '+', 10, 3) — all parts parametrized.\nassert f'{2.7182818284:{\">\"}{\"+\"}{10}.{3}}' == '     +2.72'\n# '{:{}{sign}{}.{}}'.format(2.7182818284, '>', 10, 3, sign='+') — mixed.\nsign = '+'\nassert f'{2.7182818284:{\">\"}{sign}{10}.{3}}' == '     +2.72'\n\n# === Escaping braces ===\n# '{{}}'.format() -> literal braces; '{{{}}}'.format('x') -> '{x}'.\nassert f'{{}}' == '{}'\nassert f'{{{\"x\"}}}' == '{x}'\n\n# === Custom objects (not representable in Monty) ===\n# pyformat.info also shows '{:%Y}'.format(custom) and\n# '{:open-the-pod-bay-doors}'.format(HAL9000()), which dispatch to a\n# user-defined __format__. Monty has no `class` statement and no general\n# __format__ protocol (only date/datetime get strftime handling — covered\n# above), so these have no f-string equivalent and are intentionally omitted.\n",
  'function__arity_defaults.py':
      "# Arity errors for functions whose positional params have defaults: CPython\n# reports the range form for too-many ('takes from X to Y positional\n# arguments') and counts only *required* params as missing.\n\n\ndef f(a, b=1):\n    return a + b\n\n\ndef g(a, b, c=1, d=2):\n    return a + b + c + d\n\n\ntry:\n    f(1, 2, 3)\n    assert False, 'f(1, 2, 3) should raise TypeError'\nexcept TypeError as e:\n    assert str(e) == 'f() takes from 1 to 2 positional arguments but 3 were given', f'range too-many: {e}'\n\ntry:\n    f()\n    assert False, 'f() should raise TypeError'\nexcept TypeError as e:\n    assert str(e) == \"f() missing 1 required positional argument: 'a'\", f'defaults not missing: {e}'\n\ntry:\n    g(1)\n    assert False, 'g(1) should raise TypeError'\nexcept TypeError as e:\n    assert str(e) == \"g() missing 1 required positional argument: 'b'\", f'only required missing: {e}'\n\ntry:\n    g()\n    assert False, 'g() should raise TypeError'\nexcept TypeError as e:\n    assert str(e) == \"g() missing 2 required positional arguments: 'a' and 'b'\", f'two missing joined: {e}'\n\ntry:\n    g(1, 2, 3, 4, 5)\n    assert False, 'g(1, 2, 3, 4, 5) should raise TypeError'\nexcept TypeError as e:\n    assert str(e) == 'g() takes from 2 to 4 positional arguments but 5 were given', f'range too-many g: {e}'\n\n\ndef h(a, b, c):\n    return a\n\n\ntry:\n    h()\n    assert False, 'h() should raise TypeError'\nexcept TypeError as e:\n    assert str(e) == \"h() missing 3 required positional arguments: 'a', 'b', and 'c'\", f'oxford comma: {e}'\n\n\n# === keyword errors beat too-many-positional (CPython binds kwargs first) ===\ndef k1(a):\n    return a\n\n\ntry:\n    k1(1, 2, bad=3)\n    assert False, 'k1(1, 2, bad=3) should raise TypeError'\nexcept TypeError as e:\n    assert str(e) == \"k1() got an unexpected keyword argument 'bad'\", f'unknown kwarg beats overflow: {e}'\n\ntry:\n    k1(1, 2, a=3)\n    assert False, 'k1(1, 2, a=3) should raise TypeError'\nexcept TypeError as e:\n    assert str(e) == \"k1() got multiple values for argument 'a'\", f'duplicate beats overflow: {e}'\n\n\ndef k2(a, *, c=1):\n    return a\n\n\n# A kwarg that binds cleanly to a keyword-only param leaves the overflow to\n# fire, counted in the `(and N keyword-only argument(s))` suffix — only\n# *bound* kw-only params count, defaults and unknown names do not.\ntry:\n    k2(1, 2, c=3)\n    assert False, 'k2(1, 2, c=3) should raise TypeError'\nexcept TypeError as e:\n    assert (\n        str(e) == 'k2() takes 1 positional argument but 2 positional arguments (and 1 keyword-only argument) were given'\n    ), f'kwonly suffix counts bound params: {e}'\n\ntry:\n    k2(1, 2, c=3, bad=4)\n    assert False, 'k2(1, 2, c=3, bad=4) should raise TypeError'\nexcept TypeError as e:\n    assert str(e) == \"k2() got an unexpected keyword argument 'bad'\", f'unknown kwarg beats overflow with kwonly: {e}'\n\ntry:\n    k2(1, 2)\n    assert False, 'k2(1, 2) should raise TypeError'\nexcept TypeError as e:\n    assert str(e) == 'k2() takes 1 positional argument but 2 were given', f'no suffix when no kwonly bound: {e}'\n\n\ndef k3(a, b=1, *, c, d=2):\n    return a\n\n\ntry:\n    k3(1, 2, 3, c=5, d=6)\n    assert False, 'k3(1, 2, 3, c=5, d=6) should raise TypeError'\nexcept TypeError as e:\n    assert (\n        str(e)\n        == 'k3() takes from 1 to 2 positional arguments but 3 positional arguments (and 2 keyword-only arguments) were given'\n    ), f'plural kwonly suffix: {e}'\n",
  'function__call_duplicate_kwargs.py':
      "def f(**kwargs):\n    pass\n\n\nf(**{'x': 1}, **{'x': 2})\n# Raise=TypeError(\"f() got multiple values for keyword argument 'x'\")\n",
  'function__call_unpack.py':
      "def f(*args, **kwargs):\n    return args, kwargs\n\n\n# === Multiple *args ===\nassert f(*[1, 2], *[3, 4]) == ((1, 2, 3, 4), {})\nassert f(0, *[1, 2], 3) == ((0, 1, 2, 3), {})\nassert f(*[], *[1]) == ((1,), {})\n\n# === Multiple **kwargs ===\nassert f(**{'a': 1}, **{'b': 2}) == ((), {'a': 1, 'b': 2})\nassert f(**{'a': 1}, b=2) == ((), {'a': 1, 'b': 2})\nassert f(key='before', **{'a': 1}) == ((), {'key': 'before', 'a': 1})\n\n# === Mixed ===\nassert f(1, *[2, 3], **{'x': 4}) == ((1, 2, 3), {'x': 4})\n\n# === Builtin callable with GeneralizedCall (Callable::Builtin path) ===\n# max(*[1,2], *[3,4]) exercises the Callable::Builtin branch in compile_call GeneralizedCall\nresult = max(*[1, 2], *[3, 4])\nassert result == 4\n\nresult = min(*[5, 3], *[7, 1])\nassert result == 1\n\n# Builtin type and exception constructors should keep their public names in\n# **kwargs merge errors, not fall back to '<unknown>'.\ntry:\n    list(**1)\n    assert False, 'list with non-mapping **arg should raise TypeError'\nexcept TypeError as e:\n    assert e.args == ('list() argument after ** must be a mapping, not int',)\n\ntry:\n    ValueError(**1)\n    assert False, 'ValueError with non-mapping **arg should raise TypeError'\nexcept TypeError as e:\n    assert e.args == ('ValueError() argument after ** must be a mapping, not int',)\n\ntry:\n    list(a=1, **{'a': 2})\n    assert False, 'list with duplicate **kwargs should raise TypeError'\nexcept TypeError as e:\n    assert e.args == (\"list() got multiple values for keyword argument 'a'\",)\n\n# Builtin type constructors should also keep their public names in\n# non-mapping **kwargs errors so compiler call metadata matches CPython.\ntry:\n    bool(**1)\n    assert False, 'bool with non-mapping **arg should raise TypeError'\nexcept TypeError as e:\n    assert e.args == ('bool() argument after ** must be a mapping, not int',)\n\ntry:\n    int(**1)\n    assert False, 'int with non-mapping **arg should raise TypeError'\nexcept TypeError as e:\n    assert e.args == ('int() argument after ** must be a mapping, not int',)\n\ntry:\n    float(**1)\n    assert False, 'float with non-mapping **arg should raise TypeError'\nexcept TypeError as e:\n    assert e.args == ('float() argument after ** must be a mapping, not int',)\n\ntry:\n    str(**1)\n    assert False, 'str with non-mapping **arg should raise TypeError'\nexcept TypeError as e:\n    assert e.args == ('str() argument after ** must be a mapping, not int',)\n\ntry:\n    bytes(**1)\n    assert False, 'bytes with non-mapping **arg should raise TypeError'\nexcept TypeError as e:\n    assert e.args == ('bytes() argument after ** must be a mapping, not int',)\n\ntry:\n    tuple(**1)\n    assert False, 'tuple with non-mapping **arg should raise TypeError'\nexcept TypeError as e:\n    assert e.args == ('tuple() argument after ** must be a mapping, not int',)\n\ntry:\n    dict(**1)\n    assert False, 'dict with non-mapping **arg should raise TypeError'\nexcept TypeError as e:\n    assert e.args == ('dict() argument after ** must be a mapping, not int',)\n\ntry:\n    set(**1)\n    assert False, 'set with non-mapping **arg should raise TypeError'\nexcept TypeError as e:\n    assert e.args == ('set() argument after ** must be a mapping, not int',)\n\ntry:\n    frozenset(**1)\n    assert False, 'frozenset with non-mapping **arg should raise TypeError'\nexcept TypeError as e:\n    assert e.args == ('frozenset() argument after ** must be a mapping, not int',)\n\ntry:\n    range(**1)\n    assert False, 'range with non-mapping **arg should raise TypeError'\nexcept TypeError as e:\n    assert e.args == ('range() argument after ** must be a mapping, not int',)\n\ntry:\n    slice(**1)\n    assert False, 'slice with non-mapping **arg should raise TypeError'\nexcept TypeError as e:\n    assert e.args == ('slice() argument after ** must be a mapping, not int',)\n\ntry:\n    type(**1)\n    assert False, 'type with non-mapping **arg should raise TypeError'\nexcept TypeError as e:\n    assert e.args == ('type() argument after ** must be a mapping, not int',)\n\ntry:\n    property(**1)\n    assert False, 'property with non-mapping **arg should raise TypeError'\nexcept TypeError as e:\n    assert e.args == ('property() argument after ** must be a mapping, not int',)\n\ntry:\n    ValueError(a=1, **{'a': 2})\n    assert False, 'ValueError with duplicate **kwargs should raise TypeError'\nexcept TypeError as e:\n    assert e.args == (\"ValueError() got multiple values for keyword argument 'a'\",)\n\n# === Expression-based callable with GeneralizedCall (compile_call_args path) ===\n# funcs[0](*[1,2], *[3,4]) exercises the GeneralizedCall branch in compile_call_args\nfuncs = [f]\nresult = funcs[0](*[1, 2], *[3, 4])\nassert result == ((1, 2, 3, 4), {})\n\nresult = funcs[0](**{'a': 1}, **{'b': 2})\nassert result == ((), {'a': 1, 'b': 2})\n\n# === Named kwarg in GeneralizedCall (compile_generalized_call_body Named path) ===\n# f(*[1,2], *[3], x=5): two *unpacks → GeneralizedCall; x=5 is a Named kwarg.\n# This exercises the CallKwarg::Named arm in compile_generalized_call_body.\nresult = f(*[1, 2], *[3], x=5)\nassert result == ((1, 2, 3), {'x': 5})\n\nresult = funcs[0](*[1, 2], *[3], x=5)\nassert result == ((1, 2, 3), {'x': 5})\n",
  'function__defaults.py':
      "# Tests for default parameter values in function definitions\n\n# === Basic default values ===\ndef f_basic(a, b=10):\n    return a + b\n\n\nassert f_basic(1) == 11\nassert f_basic(1, 2) == 3\nassert f_basic(5) == 15\n\n\n# === Multiple defaults ===\ndef f_multi(a=1, b=2):\n    return a + b\n\n\nassert f_multi() == 3\nassert f_multi(10) == 12\nassert f_multi(10, 20) == 30\n\n\n# === Mixed required and default ===\ndef f_mixed(a, b, c=3, d=4):\n    return a + b + c + d\n\n\nassert f_mixed(1, 2) == 10\nassert f_mixed(1, 2, 30) == 37\nassert f_mixed(1, 2, 30, 40) == 73\n\n\n# === Default with keyword args ===\ndef f_kw(a, b=10):\n    return a + b\n\n\nassert f_kw(1, b=20) == 21\nassert f_kw(a=5) == 15\nassert f_kw(a=5, b=3) == 8\n\n\n# === Default expressions evaluated at definition ===\n# Test that default is evaluated once at definition time\ndef value_maker():\n    return 42\n\n\ndef f_eval(x=value_maker()):\n    return x\n\n\n# value_maker was called once at function definition time\nassert f_eval() == 42\nassert f_eval() == 42\n\n\n# === Mutable default (Python gotcha - shared across calls) ===\ndef f_mutable(lst=[]):\n    lst.append(1)\n    return lst\n\n\nfirst_result = f_mutable()\nassert first_result == [1]\nsecond_result = f_mutable()\nassert second_result == [1, 1]\nassert first_result is second_result\n\n\n# === Multiple functions with separate defaults ===\ndef f_sep1(x=[]):\n    x.append('a')\n    return x\n\n\ndef f_sep2(x=[]):\n    x.append('b')\n    return x\n\n\nr1 = f_sep1()\nr2 = f_sep2()\nassert r1 == ['a']\nassert r2 == ['b']\nassert r1 is not r2\n\n\n# === Default referencing earlier param (not supported, different test) ===\n\n\n# === Closure with defaults ===\ndef make_adder(n):\n    def add(x, y=n):\n        return x + y\n\n    return add\n\n\nadd5 = make_adder(5)\nassert add5(10) == 15\nassert add5(10, 3) == 13\n\nadd10 = make_adder(10)\nassert add10(1) == 11\n\n# Verify the two closures have independent defaults\nassert add5(1) == 6\n\n\n# === Keyword-only defaults interleaved ===\ndef kwonly_mix(*, head=1, mid, tail=3):\n    return head, mid, tail\n\n\nassert kwonly_mix(mid=2) == (1, 2, 3)\nassert kwonly_mix(head=5, mid=7) == (5, 7, 3)\n",
