  'global__error_assigned_before.py':
      "# Regression coverage for the `global X` ordering diagnostics, including the\n# CPython quirk reported in https://github.com/pydantic/monty/issues/423:\n# `import` bindings DO NOT count as \"assigned to before global declaration\"\n# even though every other binding form does.\n#\n# Each `def` below stresses one rule. The function bodies are never executed\n# — defining them is enough to trigger prepare-time scope validation. The\n# file ends with the one form that IS expected to raise a SyntaxError, which\n# the harness verifies through the `# Raise=` comment.\n\n\n# --- Import bindings are accepted by CPython ---------------------------\n# `import X`, `import X as Y`, and `from M import X [as Y]` are treated as\n# \"soft\" bindings that don't conflict with a subsequent `global` in the same\n# scope (issue #423). The `global` declaration takes precedence, making the\n# import effectively rebind the module-level name.\n\n\ndef import_plain_then_global():\n    import os\n\n    global os  # type: ignore[reportAssignmentBeforeGlobalDeclaration]\n\n\ndef import_as_then_global():\n    import os as alias_plain\n\n    global alias_plain  # type: ignore[reportAssignmentBeforeGlobalDeclaration]\n\n\ndef from_import_then_global():\n    from os import path\n\n    global path  # type: ignore[reportAssignmentBeforeGlobalDeclaration]\n\n\ndef from_import_as_then_global():\n    from os import path as alias_path\n\n    global alias_path  # type: ignore[reportAssignmentBeforeGlobalDeclaration]\n\n\n# --- Reads inside a nested scope don't pollute this scope --------------\n# Reads inside a `lambda` body or nested `def` happen in a sub-scope, so\n# they don't trigger this scope's \"used prior to\" check.\n\n\ndef lambda_read_then_global():\n    lambda: lambda_target\n    global lambda_target\n\n\ndef nested_def_read_then_global():\n    def nested_reader():\n        return nested_target\n\n    _ = nested_reader  # keep pyright happy about the nested def\n    global nested_target\n\n    def nested_target():\n        pass\n\n\n# --- The non-import binding form that DOES error -----------------------\n# A plain assignment before `global` is the canonical SyntaxError.\n\n\ndef f():\n    x = 1\n    global x  # type: ignore[reportAssignmentBeforeGlobalDeclaration]\n\n\nf()\n# Raise=SyntaxError(\"name 'x' is assigned to before global declaration\")\n",
  'global__ops.py':
      "# === Basic global read/write ===\nx1 = 42\n\n\ndef read_explicit():\n    global x1\n    return x1\n\n\nassert read_explicit() == 42\n\n\nx2 = 1\n\n\ndef write_explicit():\n    global x2\n    x2 = 2\n\n\nwrite_explicit()\nassert x2 == 2\n\n\nx3 = 42\n\n\ndef read_implicit():\n    return x3  # no local x3, reads global\n\n\nassert read_implicit() == 42\n\n\n# === Multiple functions sharing global ===\ncounter1 = 0\n\n\ndef inc():\n    global counter1\n    counter1 = counter1 + 1\n\n\ndef get_counter():\n    return counter1\n\n\ninc()\ninc()\nassert get_counter() == 2\n\n\n# === Mutating global containers (no 'global' needed) ===\ndata1 = {'a': 1}\n\n\ndef add_dict_entry():\n    data1['b'] = 2\n\n\nadd_dict_entry()\nassert data1 == {'a': 1, 'b': 2}\n\n\nitems1 = [1, 2]\n\n\ndef append_list_item():\n    items1.append(3)\n\n\nappend_list_item()\nassert items1 == [1, 2, 3]\n\n\nitems2 = ['a', 'c']\n\n\ndef insert_list_item():\n    items2.insert(1, 'b')\n\n\ninsert_list_item()\nassert items2 == ['a', 'b', 'c']\n\n\nitems3 = []\n\n\ndef build_list():\n    items3.append(1)\n    items3.append(2)\n    items3.append(3)\n\n\nbuild_list()\nassert items3 == [1, 2, 3]\n\n\n# === Reassigning global containers (requires 'global') ===\nitems4 = [1, 2]\n\n\ndef replace_list():\n    global items4\n    items4 = [3, 4, 5]\n\n\nreplace_list()\nassert items4 == [3, 4, 5]\n\n\n# === Nested functions with global ===\nx4 = 1\n\n\ndef outer_global():\n    def inner():\n        global x4\n        x4 = 10\n\n    inner()\n\n\nouter_global()\nassert x4 == 10\n\n\nx5 = 42\n\n\ndef outer_read():\n    def inner():\n        return x5  # reads global\n\n    return inner()\n\n\nassert outer_read() == 42\n\n\n# === Shadowing ===\nx6 = 10\n\n\ndef shadow_local():\n    x6 = 20  # creates local (shadows global)\n    return x6\n\n\nassert shadow_local() == 20\n\n\nx7 = 10\n\n\ndef shadow_unchanged():\n    x7 = 99  # local\n    return x7\n\n\nassert shadow_unchanged() == 99\nassert x7 == 10\n\n\n# === `global X` for a name that doesn't yet exist at module level ===\n\n\ndef declare_then_write():\n    global ghost1\n    ghost1 = 5\n\n\ndeclare_then_write()\nassert ghost1 == 5\n\n\ndef declare_then_read():\n    global ghost2\n    return ghost2\n\n\ntry:\n    declare_then_read()\n    raise AssertionError('expected NameError for never-assigned global')\nexcept NameError as exc:\n    assert str(exc) == \"name 'ghost2' is not defined\"\n\n\n# === Forward reference to a later module-level binding ===\n\n\ndef read_late_value():\n    return late_value\n\n\nlate_value = 'bound'\nassert read_late_value() == 'bound'\n\n\n# === Late binding overrides parse-time builtin resolution ===\n\n\ndef call_min():\n    return min([3, 1, 2])\n\n\nassert call_min() == 1\n\n\ndef min(*args):\n    return 'shadowed'\n\n\nassert call_min() == 'shadowed'\n\n\n# === Module-scope shadowing builtins ===\n\nassert max(1, 2) == 2\n\n\ndef max(*args):\n    return 'shadowed-max'\n\n\nassert max(1, 2) == 'shadowed-max'\n\n\n# === Deeply nested `global X` ===\n\n\ndef deep_outer():\n    def deep_inner():\n        global deep_x\n        deep_x = 'reached-module'\n\n    deep_inner()\n\n\ndeep_outer()\nassert deep_x == 'reached-module'\n",
