  'import__sys.py':
      "# Tests for sys module import\n\nimport sys\n\n# === sys.version ===\n# Check that version is a non-empty string (exact value differs between interpreters)\nassert isinstance(sys.version, str)\nassert len(sys.version) > 0\n\n# === sys.version_info ===\n# Test index access returns integers for first 3 elements\nassert isinstance(sys.version_info[0], int)\nassert isinstance(sys.version_info[1], int)\nassert isinstance(sys.version_info[2], int)\nassert isinstance(sys.version_info[3], str)\nassert isinstance(sys.version_info[4], int)\n\n# Test negative indexing\nassert sys.version_info[-1] == sys.version_info[4]\nassert sys.version_info[-2] == sys.version_info[3]\nassert sys.version_info[-5] == sys.version_info[0]\n\n# Test named attribute access matches index access\nassert sys.version_info.major == sys.version_info[0]\nassert sys.version_info.minor == sys.version_info[1]\nassert sys.version_info.micro == sys.version_info[2]\nassert sys.version_info.releaselevel == sys.version_info[3]\nassert sys.version_info.serial == sys.version_info[4]\n\n# Test len\nassert len(sys.version_info) == 5\n\n# Test tuple equality (works after fixing NamedTuple equality)\nv = sys.version_info\nassert (v[0], v[1]) == (v.major, v.minor)\nassert v.major == v[0]\nassert v.minor == v[1]\n\n# === sys.platform ===\n# Check that platform is a non-empty string (exact value differs between interpreters)\nassert isinstance(sys.platform, str)\nassert len(sys.platform) > 0\n\n# === sys.stdout and sys.stderr ===\n# These should exist - we test by accessing them (will fail if not present)\nstdout = sys.stdout\nstderr = sys.stderr\n",
  'import__sys_monty.py':
      "# xfail=cpython\n# Tests for Monty-specific sys module values\n\nimport sys\n\n# === sys.version ===\nassert sys.version == '3.14.0 (Monty)', f'version should be 3.14.0 (Monty), got {sys.version!r}'\n\n# === sys.version_info exact values ===\nassert sys.version_info[0] == 3\nassert sys.version_info[1] == 14\nassert sys.version_info[2] == 0\nassert sys.version_info[3] == 'final'\nassert sys.version_info[4] == 0\n\n# === sys.version_info named attributes ===\nassert sys.version_info.major == 3\nassert sys.version_info.minor == 14\nassert sys.version_info.micro == 0\nassert sys.version_info.releaselevel == 'final'\nassert sys.version_info.serial == 0\n\n# === sys.version_info tuple equality ===\n# This works because NamedTuple equality compares only by elements, not type_name\nassert sys.version_info == (3, 14, 0, 'final', 0)\n\n# === sys.platform ===\nassert sys.platform == 'monty', f'platform should be monty, got {sys.platform!r}'\n",
  'import__type_checking_guard.py':
      "# === TYPE_CHECKING guard ===\n# Imports inside TYPE_CHECKING blocks should not raise errors at runtime\n# because TYPE_CHECKING is False at runtime, so the import is never executed.\nfrom typing import TYPE_CHECKING\n\nif TYPE_CHECKING:\n    import also_nonexistent\n    from nonexistent_module import something\n\n# Verify TYPE_CHECKING is False at runtime (as expected)\nassert TYPE_CHECKING is False\n\n\n# === Function using TYPE_CHECKING for conditional import ===\ndef get_type_checking_value():\n    if TYPE_CHECKING:\n        from another_fake_module import FakeType\n    return 'success'\n\n\nresult = get_type_checking_value()\nassert result == 'success'\n\n# === Nested TYPE_CHECKING blocks ===\nif TYPE_CHECKING:\n    if True:\n        from deeply_nested_fake import DeepFake\n\n# === TYPE_CHECKING in else branch (should not be executed either) ===\nx = True\nif x:\n    pass\nelse:\n    if TYPE_CHECKING:\n        from unreachable_module import Unreachable\n\nassert True\n",
  'import__typing.py':
