  'list__index_start_gt_end.py':
      "# Test that list.index with start > end doesn't panic but raises ValueError\n[1, 2, 3].index(1, 5, 2)\n\"\"\"\nTRACEBACK:\nTraceback (most recent call last):\n  File \"list__index_start_gt_end.py\", line 2, in <module>\n    [1, 2, 3].index(1, 5, 2)\n    ~~~~~~~~~~~~~~~~~~~~~~~~\nValueError: list.index(x): x not in list\n\"\"\"\n",
  'list__ops.py':
      "# === List concatenation (+) ===\nassert [1, 2] + [3, 4] == [1, 2, 3, 4]\nassert [] + [1, 2] == [1, 2]\nassert [1, 2] + [] == [1, 2]\nassert [] + [] == []\nassert [1] + [2] + [3] + [4] == [1, 2, 3, 4]\nassert [[1]] + [[2]] == [[1], [2]]\n\n# === Augmented assignment (+=) ===\nlst = [1, 2]\nlst += [3, 4]\nassert lst == [1, 2, 3, 4]\n\nlst = [1]\nalias = lst\nlst += [2]\nassert lst is alias\nassert alias == [1, 2]\n\nlst = [1, 2, 3]\nindex = 1\nlst[index] += 5\nassert lst == [1, 7, 3]\n\ntry:\n    lst = [1]\n    lst[5] += 1\n    assert False, 'subscript += past the end of a list should raise IndexError'\nexcept IndexError as e:\n    assert e.args == ('list index out of range',)\n\nlst = [1]\nlst += []\nassert lst == [1]\n\nlst = [1]\nlst += [2]\nlst += [3]\nassert lst == [1, 2, 3]\n\nlst = [1, 2]\nlst += lst\nassert lst == [1, 2, 1, 2]\n\n# === List length ===\nassert len([]) == 0\nassert len([1, 2, 3]) == 3\n\nlst = [1]\nlst.append(2)\nassert len(lst) == 2\n\n# === List indexing ===\na = []\na.append('value')\nassert a[0] == 'value'\n\na = [1, 2, 3]\nassert a[0 - 1] == 3\nassert a[-1] == 3\nassert a[-2] == 2\n\n# === List repr/str ===\nassert repr([]) == '[]'\nassert str([]) == '[]'\n\nassert repr([1, 2, 3]) == '[1, 2, 3]'\nassert str([1, 2, 3]) == '[1, 2, 3]'\n\n# === List repetition (*) ===\nassert [1, 2] * 3 == [1, 2, 1, 2, 1, 2]\nassert 3 * [1, 2] == [1, 2, 1, 2, 1, 2]\nassert [1] * 0 == []\nassert [1] * -1 == []\nassert [] * 5 == []\nassert [1, 2] * 1 == [1, 2]\nassert [[1]] * 2 == [[1], [1]]\n\n# === List repetition augmented assignment (*=) ===\nlst = [1, 2]\nlst *= 2\nassert lst == [1, 2, 1, 2]\n\nlst = [1]\nlst *= 0\nassert lst == []\n\n# === list() constructor ===\nassert list() == []\nassert list([1, 2, 3]) == [1, 2, 3]\nassert list((1, 2, 3)) == [1, 2, 3]\nassert list(range(3)) == [0, 1, 2]\nassert list('abc') == ['a', 'b', 'c']\nassert list(b'abc') == [97, 98, 99]\nassert list({'a': 1, 'b': 2}) == ['a', 'b']\n\n# non-ASCII strings (multi-byte UTF-8)\nassert list('héllo') == ['h', 'é', 'l', 'l', 'o']\nassert list('日本') == ['日', '本']\nassert list('a🎉b') == ['a', '🎉', 'b']\n\n# === list.append() ===\nlst = []\nlst.append(1)\nassert lst == [1]\nlst.append(2)\nassert lst == [1, 2]\nlst.append(lst)  # append self creates cycle\nassert len(lst) == 3\n\n# === list.insert() ===\n# Basic insert at various positions\nlst = [1, 2, 3]\nlst.insert(0, 'a')\nassert lst == ['a', 1, 2, 3]\n\nlst = [1, 2, 3]\nlst.insert(1, 'a')\nassert lst == [1, 'a', 2, 3]\n\nlst = [1, 2, 3]\nlst.insert(3, 'a')\nassert lst == [1, 2, 3, 'a']\n\n# Insert beyond length appends\nlst = [1, 2, 3]\nlst.insert(100, 'a')\nassert lst == [1, 2, 3, 'a']\n\n# Insert with negative index\nlst = [1, 2, 3]\nlst.insert(-1, 'a')\nassert lst == [1, 2, 'a', 3]\n\nlst = [1, 2, 3]\nlst.insert(-2, 'a')\nassert lst == [1, 'a', 2, 3]\n\nlst = [1, 2, 3]\nlst.insert(-100, 'a')\nassert lst == ['a', 1, 2, 3]\n\n# === list.pop() ===\nlst = [1, 2, 3]\nassert lst.pop() == 3\nassert lst == [1, 2]\n\nlst = [1, 2, 3]\nassert lst.pop(0) == 1\nassert lst == [2, 3]\n\nlst = [1, 2, 3]\nassert lst.pop(1) == 2\nassert lst == [1, 3]\n\nlst = [1, 2, 3]\nassert lst.pop(-1) == 3\nassert lst == [1, 2]\n\nlst = [1, 2, 3]\nassert lst.pop(-2) == 2\nassert lst == [1, 3]\n\n# === list.remove() ===\nlst = [1, 2, 3, 2]\nlst.remove(2)\nassert lst == [1, 3, 2]\n\nlst = ['a', 'b', 'c']\nlst.remove('b')\nassert lst == ['a', 'c']\n\n# === list.clear() ===\nlst = [1, 2, 3]\nlst.clear()\nassert lst == []\n\nlst = []\nlst.clear()\nassert lst == []\n\n# === list.copy() ===\nlst = [1, 2, 3]\ncopy = lst.copy()\nassert copy == [1, 2, 3]\nassert copy is not lst\nlst.append(4)\nassert copy == [1, 2, 3]\n\n# === list.extend() ===\nlst = [1, 2]\nlst.extend([3, 4])\nassert lst == [1, 2, 3, 4]\n\nlst = [1]\nlst.extend((2, 3))\nassert lst == [1, 2, 3]\n\nlst = [1]\nlst.extend(range(2, 5))\nassert lst == [1, 2, 3, 4]\n\nlst = [1]\nlst.extend('ab')\nassert lst == [1, 'a', 'b']\n\nlst = []\nlst.extend([])\nassert lst == []\n\n# === list.index() ===\nlst = [1, 2, 3, 2]\nassert lst.index(2) == 1\nassert lst.index(3) == 2\nassert lst.index(2, 2) == 3\nassert lst.index(2, 1, 4) == 1\n\n# Regression: `-index` on i64::MIN used to panic when normalising start/end\n_I64_MIN = -(2**63)\nassert lst.index(1, _I64_MIN) == 0\nassert lst.index(2, _I64_MIN, 4) == 1\n\n# === list.count() ===\nlst = [1, 2, 2, 3, 2]\nassert lst.count(2) == 3\nassert lst.count(1) == 1\nassert lst.count(4) == 0\nassert [].count(1) == 0\n\n# === list.reverse() ===\nlst = [1, 2, 3]\nlst.reverse()\nassert lst == [3, 2, 1]\n\nlst = [1]\nlst.reverse()\nassert lst == [1]\n\nlst = []\nlst.reverse()\nassert lst == []\n\n# === list.sort() ===\nlst = [3, 1, 2]\nlst.sort()\nassert lst == [1, 2, 3]\n\nlst = ['b', 'c', 'a']\nlst.sort()\nassert lst == ['a', 'b', 'c']\n\nlst = [3, 1, 2]\nlst.sort(reverse=True)\nassert lst == [3, 2, 1]\n\nlst = []\nlst.sort()\nassert lst == []\n\nlst = [1]\nlst.sort()\nassert lst == [1]\n\n# === list.sort(key=...) ===\nlst = ['banana', 'apple', 'cherry']\nlst.sort(key=len)\nassert lst == ['apple', 'banana', 'cherry']\n\nlst = [[1, 2, 3], [4], [5, 6]]\nlst.sort(key=len)\nassert lst == [[4], [5, 6], [1, 2, 3]]\n\nlst = [[1, 2, 3], [4], [5, 6]]\nlst.sort(key=len, reverse=True)\nassert lst == [[1, 2, 3], [5, 6], [4]]\n\nlst = [-3, 1, -2, 4]\nlst.sort(key=abs)\nassert lst == [1, -2, -3, 4]\n\n# key=None is same as no key\nlst = [3, 1, 2]\nlst.sort(key=None)\nassert lst == [1, 2, 3]\n\nlst = [3, 1, 2]\nlst.sort(key=None, reverse=True)\nassert lst == [3, 2, 1]\n\n# Empty list with key\nlst = []\nlst.sort(key=len)\nassert lst == []\n\n# key=int for string-to-int conversion\nlst = ['-3', '1', '-2', '4']\nlst.sort(key=int)\nassert lst == ['-3', '-2', '1', '4']\n\nlst = ['10', '2', '1', '100']\nlst.sort(key=int)\nassert lst == ['1', '2', '10', '100']\n\nlst = ['10', '2', '1', '100']\nlst.sort(key=int, reverse=True)\nassert lst == ['100', '10', '2', '1']\n\n# user-defined key function\n\n\ndef last_char(s):\n    return s[-1]\n\n\nlst = ['cherry', 'banana', 'apple']\nlst.sort(key=last_char)\nassert lst == ['banana', 'apple', 'cherry']\n\n\n# key function might raise exception\nlst = ['']\ntry:\n    lst.sort(key=last_char)\nexcept IndexError:\n    pass  # expected since last_char('') raises IndexError\n\n\n# === list.sort() reentrant mutation by key callback (issue #411) ===\n# CPython detaches the list during sort so reentrant access sees an empty\n# list. If the user re-populates the live list, sort raises ValueError after\n# restoring the detached (sorted) buffer.\n\n# Key callback observes empty list during sort\nxs1 = [3, 2, 1]\n\n\ndef empty_key(value):\n    assert len(xs1) == 0\n    return value\n\n\nxs1.sort(key=empty_key)\nassert xs1 == [1, 2, 3]\n\n# Repopulating the list during sort must raise ValueError\nxs2 = [3, 2, 1]\n\n\ndef repopulate_key(value):\n    xs2.append(99)\n    return value\n\n\ntry:\n    xs2.sort(key=repopulate_key)\n    assert False, 'expected ValueError when key callback repopulates the list'\nexcept ValueError as exc:\n    assert str(exc) == 'list modified during sort'\nassert xs2 == [1, 2, 3]\n\n\n# === List assignment (setitem) ===\n# Basic assignment\nlst = [1, 2, 3]\nlst[0] = 10\nassert lst == [10, 2, 3]\n\nlst = [1, 2, 3]\nlst[1] = 20\nassert lst == [1, 20, 3]\n\nlst = [1, 2, 3]\nlst[2] = 30\nassert lst == [1, 2, 30]\n\n# Negative index assignment\nlst = [1, 2, 3]\nlst[-1] = 100\nassert lst == [1, 2, 100]\n\nlst = [1, 2, 3]\nlst[-2] = 200\nassert lst == [1, 200, 3]\n\nlst = [1, 2, 3]\nlst[-3] = 300\nassert lst == [300, 2, 3]\n\n# Assigning different types\nlst = [1, 2, 3]\nlst[0] = 'hello'\nassert lst == ['hello', 2, 3]\n\nlst = [1, 2, 3]\nlst[1] = [4, 5]\nassert lst == [1, [4, 5], 3]\n\nlst = [1, 2, 3]\nlst[0] = None\nassert lst == [None, 2, 3]\n\n# Multiple assignments\nlst = [0, 0, 0]\nlst[0] = 1\nlst[1] = 2\nlst[2] = 3\nassert lst == [1, 2, 3]\n\n# Assignment preserves other elements\nlst = ['a', 'b', 'c', 'd']\nlst[1] = 'B'\nassert lst[0] == 'a'\nassert lst[1] == 'B'\nassert lst[2] == 'c'\nassert lst[3] == 'd'\n\n# === Bool indices ===\n# Python allows True/False as indices (True=1, False=0)\nlst = ['a', 'b', 'c']\nassert lst[False] == 'a'\nassert lst[True] == 'b'\n\nlst = ['x', 'y', 'z']\nlst[False] = 'X'\nassert lst == ['X', 'y', 'z']\n\nlst = ['x', 'y', 'z']\nlst[True] = 'Y'\nassert lst == ['x', 'Y', 'z']\n\n# === Nested list equality ===\n# same-length lists with matching nested elements\nassert [[1, 2], [3, 4]] == [[1, 2], [3, 4]]\n# same-length but different nested elements (exercises py_eq early return)\nassert [[1, 2], [3, 4]] != [[1, 2], [3, 5]]\nassert [[]] != [[1]]\n# deeper nesting\nassert [[[1]]] == [[[1]]]\nassert [[[1]]] != [[[2]]]\n# mixed nesting depths\nassert [[1], 2] == [[1], 2]\nassert [[1], 2] != [[1], 3]\n\n# === Nested list repr ===\nassert repr([[1, 2], [3, 4]]) == '[[1, 2], [3, 4]]'\nassert repr([[]]) == '[[]]'\nassert repr([[1], [2, 3]]) == '[[1], [2, 3]]'\n\n# === list.remove() with nested elements ===\nx = [1, 2]\nlst = [x, [3, 4], x]\nlst.remove([1, 2])\nassert lst == [[3, 4], [1, 2]]\n\nlst = [1, [2, 3], 4]\nlst.remove([2, 3])\nassert lst == [1, 4]\n\n# === list.index() with nested elements ===\nlst = [[3], [1, 2], [4]]\nassert lst.index([1, 2]) == 1\n\nlst = [[1], [2], [1]]\nassert lst.index([1]) == 0\n\n# === list.count() with nested elements ===\nlst = [[1, 2], [3], [1, 2], 4, [1, 2]]\nassert lst.count([1, 2]) == 3\nassert lst.count([3]) == 1\nassert lst.count([99]) == 0\nassert [].count([1]) == 0\n\n# === Nested list containment ===\nassert [1, 2] in [[1, 2], [3, 4]]\nassert [5, 6] not in [[1, 2], [3, 4]]\nassert [] in [[], [1]]\n\n# === List unpacking (PEP 448) ===\na = [1, 2]\nb = [3, 4]\nassert [*a] == [1, 2]\nassert [*a, *b] == [1, 2, 3, 4]\nassert [0, *a, 5] == [0, 1, 2, 5]\nassert [*[]] == []\nassert [*(1, 2)] == [1, 2]\nassert [*'abc'] == ['a', 'b', 'c']\nassert [*{'x': 1, 'y': 2}] == ['x', 'y']\n# Heap-allocated set: covers the HeapData::Set arm in list_extend\nassert sorted([*{1, 2, 3}]) == [1, 2, 3]\n# Heap-allocated Str (result of concat, not interned): covers HeapData::Str in list_extend\nhs = 'hel' + 'lo'\nassert [*hs] == ['h', 'e', 'l', 'l', 'o']\n\n\n# Non-iterable heap-allocated Ref (closure) hits the inner `_` arm in list_extend.\n# A plain top-level function is Value::DefFunction (not a Ref), so a closure is\n# required to reach the Value::Ref(_) branch (HeapData that is not List/Tuple/Set/Dict/Str).\ndef _make_list_unpack_closure():\n    _sentinel = 1\n\n    def _inner():\n        return _sentinel\n\n    return _inner\n\n\n_list_unpack_closure = _make_list_unpack_closure()\ntry:\n    _x = [*_list_unpack_closure]\n    assert False, 'expected TypeError for non-iterable heap closure in list unpack'\nexcept TypeError:\n    pass\n\n# === Nested subscript assignment ===\na = [[1, 2, 3], [4, 5, 6]]\na[0][2] = 99\nassert a[0][2] == 99\nassert a == [[1, 2, 99], [4, 5, 6]]\n\n# === Nested subscript augmented assignment ===\na = [[1, 2, 3]]\na[0][2] += 1\nassert a == [[1, 2, 4]]\n\na = [[10, 20], [30, 40]]\na[1][0] -= 5\nassert a == [[10, 20], [25, 40]]\n\n# === Triple nesting ===\na = [[[0]]]\na[0][0][0] = 7\nassert a[0][0][0] == 7\n\na = [[[10]]]\na[0][0][0] += 1\nassert a[0][0][0] == 11\n\n# === Mixed dict-list nesting ===\nd = {'k': [1, 2, 3]}\nd['k'][0] = 100\nassert d['k'] == [100, 2, 3]\n\nd = {'k': [1, 2, 3]}\nd['k'][0] += 100\nassert d['k'] == [101, 2, 3]\n\n# === Nested dict assignment ===\nd = {'a': {'x': 1, 'y': 2}}\nd['a']['y'] = 42\nassert d['a']['y'] == 42\n\nd = {'a': {'x': 1}}\nd['a']['x'] += 10\nassert d['a']['x'] == 11\n\n# === Eval-once semantics for augmented subscript assignment ===\n# CPython evaluates the container and index expressions exactly once,\n# in left-to-right order. Verify Monty matches this behavior.\n_eval_log = []\n\n\ndef _tracking_obj():\n    _eval_log.append('obj')\n    return [10, 20, 30]\n\n\ndef _tracking_index():\n    _eval_log.append('idx')\n    return 1\n\n\n_tracking_obj()[_tracking_index()] += 100\nassert _eval_log == ['obj', 'idx'], f'eval-once order: {_eval_log}'\n\n# Also verify the assignment itself is correct (even though the list is temporary)\n_result_list = [10, 20, 30]\n_eval_log.clear()\n\n\ndef _tracking_obj2():\n    _eval_log.append('obj')\n    return _result_list\n\n\ndef _tracking_index2():\n    _eval_log.append('idx')\n    return 2\n\n\n_tracking_obj2()[_tracking_index2()] += 7\nassert _eval_log == ['obj', 'idx'], f'eval-once order with persistent list: {_eval_log}'\nassert _result_list == [10, 20, 37], f'augmented assign via function: {_result_list}'\n",
