  'loop__break_continue.py':
      "# === Basic break ===\nresult = []\nfor x in [1, 2, 3, 4, 5]:\n    if x == 3:\n        break\n    result.append(x)\nassert result == [1, 2]\n\n# === Break skips else ===\nflag = 0\nfor x in [1, 2, 3]:\n    if x == 2:\n        break\nelse:\n    flag = 1\nassert flag == 0\n\n# === No break runs else ===\nflag = 0\nfor x in [1, 2, 3]:\n    pass\nelse:\n    flag = 1\nassert flag == 1\n\n# === Basic continue ===\nresult = []\nfor x in [1, 2, 3, 4, 5]:\n    if x % 2 == 0:\n        continue\n    result.append(x)\nassert result == [1, 3, 5]\n\n# === Continue with else ===\nflag = 0\nfor x in [1, 2, 3]:\n    if x == 2:\n        continue\nelse:\n    flag = 1\nassert flag == 1\n\n# === Nested loops - break inner ===\nresult = []\nfor i in [1, 2, 3]:\n    for j in ['a', 'b', 'c']:\n        if j == 'b':\n            break\n        result.append((i, j))\nassert result == [(1, 'a'), (2, 'a'), (3, 'a')]\n\n# === Nested loops - continue inner ===\nresult = []\nfor i in [1, 2]:\n    for j in ['a', 'b', 'c']:\n        if j == 'b':\n            continue\n        result.append((i, j))\nassert result == [(1, 'a'), (1, 'c'), (2, 'a'), (2, 'c')]\n\n# === Break in nested with else on inner ===\nresult = []\nfor i in [1, 2]:\n    for j in [10, 20, 30]:\n        if j == 20:\n            break\n        result.append(j)\n    else:\n        result.append('inner-else')\nassert result == [10, 10]\n\n# === No break in inner runs inner else ===\nresult = []\nfor i in [1, 2]:\n    for j in [10, 20]:\n        result.append(j)\n    else:\n        result.append('inner-else')\nassert result == [10, 20, 'inner-else', 10, 20, 'inner-else']\n\n# === Continue does not affect else ===\nresult = []\nfor x in [1, 2, 3]:\n    if x == 2:\n        continue\n    result.append(x)\nelse:\n    result.append('else')\nassert result == [1, 3, 'else']\n\n# === Empty loop with else ===\nflag = 0\nfor x in []:\n    flag = 1\nelse:\n    flag = 2\nassert flag == 2\n\n# === Break on first iteration ===\nresult = []\nfor x in [1, 2, 3]:\n    result.append('before')\n    break\n    result.append('after')  # unreachable\nassert result == ['before']\n\n\n# === Double break (unreachable second break) ===\ndef double_break(value):\n    for i in range(0, 1):\n        break\n        break\n    return value\n\n\nassert double_break('hello') == 'hello'\nassert double_break(42) == 42\n\n\n# === Two breaks in different branches (both reachable) ===\ndef two_breaks(items):\n    result = []\n    for x in items:\n        if x < 0:\n            result.append('negative')\n            break\n        if x > 100:\n            result.append('too big')\n            break\n        result.append(x)\n    return result\n\n\nassert two_breaks([1, 2, 3]) == [1, 2, 3]\nassert two_breaks([1, -1, 3]) == [1, 'negative']\nassert two_breaks([1, 200, 3]) == [1, 'too big']\nassert two_breaks([-5]) == ['negative']\nassert two_breaks([999]) == ['too big']\n\n\n# === Double continue (unreachable second continue) ===\ndef double_continue(items):\n    out = []\n    for x in items:\n        out.append(x)\n        continue\n        continue\n    return out\n\n\nassert double_continue([1, 2, 3]) == [1, 2, 3]\nassert double_continue([]) == []\n\n# === Continue on every iteration ===\nresult = []\nfor x in [1, 2, 3]:\n    result.append(x)\n    continue\n    result.append('after')  # unreachable\nassert result == [1, 2, 3]\n",
  'loop__break_finally.py':
      "# === Break in try/finally must run finally ===\nresult = []\nfor x in [1, 2, 3]:\n    try:\n        result.append('before')\n        break\n        result.append('after')  # unreachable\n    finally:\n        result.append('finally')\nassert result == ['before', 'finally'], f'break in try/finally should run finally: {result}'\n\n# === Break in nested try/finally runs both finally blocks ===\nresult = []\nfor x in [1, 2, 3]:\n    try:\n        try:\n            result.append('inner-try')\n            break\n        finally:\n            result.append('inner-finally')\n    finally:\n        result.append('outer-finally')\nassert result == ['inner-try', 'inner-finally', 'outer-finally'], f'nested finally blocks: {result}'\n\n# === Break in try/except/finally runs finally ===\nresult = []\nfor x in [1, 2, 3]:\n    try:\n        result.append('try')\n        break\n    except ValueError:\n        result.append('except')\n    finally:\n        result.append('finally')\nassert result == ['try', 'finally'], f'break in try/except/finally: {result}'\n\n# === Break inside except handler with finally ===\nresult = []\nfor x in [1, 2, 3]:\n    try:\n        raise ValueError('test')\n    except ValueError:\n        result.append('except')\n        break\n    finally:\n        result.append('finally')\nassert result == ['except', 'finally'], f'break in except with finally: {result}'\n\n# === Break does not run finally if not in try ===\nresult = []\nfor x in [1, 2, 3]:\n    result.append('body')\n    break\nassert result == ['body'], f'break without finally: {result}'\n\n# === Break with multiple loops and finally ===\nresult = []\nfor i in [1, 2]:\n    try:\n        for j in [10, 20, 30]:\n            if j == 20:\n                break  # This break should not trigger outer finally\n            result.append(j)\n        result.append('after-inner')\n    finally:\n        result.append('outer-finally')\nassert result == [10, 'after-inner', 'outer-finally', 10, 'after-inner', 'outer-finally'], (\n    f'inner break with outer finally: {result}'\n)\n",
