  'tuple__methods.py':
      "# === tuple.index() ===\nt = (1, 2, 3, 2)\nassert t.index(2) == 1\nassert t.index(3) == 2\nassert t.index(2, 2) == 3\nassert t.index(2, 1, 4) == 1\n\n# Regression: `-index` on i64::MIN used to panic when normalising start/end\n_I64_MIN = -(2**63)\nassert t.index(1, _I64_MIN) == 0\nassert t.index(2, _I64_MIN, 4) == 1\n\nt = ('a', 'b', 'c')\nassert t.index('b') == 1\n\n# === tuple.count() ===\nt = (1, 2, 2, 3, 2)\nassert t.count(2) == 3\nassert t.count(1) == 1\nassert t.count(4) == 0\nassert ().count(1) == 0\n\nt = ('a', 'b', 'a')\nassert t.count('a') == 2\n",
  'tuple__ops.py':
      "# === Empty tuple identity (singleton optimization) ===\n# In Python, () is () is always True because empty tuples are interned\nassert () is ()\nassert tuple() is ()\nassert tuple() is tuple()\na = ()\nb = ()\nassert a is b\n# Empty tuple from operations\nassert (1,)[1:] is ()\nassert (1, 2) * 0 is ()\n\n# === Tuple length ===\nassert len(()) == 0\nassert len((1,)) == 1\nassert len((1, 2, 3)) == 3\n\n# === Tuple indexing ===\na = (1, 2, 3)\nassert a[1] == 2\n\na = ('a', 'b', 'c')\nassert a[0 - 2] == 'b'\nassert a[-1] == 'c'\n\n# === Nested tuples ===\nassert ((1, 2), (3, 4)) == ((1, 2), (3, 4))\n\n# === Tuple repr/str ===\nassert repr((1, 2)) == '(1, 2)'\nassert str((1, 2)) == '(1, 2)'\n\n# === Tuple concatenation (+) ===\nassert (1, 2) + (3, 4) == (1, 2, 3, 4)\nassert () + (1, 2) == (1, 2)\nassert (1, 2) + () == (1, 2)\nassert () + () == ()\nassert ('a', 'b') + ('c',) == ('a', 'b', 'c')\nassert ((1, 2),) + ((3, 4),) == ((1, 2), (3, 4))\n\n# === Tuple repetition (*) ===\nassert (1, 2) * 3 == (1, 2, 1, 2, 1, 2)\nassert 3 * (1, 2) == (1, 2, 1, 2, 1, 2)\nassert (1,) * 0 == ()\nassert (1,) * -1 == ()\nassert () * 5 == ()\nassert (1, 2) * 1 == (1, 2)\n\n# === Tuple augmented assignment edge cases ===\nt = ([1],)\ntry:\n    t[0] += [2]\n    assert False, 'tuple item augmented assignment should fail'\nexcept TypeError as e:\n    assert e.args == (\"'tuple' object does not support item assignment\",)\n    assert t == ([1, 2],)\n\n# === tuple() constructor ===\nassert tuple() == ()\nassert tuple([1, 2, 3]) == (1, 2, 3)\nassert tuple((1, 2, 3)) == (1, 2, 3)\nassert tuple(range(3)) == (0, 1, 2)\nassert tuple('abc') == ('a', 'b', 'c')\nassert tuple(b'abc') == (97, 98, 99)\nassert tuple({'a': 1, 'b': 2}) == ('a', 'b')\n\n# non-ASCII strings (multi-byte UTF-8)\nassert tuple('héllo') == ('h', 'é', 'l', 'l', 'o')\nassert tuple('日本') == ('日', '本')\nassert tuple('a🎉b') == ('a', '🎉', 'b')\n\n# === Tuple unpacking (PEP 448) ===\na = (1, 2)\nb = (3, 4)\nassert (*a,) == (1, 2)\nassert (*a, *b) == (1, 2, 3, 4)\nassert (0, *a, 5) == (0, 1, 2, 5)\nassert (*(),) == ()\nassert (*[1, 2],) == (1, 2)\n\n# === Tuple comparison (<, >, <=, >=) ===\nassert (1, 2) < (1, 3)\nassert (1,) < (2,)\nassert () < (1,)\nassert (1, 2) < (1, 2, 3)\nassert not (1, 2) < (1, 2), 'not lt when equal'\nassert not (1, 3) < (1, 2), 'not lt when greater'\n\nassert (1, 3) > (1, 2)\nassert (2,) > (1,)\nassert (1,) > ()\nassert (1, 2, 3) > (1, 2)\nassert not (1, 2) > (1, 2), 'not gt when equal'\n\nassert (1, 2) <= (1, 2)\nassert (1, 2) <= (1, 3)\nassert not (1, 3) <= (1, 2), 'not le when greater'\n\nassert (1, 2) >= (1, 2)\nassert (1, 3) >= (1, 2)\nassert not (1, 2) >= (1, 3), 'not ge when less'\n\n# === Tuple comparison with sorted() ===\nassert sorted([(2, 'b'), (1, 'a')]) == [(1, 'a'), (2, 'b')]\nassert sorted([(1, 'b'), (1, 'a')]) == [(1, 'a'), (1, 'b')]\nassert sorted([(3,), (1,), (2,)]) == [(1,), (2,), (3,)]\n\n# === Nested tuple comparison ===\nassert ((1, 2), 3) < ((1, 3), 2)\nassert (1, (2, 3)) < (1, (2, 4))\n\n# === Equal-but-unorderable elements (None, lists, dicts) ===\n# CPython checks __eq__ first; equal elements skip ordering comparison\nassert not (1, None) < (1, None), 'equal None elements not lt'\nassert (1, None) <= (1, None)\nassert (1, None) >= (1, None)\nassert not (1, None) > (1, None), 'equal None elements not gt'\nassert (1, None) < (2, None)\nassert (1, [1, 2]) <= (1, [1, 2])\n\n# === Mixed types in tuple comparison ===\nassert (1,) < (2.0,)\nassert (1.0,) < (2,)\nassert (True,) < (2,)\nassert (False,) < (True,)\nassert (1, 'a') < (1, 'b')\nassert ('a', 1) < ('b', 1)\n\n# === Empty and equal tuples ===\nassert not () < (), 'empty tuples not lt'\nassert () <= ()\nassert () >= ()\nassert not () > (), 'empty tuples not gt'\n\n# === Tuple reprs ===\nassert repr(()) == '()'\nassert repr((1,)) == '(1,)'\nassert repr((1, 2)) == '(1, 2)'\nassert repr((1, (2, 3))) == '(1, (2, 3))'\n",
