  'unpack__nested.py':
      "# Test nested tuple unpacking\n\n# === Basic nested unpacking ===\ndata = ((1, 2), 'x')\n(a, b), c = data\nassert a == 1\nassert b == 2\nassert c == 'x'\n\n# === Deeply nested ===\n((a, b), (c, d)) = ((1, 2), (3, 4))\nassert a == 1\nassert b == 2\nassert c == 3\nassert d == 4\n\n# === Mixed depths ===\n(a, (b, c)) = (1, (2, 3))\nassert a == 1\nassert b == 2\nassert c == 3\n\n# === Three levels deep ===\n(a, (b, (c, d))) = (1, (2, (3, 4)))\nassert a == 1\nassert b == 2\nassert c == 3\nassert d == 4\n\n# === In for loops ===\nitems = [((1, 2), 'a'), ((3, 4), 'b')]\nsums = []\nletters = []\nfor (a, b), c in items:\n    sums.append(a + b)\n    letters.append(c)\nassert sums == [3, 7]\nassert letters == ['a', 'b']\n\n# === In comprehensions ===\nitems = [((1, 2), 'a'), ((3, 4), 'b')]\nresult = [a + b for (a, b), c in items]\nassert result == [3, 7]\n\n# === Deep nested in comprehension ===\nitems = [((1, 2), (3, 4)), ((5, 6), (7, 8))]\nresult = [a + b + c + d for (a, b), (c, d) in items]\nassert result == [10, 26]\n",
