  'unpack__ops.py':
      "# === Basic tuple unpacking ===\na, b = (1, 2)\nassert a == 1\nassert b == 2\n\n# === Unpacking without parentheses ===\nx, y = 10, 20\nassert x == 10\nassert y == 20\n\n# === Three element unpacking ===\na, b, c = (1, 2, 3)\nassert a == 1\nassert b == 2\nassert c == 3\n\n\n# === Unpacking from function return ===\ndef returns_pair():\n    return 42, 37\n\n\nx, y = returns_pair()\nassert x == 42\nassert y == 37\n\n\ndef returns_triple():\n    return 'a', 'b', 'c'\n\n\np, q, r = returns_triple()\nassert p == 'a'\nassert q == 'b'\nassert r == 'c'\n\n# === Unpacking list ===\na, b = [100, 200]\nassert a == 100\nassert b == 200\n\na, b, c, d = [1, 2, 3, 4]\nassert a == 1\nassert d == 4\n\n# === Unpacking string ===\na, b = 'xy'\nassert a == 'x'\nassert b == 'y'\n\np, q, r = 'abc'\nassert p == 'a'\nassert q == 'b'\nassert r == 'c'\n\n# === Unpacking with different value types ===\na, b = (True, False)\nassert a is True\nassert b is False\n\na, b = (1.5, 2.5)\nassert a == 1.5\nassert b == 2.5\n\na, b = (None, 42)\nassert a is None\nassert b == 42\n\n# === Unpacking with nested containers ===\na, b = ([1, 2], [3, 4])\nassert a == [1, 2]\nassert b == [3, 4]\n\na, b = ((1, 2), (3, 4))\nassert a == (1, 2)\nassert b == (3, 4)\n\n# === Reassignment via unpacking ===\nx = 1\ny = 2\nx, y = y, x\nassert x == 2\nassert y == 1\n\n# === Single element tuple (edge case) ===\n# Note: (x,) = (1,) is valid Python\n(a,) = (42,)\nassert a == 42\n\n(a,) = [99]\nassert a == 99\n\n(a,) = 'z'\nassert a == 'z'\n\n# === Star unpacking (extended unpacking) ===\n# Star at end\nfirst, *rest = [1, 2, 3, 4, 5]\nassert first == 1\nassert rest == [2, 3, 4, 5]\n\n# Star at start\n*init, last = [1, 2, 3, 4, 5]\nassert init == [1, 2, 3, 4]\nassert last == 5\n\n# Star in middle\nfirst, *middle, last = [1, 2, 3, 4, 5]\nassert first == 1\nassert middle == [2, 3, 4]\nassert last == 5\n\n# Empty rest (minimum values)\nfirst, *rest, last = [1, 2]\nassert first == 1\nassert rest == []\nassert last == 2\n\n# From tuple\na, *b = (10, 20, 30)\nassert a == 10\nassert b == [20, 30]\n\n# From string\nfirst, *mid, last = 'abcde'\nassert first == 'a'\nassert mid == ['b', 'c', 'd']\nassert last == 'e'\n\n# With more targets before star\na, b, c, *rest = [1, 2, 3, 4, 5, 6]\nassert a == 1\nassert b == 2\nassert c == 3\nassert rest == [4, 5, 6]\n\n# With more targets after star\n*init, x, y, z = [1, 2, 3, 4, 5, 6]\nassert init == [1, 2, 3]\nassert x == 4\nassert y == 5\nassert z == 6\n\n# Star captures all but one\nhead, *tail = [1]\nassert head == 1\nassert tail == []\n\n# Star with bracket syntax\n[a, *b, c] = [1, 2, 3, 4]\nassert a == 1\nassert b == [2, 3]\nassert c == 4\n",
